/* 令和3年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r03.committeeSessions.push(...[{"id":"r03-20210608-14","meetingId":"r03-cm06","date":"2021年6月8日","dateIso":"2021-06-08","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時０１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"あくつ委員","kind":"意見","question":"公明党のあくつ広王です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"石田（ち）委員","kind":"確認","question":"今ご説明いただいたところで、確認等々させていただけたらと思うのですが、区有施設、公有地等の活用のところで、旧都営住宅元芝アパートの現況等というところに「『都意向調査』回答」とあるのですけれども、先ほどそれを待っているとおっしゃったのですか。","respondent":"佐藤企画調整課長、濱中庁舎計画担当課長、大澤広報広聴課長","answer":"１つ目のご質問の元芝アパートの状況ですが、区から都に対して意向調査のほうを回答して、都からの反応を待っているということで、言葉が足りずすみません。区民アンケートの抽出方法です、層化２段無作為抽出法ですが、地域の人口の比率に合わせ、その比率が公平に分配されるような形で抽出をして。広報媒体についての課題ですけれども、今、例えば広報しながわのような紙媒体とホームページのようなインターネットを使った発信と両方をやっておりますが。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。庁舎のアンケートのところなのですけれども、２段というのは、要は１段目がどういうことで２段目があるのか。イメージがつかなくて。地域の人口比率に合わせて取っていくということは分かったのですが、層化というのが分かりづらいのですけれども、もう一度いいですか。","respondent":"濱中庁舎計画担当課長","answer":"５地域を中心に８地域の人口比率に応じて、それに応じた形で抽出をしまして郵送していくという方法です。こちら、区の世論調査と同じ抽出方法でやらせていただきます。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"新庁舎整備の基本構想・基本計画策定についてというところで１点だけ。これはやるかどうかは別にして、例えば電子表決とか、電源をどうしていくのかとか、当然一問一答方式とかソフトの部分とハードの部分は非常に関係するので、一概には言えない部分があるのですけれども、そういうものをできるだけ資料として提示をしていただいて、活発な議論をさせていただきたいなと思うのですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問・要望","question":"何点かお伺いしたいと思います。このテレワークの活用と、自治体の業務ですとＬＧＷＡＮとの関係というものも出てくるかと思いますが、それで当初テレワークがなかなかやりにくかったと思うのですけれども、このＬＧＷＡＮ、あるいは、閉じた３層構造とのテレワークの可能性ということで、今どういう仕組みで動いていらして、それをどうやって拡大するのかということを教えていただければと思います。","respondent":"佐藤企画調整課長、濱中庁舎計画担当課長、宮澤情報推進課長","answer":"３番の元芝アパートに関しましては都有地ですので、都の回答を待っていると。４番の平塚二丁目寄付物件に関しましては、令和８年度までの予定です。次世代を担う子どもたちも使う庁舎ですので、関係部署とも連携をしながら、子どもたちの意見を聞けるような方法を検討してまいります。職員の業務を行うネットワーク層というのがＬＧＷＡＮ環境になりますけれども、そこへのリモートでのアクセスというのができなかったところではありますが。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"それぞれありがとうございました。最初の質問の中で、そうすると、今、貸付け中のものというのは、逆に第一日野小学校跡地だけということでよろしいのでしょうか。私のほうは例示として挙げただけなのですけれども、特にそれ以外はないということでしたか。","respondent":"佐藤企画調整課長","answer":"お尋ねの区有地を民間等々に貸付けている用地というのは、今現在、第一日野小学校跡地のみというところで理解しています。","id":"exchange-006"},{"speaker":"せお委員","kind":"質問・要望","question":"１点だけ。今お話のあった区有施設、公有地等の活用に関することなのですけれども、ここのそれぞれの場所について、次にこちらの委員会で報告されるのはそれぞれどういう状況で、どういう時点での報告になるのか、教えていただきたい。これは分からないのですけれども、理事者に聞いていいのですか。正副委員長なのか、すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"せお委員","kind":"質問","question":"旧荏原第四中学校とか、清掃作業所とかのそれぞれの段階についてもこちらで話してからということでよろしいですか。その他のところでお話しするということですか。細かい状況についても、一旦その他でお話ししてからという状況になるのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問・要望","question":"当然この１年で完結するような話ではないというふうになるわけですけれども、この１年間で、行財政改革特別委員会でどのぐらいの内容を、スケジュール感といいますか、どのぐらいのことがこの１年間で、国あるいは品川区のほうで進めようとしているところなのかというのを、確認させていただきたいのですが。","respondent":"宮澤情報推進課長","answer":"この夏頃に国から具体的なスケジュールというものが示されてくるというところがありますので、まだ今の時点ではなかなか詳細なところというのは出ておりませんが、恐らくは第１、第２という形で。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"２段構えとおっしゃったのは、第１回、第２回というのが、この年度内に出てくるというようなことでよろしいのでしょうか。","respondent":"宮澤情報推進課長","answer":"失礼しました。２段構えが今年度中に出てくるかどうかはまだ示されておりません。２段階と言ったのも、１７業務を、恐らく２つに分かれるのですが、それぞれの２段のタイミングで同時に出てくるかどうかもまだ示されていないので、そこは夏の国の動向を注視している状況です。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"すみません。追加で１点。そこを取り入れていく予定があるか。取り入れていっていただきたいと思っているのですけれども、そこだけ１点確認させてください。","respondent":"濱中庁舎計画担当課長","answer":"新庁舎に関しまして、ユニバーサルデザインのご意見を頂きまして、今後、ユニバーサルデザインとしましては、まずバリアフリー化等のハードや、また案内サインの表示なども含めて、ユニバーサルデザインの検討を深めていきたいと考えています。","id":"exchange-011"},{"speaker":"芹澤委員","kind":"質問","question":"デジタル化について１点だけお伺いしますが、以前、決算特別委員会かどこかで伺ったのですけれども、デジタル化とかＩＣＴ化の基本計画というのを２３区のほとんどがつくっていて、品川区がまだできていないというのをお話ししたときに、前向きに検討するというようなお話があって、この資料を見る限りでは、どのスケジュール感でどこまでやっていくかというのがまだ決まっていないように思うのですが。","respondent":"宮澤情報推進課長","answer":"デジタル化を進めていくにあたっての体制というところで、この４月に情報推進課の中に情報戦略担当というのを新設いたしました。進めていくにあたってのビジョン、計画につきましても、現在検討しているという状況です。","id":"exchange-012"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"まとめて伺います。質問項目以外に多分意見もあると思うので、ぜひ設けていただきたいと思うのですが、いかがかということと、意見募集のほうはいつからやるのかということと、どのように周知されていくのかということを伺いたいと思います。そうしたことがないようにしていくべきだと思うのですけれども、区の考えを伺いたい。","respondent":"佐藤企画調整課長、濱中庁舎計画担当課長、宮澤情報推進課長","answer":"地域の要望といたしまして、防災的な避難所や地域利用の希望もありますので、その点も踏まえながら、今現在。今後、広報しながわにおきましても、意見募集フォームをやっているということを周知いたしまして、区民の意見をお伺いしていきたいと考えています。これらを国が定める標準仕様にすることによりまして、今までできていたことが仕様が変わることによってできなくなるというようなこともありますが。","id":"exchange-013"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"旧荏原第四中学校のところは、今、検討中ということで、今後委員会でも示されるということですので、ぜひ住民参加でいろいろ検討会などもやりながら、住民要望を叶える施設検討をしていっていただきたいと思います。システムの標準化のところでは、今までやってきたことができなくなることもあるということですが、ぜひ、そういったことがないようにしていただきたいというふうに要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"新庁舎については、庁舎が古くなれば建て替えも必要になってくると思いますので、建て替えというのはあるだろうと思います。それでも現庁舎があと１５年もちます。現在の新庁舎の検討が、ＪＲの開発計画と一体に進められていますので、開発とは切り離して考えていくべきだと思っています。そうした点も含めて、多くの区民の声を聞いていくべきだと思います。少し抽象的ですが、以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問","question":"今の共産党の話なのですけれども、いつもそういう内容のことをおっしゃるのです。１５年もつと。そうすると、この議論を始めるのに適正な時期というのは、共産党はいつからとお考えになっているのですか。１５年後にはもう駄目だということを、先ほどご自身でもおっしゃっているのですけれども、いつぐらいが適当だと思いますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"意見","question":"世田谷区などは１０年かけて住民参加で、そして情報公開で、そして低層なのか高層なのか、どういう庁舎にするのかというものを区民も交えて考えて、１０年以上かけて検討して、そして、こういう庁舎にしていきますという建設企業のプレゼンテーションなども区民にしながら、本当に丁寧に進めていますので、そうした住民参加と情報公開を徹底して進めていくには、少し短すぎるのではないか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問","question":"議論を進めていくのは賛成だということは分かりました。では、先ほど申し上げたように、これはいつ結論を出すべきだと思っていらっしゃるのですか。１０年検討して、その５年後に建て替えの、共産党がおっしゃる１５年、そこから建設を始めるという、そういう認識でいいということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"意見","question":"１５年もつということなので、１５年経ってから建設が始まる、一、二年で検討するというのでは大変ですので、１５年後に間に合うような検討でいけばいいのではないかなというふうに思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/121451?Template=document&Id=6110#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":19534,"voices":90}},{"id":"r03-20210609-19","meetingId":"r03-cm06","date":"2021年6月9日","dateIso":"2021-06-09","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 １時５２分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"品川改革連合の筒井ようすけです。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"今日は概要のご説明ということですけれども、災害廃棄物に関することで、災害廃棄物処理計画の作成が、もう６月に庁内会議を設置ということで、もう今月で差し迫っておりますので、この庁内会議がどのような形で設置されるのかだけ教えてください。","respondent":"山本防災課長","answer":"庁内会議の設置のメンバーですけれども、中心としては防災まちづくり部となり、プラスで都市環境部、それから衛生の部分もありますので、保健所の生活衛生課のメンバーを、部課長等を入れて進めていきたいというふうに考えているところです。","id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"予算特別委員会のときに、私たちは災害廃棄物処理計画の作成について取り上げたのですけれども、まず最初の第１次の仮置場ですか、それは災害が去って、気持ちが少し立ち直ったところで、すぐに始まるのが廃棄物の処理だと思うのですが、そのときに、今までの事例から見ても、やはりなかなかその仮置場の場所というのが、なるべくだったら便利で身近なところにあってほしい、でも。","respondent":"山本防災課長","answer":"こちらの計画の中で、どういったところを仮置場とする、候補をどのように選んでいくかというところは、内部の検討会のほうで決めていきたいというふうに考えておりまして、現在は個別に区民の方のご意見をいただくというところは考えていないところです。","id":"exchange-003"},{"speaker":"吉田委員","kind":"意見","question":"別に今の段階で個別に区民の方の意見をということではなくて、この庁内会議の中に、一番そのような方たちの日々の暮らし、しかも、このような困難なことが起こったとき、より困難になる立場の人たち、はっきり言えば福祉系の方たちです。これは意見です。ぜひ今後の庁内会議の中では、そのような方たちの参加をよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"この計画の目標、令和４年度の資源化率を３１％とすることを目指すということですけれども、現段階、令和３年度なのですが、どのぐらい、この進捗状況がどうなっているかということをお伺いしたいということと、それからこれ第３次なのですけれども、次の計画は第４次ということでつくられると思うのですが、令和５年３月までが今の計画ですから、令和５年４月からということで、そうすると、来年度。","respondent":"品川品川区清掃事務所長","answer":"１点目、目標に対して今のところというところですけれども、これが非常に難しいところでございまして、現在のところは、これをつくった当初が２６％となっておりますが、大体その辺りの水準というようになっております。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっとざっくりとした説明でしたので、これから詳しいところは個別にされていくのだとは思うのですけれども、まず１つ、要配慮者の避難ということについてちょっと伺いたいのですが、これも本当に長い間の課題で、なかなか難しい問題もあって、個別計画などもなかなか進まないという実態があると思うのですけれども、品川区として。","respondent":"山本防災課長","answer":"それから実際の防災と福祉の連携というところで、どういった検討会かというところですけれども、こちらについては、今まさにどういったことを進めていくかというところ、こちらのほうで考えているところではありますが、実際に避難行動要支援者の方を避難させるときの心構えとか。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからあと、４番の防災情報に関することですけれども、ここの情報というところは、緊急情報というようなところが主に書かれていると思うのですけれども、それだけでなく、防災情報というのはハザードマップだったり、それから障害者に対する情報発信だったり、提供の在り方というようなものも防災情報の中には含まれるのではないかなと思うのですが、そのような点では防災情報の、何というのですか。","respondent":"平原防災体制整備担当課長","answer":"障害者をはじめといたしまして、情報を得るために配慮が必要な方につきましては、こちらの緊急情報、今回ちょっと言葉では簡単に概要ということで説明させていただきましたが、あらゆる方が情報を取りやすくなるということは。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、１１月に委員会報告となっていますけれども、この計画について、ぜひ区民に対しての説明会をしていただいて、区民にもそのように、何というのですか、今のうちから災害についての、防災計画のときもそうだったのですが、そのような計画をつくったときに、やはりその意識を持ってもらう、すごく絶好のチャンスになると思うのです。もし、何かご回答がありましたらお願いします。","respondent":"山本防災課長","answer":"区民への説明会というところは、今のところ予定はしておりませんで、パブリックコメントを行いまして、幅広く意見のほうを聴取できればというふうに考えているところです。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めてぜひ、品川区は説明会を様々な計画についてやらないという方針なので、私たちは、そのたびごとに説明会をやっていただきたいということで要望していますが、改めてここでも、説明会をやっていただくように要望させていただきたいと思います。","respondent":"平原防災体制整備担当課長","answer":"ただ、その物資がなくなったような場合というのは、自宅が無事でも自宅での生活が難しくなるような場合がありますので、そういった場合には、例えば避難所への避難をしていただく、あるいはなくなったときによっては、政府や都からの支援物資。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは在宅で、本当にきちんとした環境が整っていないにもかかわらず、在宅避難せざるを得ないという方もいらっしゃると思いますので、これはその具体的な審議のときに、また意見を述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問","question":"環境のＺＥＢ、ＣＯ２のところですけれども、この背景・目的・目標のところで、品川区環境基本計画が平成３０年３月策定となっておりますが、今国のほうで、かなり方向転換ではないのですが、大きくこう、何というのですか、ＣＯ２削減とか、こういったものに向けて、かなり大幅にスピードアップしようという動きが出ておりますけれども、だからこの品川区環境基本計画を策定したときとは、国における全体の。","respondent":"河内環境課長","answer":"そういったところを視野に踏まえながら、検討をしていきたいというようなところで進めているところです。","id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、あくまでそこを意識した上で、ＺＥＢ、ＣＯ２削減の取組みというもののご報告もいただくし、我々もそれをあれしていくので、もしかすると、読み込んでいませんけれども、当時の品川区環境基本計画の数値よりも、もっと大幅に減らしていくのだということでよろしいのでしょうか。","respondent":"河内環境課長","answer":"そういったところから、ＺＥＢあるいは一般家庭へのＺＥＨというところが、今後ＣＯ２削減に向けての有力な要素だと言われておりますので、ＺＥＢというところも踏まえて、そういった目標に向かって検討を進めてまいりたいというふうに考えている中でのＺＥＢの展開です。","id":"exchange-012"},{"speaker":"こんの委員","kind":"質問・要望","question":"直接の概要説明をいただいて、そのことで質問というよりも、今後の進め方で、委員長、そして理事者の皆様にご要望なのですが、今回は概要説明なので大まかな資料ですけれども、この資料について、例えば防災のほうでは、防災協定１７８件と出ております。要するに何が言いたいかというと、こうした防災協定の１７８件、資料の提供をいただきたいなと。その１点お願いします。","respondent":"安藤委員長","answer":"ありがとうございました。ただいまの委員のご意見を踏まえまして、正副で十分に検討していきたいと思います。","id":"exchange-013"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その改定された「避難行動要支援者の避難行動支援に関する取組指針」というものが内閣府から出されているのですけれども、このようなものも、ちょっと全文だとなかなかページ数が厚いのですが、その概要をまとめたようなものを出していただけたら、同じ前提に、議論の前提になると思いますので、出していただけたらということで要望をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"こんの委員","kind":"質問","question":"すみません。先ほどの続きになってしまいますが、先ほどの品川区地域防災計画の中を抜き出してということと同時に、例えば清掃、環境のほうでも、他区の事例、ほかの自治体の事例なども情報収集していただき、そうした資料もご提供いただければなと思いますので、ご検討いただけますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"たけうち委員","kind":"質問・要望","question":"確認ですけれども、今日ここに配られているように、この災害対策についてというものが１枚になっていますね。調査事項の１から４まで。だから、あれでしょうか、これからの進め方としては、同じ災害関係なので、この１から４を全部まとめて、Ａ３で配られた１枚の部分をまとめてやっていくという、環境は環境で別なのでという。これは要望ですけれども、一応もし何かあれば教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/298227?Template=document&Id=6596#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":17014,"voices":68}},{"id":"r03-20210611-10","meetingId":"r03-cm06","date":"2021年6月11日","dateIso":"2021-06-11","committee":"議会運営委員会","time":"午後 １時００分～午後 ２時１６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","topics":[{"id":"topic-01","title":"議長会への要望事項","agenda":"議長会への要望事項","exchanges":[{"speaker":"芹澤委員","kind":"質問・要望","question":"１つ目、経済に関する要望として、前段の説明は省きますが、項目のご説明をいたします。そして２番目、パラスポーツのレガシーの一環として、これは具体的なものですけれども、デフリンピックの日本誘致を実現し、東京２０２０大会が実施された会場で行っていただきたい旨の要望です。２点目が資器材についてです。ＧＩＧＡスクールに関する要望、そして環境に関する要望、この６点を東京都に出しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"国に対する第２位は、行政のデジタル化、デジタルトランスフォーメーションに関する要望ということです。３番目が、これは毎年出しているものですが、高齢者施設に関する要望というところで、特別養護老人ホーム開設のための用地確保ということと、あとは介護従事者の処遇改善と、大枠で書かせていただきました。東京都のほうの第２位は、国のほうで述べた高齢者施設に関するものと同様です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"せお委員","kind":"質問・要望","question":"自民・無所属・子ども未来からの要望は、まず、カーボン・ニュートラル社会の構築、こちら国や都に対してです。項目だけ挙げていきます。こちらは都に要望するものですが、教育のインクルージョンの推進についてということで、提出いたしました。詳細は書面にて代えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"手元に文書が配布されていますので、端的に説明させていただきたいと思います。先ほどのは国に対するものです。次に、国への要望として、都心・市街地を低空飛行する羽田新ルートについてということで、１つは計画の撤回、海上ルートに戻すこと、２つ目は、住環境の影響について調査をし公表することを求めさせていただきました。続きまして、特別養護老人ホームについてになります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"１つ目が、要望内容として、日本経済の中心にある大都市東京の企業と人口は東京に増えている、密集しているということで、１番目に、首都直下大地震が近々起こる可能性が高い、大地震、大火災等が発生した場合に、区民を支援、救済する大勢の職員が区内に待機できる場所、２番目に、大量の避難民が生まれた場合に、区民の一時避難ができる場所、３番目に、感染症などの大勢の感染者が生まれた場合に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"芹澤委員","kind":"質問・要望","question":"あわせて、国に対する要望で言うと、やはり環境に関しては、今回、特別委員会を設置しましたけれども、今、時代の変わり目だと思っていますので、ぜひ前向きにご検討いただきたいと思います。国に対する要望に関しては、ＧＩＧＡスクール構想もぜひご検討いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"芹澤委員","kind":"質問・要望","question":"引き続きになります。すみません。東京都のほうも、国に対して出す要望と被りますが、経済的な支援、環境施策に対する支援というのは、ぜひ都にも出していきたいと、会派として思っています。保健所と財調に関しては、昨年出したものなのですが、まだ大きな改善がなく、全区的な課題だとも思っていますので、ぜひこれも前向きに御検討いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"検討をお願いするのもいいですが、一応、我々、正副議長に、これを出しているわけですから、各会派、すべて取り上げてもらうに越したことはないわけですけれども、芹澤委員のほうからも、重複、重なったところという言葉が出ているので、あとは私たちの意を受けて、正副議長にお願いをするような形をとっていただいたほうが、委員会の効率的な運営上、好ましいのではないかと私は考えておりますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"意見","question":"お二人から今ご意見あったのですけれども、重なっているところというところで、多分、ここに今参加されている方の会派では、やはり、資料No.４－１の一番目の新型コロナウイルス感染症について、ここのところは皆さん異論がないところではないのかなと思いますので、これらは正副議長のほうでまとめていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"各会派の要望もしっかりと読ませていただきました。ただし、羽田新ルートについてですけれども、２３区共通のものではないと言われかねない案件ではありますが、やはり品川区は最も市街地を低空で飛行する、その住民の代表である品川区議会としては、羽田新ルートについて、一致できる範囲で意見は挙げていくという姿勢は大事ではないかなと思いますので、一言述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"なければ１点だけいいですか。１点だけ、要望としては確かに共産党だけからかもしれませんけれども、少人数学級のことについて、中学校も拡大を求めていこうという点においては、項目としては確かに挙がってはいないものの、ぜひ少人数学級を中学校で実施していただきたいという国への要望、これは一致できるのであれば、ご調整をいただけたらと思います。すいません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"渡辺委員","kind":"提案","question":"とりあえず、この７月末という１つのスケジュール感で言えば、議会改革推進会議、こちらで、理由は、会派が大体お顔ぶれがそろっていること、意見集約がしやすいこと、最終的にこの議運で確認もされるという仕組みになっているので、一番スムーズかつ、議会全体の同意が得られやすいかなと思いますので、その方向で、議長提案で言われたとおりで諮っていけばいいのかなという思いがあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"議会で一本化というのは、私はなかなか難しいのではないかと思いますので、できれば、こういう考え方がいいのかどうかわかりませんが、各会派でそれぞれ、例えばＡ４で何ページまでということでまとめて、それで各会派の意見を区のほうに提出して、こういうご意見が出ていますよという形をとったほうが、行革は行革でまた報告をするのでしょうから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"それぞれやはり、皆さん、区に対する要望というのは違っている中で、では１つにそこを一本化するとなると、どれかを取捨選択しなければいけない、どれかは、いやそのような意見はなかったということで区に報告するわけですから、そうではなくて、もう議会として、各会派の意見をこういうふうにお渡ししますと、意見がありましたとやったほうが、いろいろな人の、各会派の意見。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"たけうち委員","kind":"質問","question":"今、石田秀男委員長からお話があって、須貝委員にも分かっていただけると思ったのだけれども、分かっていただけないみたいなので。いろいろな議員のお声があって、それを議会がある程度議論してくれなければ、そのためにわざわざ議長に、そういう議論をしてもらえないかと要請が来ているのを、最初から、いやそれはできないから、そちらで勝手に決めてくれと言っているようなものではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"須貝委員","kind":"質問・要望","question":"もう１回だけいいですか。すみません。これ以上は言いませんけれども、建物を建てるということは、構造から意匠から、何階建てにするとか、いろいろな仕組みから始まるのですね。私はそれを言っているのです。でも、実際にそれを議論をしていったら、膨大な日数がかかりますので、私は申し上げているだけで、別に私の意見を通そうとは思っていないので、こういうことを認識していただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"大沢委員","kind":"質問・要望","question":"今、須貝委員から、意見を通そうと思っていないというようなご発言は問題がある。そういう意見であればご発言は差し控えていただきたいということです。それと、行政側から議長に諮問というか問いが来ているということは、議会としての統一した意見が求められているのであって、会派のおのおのが出す意見については、これはもうまるっきりまとまりがつかないものであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"そもそも共産党としては、区が示している庁舎建設については白紙に戻して、十分に時間をかけてやるべきだと述べてきました。ただし、全会派から出ているかというとそういうわけでもないし、議会棟の議論ですから、希望する無所属議員の方も参加を保証、希望する方がいらっしゃれば保証すべきだと思いますので、そういう意味からすると、なかなかこの議運のメンバーだけでは限界があるのかなとも、思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問・要望","question":"会派としての意見は、先ほどたけうち委員から申し上げたとおりですので、１点だけお願いです。７月末までにと言われても、これはタイトなスケジュールの中で、それこそ、先ほど中塚委員からもありましたけれども、７月末までという投げかけである以上、なるべく早く情報を出していただきたいということが１つです。課題を抽出する。なるべく資料の件はぜひ役所側にプッシュしていただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"すごく簡単に。いずれにしても、先ほど議長から投げかけられたとおり、こうした説明の場を設けようではないかという点で一致ができるのであれば、できるだけスピーディーにことを進めていただけたらと、改めて要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/761909?Template=document&Id=5416#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":23525,"voices":72}},{"id":"r03-20210622-10","meetingId":"r03-cm06","date":"2021年6月22日","dateIso":"2021-06-22","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","topics":[{"id":"topic-01","title":"令和３年第３回定例会の日程","agenda":"令和３年第３回定例会の日程","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"委員会日程については、了解いたしました。ただ、この資料の右下に、仮ですけれど行政視察と書かれております。昨年同様ですけれども、コロナ感染の状況をよく見極めて、各委員会対応がばらばらというよりも、区議会として同じ対応ができるように調整していただきたいと。意見だけ述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"確認と質問と意見を述べさせていただきたいのですけれども、まず確認です。議会改革推進会議では、この間、最終的な取りまとめは全会一致ということで確認されておりましたが、今回も同じ取扱いでよいのか、確認させていただきたいと思います。質問ですけれども、いつまでに何回ぐらいというスケジュール感はお持ちなのか。","respondent":"本多議長","answer":"最初のほうですけれども、議会改革推進会議で協議をしていただきたいという発言をさせていただきました。そこで十分議論を尽くしていただいて、その会議体によるまとめが出来上がりましたら、それを議会運営委員会で確認していただけないかと、そういう趣旨です。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回の会議体も今までどおり、最終的に要望をまとめる段階においては、全会一致で進めるべきだと、従来のことを変えるべきではないと思いますので、その辺だけ確認したいです。これは誰に聞いたらいいのか分からないですけれども、全会一致だけ確認させていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"全会一致については、先ほど述べたとおりです。前回述べましたけれども、最終的には要望事項を協議したいということですけれども、まずは現状の課題を丁寧に抽出していくことが求められていると思います。どうしてもスケジュールがタイトなので、資料については、委員会と同じにするのであれば、せめて２日前に提供していただきたいと、意見を述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"メンバーの傍聴はそれでいいと思うのですけれども、やはりとても大事な議会棟の議論になりますので、メンバー以外の方から発言をしたいという申出があったときには、委員会に諮って発言を認めるかどうか、そういう丁寧な進め方ができたらと、要望したいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"関連なんですけれど、議会改革推進会議でやるということで、それはいいと思うのですが、中塚委員のほうからも要望しましたように、無所属委員の意見をどう聴取するか、あと、今回はいろいろお考えがあって品改も入っていないということで、そうした推進会議に入っていない議員の意見を、どう聴取するかについて、どのようなお考えがあるのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"今、品改の話をしていただいて、ありがとうあります。ただ、この間もお話をしたのですが、せっかく今、専門家、有識者、それから議員を代表して、そちらで検討が進められているのですから、我々とすればそれを尊重してやっていきたいので、任せている以上、私らの会派としては、推進会議で一緒に討論、議論することは考えておりませんので、ありがとうあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"一言、意見だけ述べさせていただきたいと思います。要望事項の５番にマイナンバーカードの普及促進とあります。個人情報漏えいの問題、プライバシー侵害の問題、さらに国による個人情報の一元管理の問題など、この要望事項は共通する事項で進めていこうという趣旨でありますので、マイナンバーを進めていくという点については、適切ではないと思いますので、一言意見だけ述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"委員会はもちろん本会議場にも、手話通訳をつけるべきだと思っているのですけれども、どういう対応されるのか。つまり、発言者の隣だと遠くて見えないのではないかと思うので、何か工夫ができれば、当事者の方のご意見を伺うのが一番だと思いますけれども、委員会だけでなく、本会議にも手話通訳を、でも、テレビでやっているのか。すいません。","respondent":"工藤区議会事務局長","answer":"今回、所管からお話しいただいていますのが、７月６日の厚生委員会と、７月１４日の本会議最終日に、手話通訳者をです。そのような形で私ども見込んでおりますので、傍聴者にしっかり伝わるような形で対応してまいりたいと考えております。","id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/761909?Template=document&Id=5418#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":11181,"voices":54}},{"id":"r03-20210706-6","meetingId":"r03-cm07","date":"2021年7月6日","dateIso":"2021-07-06","committee":"区民委員会","time":"午前１０時００分～午前１１時２７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","topics":[{"id":"topic-01","title":"第３９号議案、品川区手数料条例の一部を改正する条例","agenda":"第３９号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今回、手数料条例ということではありますが、冒頭説明があったように、デジタル庁の設置に伴って、マイナンバーカードの発行主体が品川区からＪ－ＬＩＳに移るという説明でした。なぜ品川区からＪ－ＬＩＳに移るのか、その目的について伺いたいと思います。あわせて、Ｊ－ＬＩＳとはどんな組織なのか、国との関係についてもご説明いただきたいと思います。","respondent":"木村戸籍住民課長","answer":"令和４年度末までに国民全員にマイナンバーカードを交付するという国の目標がございまして、それに向け、さらに加速をさせるという意味で、端的に申しますと、国がいわゆるガバナンス強化といいますか、目標設定があったり。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、説明あったとおり、マイナンバーの強化、マイナンバーカード発行の加速ということになります。マイナンバーカードの普及は、個人情報を全員一元化させ、個人情報漏えいの危険も繰り返し言われております。マイナンバーの推進は行うべきではないと、意見を述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"横山委員","kind":"確認","question":"確認なのですけれども、再交付申請のとき、１件につき８００円という手数料の額は変わらないということでよろしいのでしょうか。こちらは区の歳入が改正なので、改正後、９月以降は歳入歳出外現金になるということなのですけれども、大体何件くらいで、総額幾らくらい見込んでいらっしゃるのでしょうか。","respondent":"木村戸籍住民課長","answer":"手数料額ですが、変わらない予定でということなのですけれども、８月中に決定するです。基本的には変わらない予定です。それから、歳入額なのですけれども、令和２年度の実績ですと、８９６件、７１万６,８００円。そのぐらいの規模の金額です。","id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"あまりにも、個人情報について何回も委員会の中で質疑が出た中で、このようになりましたから、このようにしますというような、この一文だけになっていていいのかなという思いが少しあるのですけれども、その辺についてはいかがですか。","respondent":"木村戸籍住民課長","answer":"書き方のところで、ちょっとうまくなかったかなという部分は正直ありますけれども、全体としては、大きな変更はございませんので、ご理解いただければと思います。","id":"exchange-004"},{"speaker":"藤原委員","kind":"確認","question":"今の答弁の確認ですが、より一層個人情報は、国の目が入ることによって守られていきますという理解でよろしいのでしょうか。","respondent":"木村戸籍住民課長","answer":"今回の改正による変更に関しましては、いわゆる個人情報の取扱いの部分での変更というのは特にございませんので、今まで同様にしっかりやっていくという形です。","id":"exchange-005"},{"speaker":"中塚委員","kind":"意見","question":"マイナンバーを強化・加速させるべきではないと思いますので、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"}]},{"id":"topic-02","title":"令和２年陳情第６２号、目黒川沿いに設置されている喫煙所撤去に関する陳情","agenda":"令和２年陳情第６２号、目黒川沿いに設置されている喫煙所撤去に関する陳情","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"加熱式たばこですけれども、加熱式たばこというのは、ふだんライターで火をつけるたばこと同じものなのか、つまり、ポイ捨て禁止の条例がありますけれども、たばことして扱っているのかどうか、その点を確認させていただきたいと思います。加熱式たばこの健康被害は、私はあると思っているのですが、その点についてもご説明いただきたいと思います。","respondent":"森田生活安全担当課長","answer":"加熱式たばこについてのご説明です。通常の紙たばこと言われているものにつきましては、火を点火して、中のたばこ葉を燃やして、その煙を吸うというのが紙たばこです。","id":"exchange-007"},{"speaker":"中塚委員","kind":"意見","question":"加熱式喫煙所になったとはいえ、健康被害をもたらすものなので、結論めいたことを言ってしまうけれども、撤去すべきだと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"課長に伺うのか、委員長に伺うのか、わからないのですけれども、今、課長の説明の中で、加熱式喫煙所にしていきますということを陳情代表者に説明しに行ったら、承諾いただいたという説明がありましたが、この陳情は、撤去をお願いしますという内容です。","respondent":"森田生活安全担当課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"藤原委員","kind":"確認","question":"分かりました。だから、ここは撤去をお願いいたしますとなっているけれども、こういう形で、このようにしていきますと行政として説明したら、陳情代表者は納得していただいて、していただいたから、この裏面にある再開後のイメージ図みたいにしていきますという形で報告してくれたということでいいのでしょうか。改めて確認します。","respondent":"森田生活安全担当課長","answer":"そのとおりです。引き続き、やっていきたいと思います。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問・要望","question":"もう一つは、たばこを作る、たばこを直接販売しているところ、たばこ会社でいいのか、そういうところも私は、こういう喫煙場所をつくるときに、経済的に協力をしていっていただきたいと思っているし、これは直接委員会等で質問はしておりませんので、改めて伺うのですけれども、喫煙所の中には、たばこ会社が経済的に協力をしてくれているところもあると聞いたことがあるのですけれども。","respondent":"森田生活安全担当課長","answer":"喫煙所のたばこ会社の協力ですが、今回の本村橋喫煙所につきましては、フィリップモリスから敷地の中の看板等、喫煙の灰皿も含めて、受けたという形になっています。","id":"exchange-011"},{"speaker":"くにば委員","kind":"質問","question":"だからこれは禁止しているという、幾つかの明確な理由があるのですけれども、品川区はここに対して、例えば都の条例が、そもそも加熱式たばこは対象としているか、違反の対象としているから品川区も準じていますという理由なのか、もしくは、例えばそれでしたら港区はみなとタバコルールで、東京都に準じている必要があるというか、準じていてしかるべきだと思うのですけれども。","respondent":"森田生活安全担当課長","answer":"先ほどのところでも、厚生労働省が加熱式たばこを指定たばことしているということと、健康被害のリスクについては科学的根拠が十分でなく、さらなる研究が必要であるということで、今のところ加熱式たばこは、たばことして認識されておりますので、これにつきましては。","id":"exchange-012"},{"speaker":"くにば委員","kind":"質問","question":"品川区も対象になっていないはずです。ポイ捨てというのは、ここの後の問題ではないですか。そもそも加熱式たばこを規制するという理由について、すみません、私の質問が分かりづらいかもしれないのですけれども、伺いたいのですが。","respondent":"森田生活安全担当課長","answer":"港区等で加熱式たばこを除いているのかもしれませんが、先ほど説明させていただきましたが、現状、科学的根拠が十分でないというところからも、紙たばこと加熱式たばこを分けて、加熱式たばこはいい、紙たばこは取り締まるという考えでは、今のところはございませんので。","id":"exchange-013"},{"speaker":"くにば委員","kind":"質問","question":"それで、大崎駅西口線路脇の加熱式たばこ専用喫煙所の実証実験の成果ということで、これは大崎駅西口の加熱式たばこ専用喫煙所が区内で初めてだったのかどうかということと、今回の大崎駅の実証実験の成果を踏まえて、ほかにも区内で広げていく方向で考えているのか、そこについて伺えますでしょうか。","respondent":"森田生活安全担当課長","answer":"今後も加熱式たばこ喫煙所を広げていくかというお話ですが、これにつきましても、今設置してある箇所の状況や、また、他に選定できる箇所があれば、随時進めていきたいとは考えております。","id":"exchange-014"},{"speaker":"くにば委員","kind":"質問","question":"それは、一般的な喫煙所を撤去したときの苦情・トラブルというのと近しいものがあると思うのですけれども、そういったトラブルが、あくまで全く大崎駅では発生しなかったから、今回その実証実験が成功したということになっているのか、それとも、何かそういったトラブルというのが起こり得る他自治体での事例であるとか、ほかのところで加熱式たばこ専用のところにしたときに、そういったトラブルであるとか。","respondent":"森田生活安全担当課長","answer":"今回の喫煙所につきましては、大きな看板で、ここは加熱式たばこ専用エリアですという形で仕切らせていただいております。ここには、目黒川の反対側に花房通り沿いの喫煙所もございまして、紙たばこの方はそちらへというご案内も入れする予定です。","id":"exchange-015"},{"speaker":"くにば委員","kind":"質問","question":"花房通りのほうに喫煙所があるというのは、前回、昨年この陳情について我々で議論したときに、そのときの課長に、近隣にないと伺ったのです。そこに行ってくださいとアナウンスができると。そうすれば今後、同様の陳情がなくなるというか、区内での煙害であるとか、ポイ捨てであるとか、問題がなくなってくると思うのですが、そこの２点についてお伺いしたいのですけれども。","respondent":"森田生活安全担当課長","answer":"しかしながら、今現在もたばこを吸われている方が、あの周辺にいらっしゃいますので、あそこと、なおかつ今回の陳情にもありますとおり、火種や煙や臭いの問題も考えますと、あそこでは加熱式たばこが一番よいのではないかということで、結論を出したところです。","id":"exchange-016"},{"speaker":"くにば委員","kind":"質問","question":"分かりました。賛同したのです。もちろん、そんなトラブルというのは起こるべきではない。例えばあそこに関しても、加熱式たばこ専用に転換をするという考え方は、当然同じくあると思うのですが、そういった、ほかにトラブルが起こっているところに関しての今後の見通しというか、加熱式たばこに今後転換したほうがいいのではないかということは、どのようにお考えになられているのか伺いたいです。","respondent":"森田生活安全担当課長","answer":"城南信金の前のところにつきましても、コンテナ型、加熱式、様々なことも検討しているところでございまして、その解決の折には、何かしらの代替の喫煙所となるものを設置したいということでは考えております。","id":"exchange-017"},{"speaker":"くにば委員","kind":"質問・要望","question":"この指定喫煙所は、先ほど報告がありましたとおり、基本的には陳情代表者の方が、このような方向性で区でも努力をして、トラブルが起こらないだろうという感じで、区内の大崎駅の事例を用いて納得してくださるという部分がありますので、ほかのところでもトラブル、煙害が発生しているところに関して、同様の措置というのをどんどん推進していただきたいと個人的に考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明ありがとうございました。その中で、その場所で過料を徴収したという事例はあったのですか。それが１点。あそこは今、紙たばこの方もいますけれども、本当にいろいろ検証していただいて、加熱式、そして紙たばこの両方の方が、愛煙家の方々が好んで喫煙できるような体制を、これから先、整えていただきたいという、これは要望で終わりにします。１点だけ、お願いします。","respondent":"森田生活安全担当課長","answer":"本村橋の喫煙所の周辺の徴収については、実際にあります。件数については、手元の資料ですと、８件あります。","id":"exchange-019"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ただ、ここが加熱式たばこになってしまうということは、紙たばこを吸われる方にとっては吸う場所がなくなるということでありますので、生活安全パトロール隊のパトロールを大崎でもやっていたということですけれども、引き続き、五反田のこちらの場所でもパトロールを継続していくのかということと、もう一つは、吸う方のマナー向上に対して、どのように品川区は取り組んでいかれるのかというところを。","respondent":"森田生活安全担当課長","answer":"生活安全パトロール隊につきましては、引き続き本村橋周辺のパトロールを、指導等を継続的にやってまいります。","id":"exchange-020"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ぜひお願いいたします。たばこ税の収入が、たばこを吸われる方が減りつつある中で、品川区として少しずつ、たばこ税としての収入が減っている現状があるかと思うのですが、品川区が大胆に、この喫煙所の設置というところに向けては、もう少し予算をつけながらやっていただきたいというのが要望としてあります。","respondent":"森田生活安全担当課長","answer":"これが終わりではないので、引き続き、吸う方も吸われない方も両方が共存できるような環境をつくっていきたいと思ってはおります。民間の場所につきましても、補助を出せるようにしましたので、民間の場所においても喫煙所ができるような形で進めていきたいとも思っています。","id":"exchange-021"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ぜひ、たばこ会社の協力もたくさんいただきながら、取組を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、趣旨採択でお願いいたします。吸う方も吸わない方も共存する社会というご説明がありましたが、トラブルが起こる、起こらないではなくて、引き続き区内のバランスを見ていただきながら、喫煙所を密閉型・加熱式への転換というお話がありましたけれども、区民の方へのマナーの啓発も引き続きお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"高橋（伸）委員","kind":"質問","question":"本日結論を出すということで、趣旨採択でお願いします。理由を述べさせてもらいます。この陳情代表者の意見について本当に理解はしますが、区でも喫煙所設置に関しては非常に検証している中で、加熱式専用にしたということは、いろいろ苦慮されたということだと思いますので、改めて趣旨採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"中塚委員","kind":"意見","question":"本日結論を出すということで、私は採択でいいと思います。道路を含め、公共の場での喫煙は規制が必要だと思います。健康被害についても、引き続き深刻なものがありますので、加熱式たばこであっても撤去すべきだと思いますので、採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"くにば委員","kind":"意見","question":"前回と同様、採択の主張になるのですけれども、基本的には、この陳情を出されている方々の思いというのは、非常にこの文章であるとか、あとは、実際に現場の写真を一通り見てみて、ひどい状況だというのはよくよく分かりましたので、ここに喫煙所というのは置くべきではないというのが一つあったのですが、今回いろいろとご努力をなされて、陳情を出された方がまずは一つ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"}]},{"id":"topic-03","title":"議題順を変更いたしまして、(2)区民斎場「なぎさ会館」エレベーター工事に伴う休館","agenda":"議題順を変更いたしまして、(2)区民斎場「なぎさ会館」エレベーター工事に伴う休館","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"数字的に、まず教えていただきたいのですが、大体平均して、数字を持っていると思うのですけれども、この期間、何件ぐらいできなくなるのか、そして、できなくなった数というのは、全てではないと思うけれども、大体なぎさで式をやって、火葬をなされるのは臨海斎場というのが多かったと思うのですが、その期間は多分、臨海斎場で式もして、火葬もするという形になると思うのですけれども、その辺について。","respondent":"木村戸籍住民課長","answer":"現在の想定件数ですけれども、１２件という形になります。年間の使用されている件数、これは議会でもいろいろご要望いただいているところですが、稼働率がかなり低いところが正直ございまして、件数的にもそのぐらいという形になります。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"この期間で１２件しかできない。できないというのは、やれない、葬儀ができないということですか。私が違っていたら、ごめんなさい。４か月で１２件しかないということはないと思うのですが。","respondent":"木村戸籍住民課長","answer":"言葉足らずで申し訳ございません。令和２年度の実績なのですけれども、実際の枠数に、お使いになられた稼働率が２１.６％ということで、休館日数５９日ということで計算しますと、空いているときが多いです。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"今日、こういう質問をさせていただいて、数字を見て、もっと見ようと思ったのですけれども、逆算して１２件だと、１２件、臨海斎場とか桐ヶ谷斎場で火葬をするという意味であるならば、そんなにやってほしい火葬ができなくなってしまうとか、亡くなられてから何週間も火葬することができないという状況にはならないということですね。","respondent":"木村戸籍住民課長","answer":"ご認識のとおりです。","id":"exchange-029"},{"speaker":"藤原委員","kind":"意見","question":"今日はもうこれ以上しませんが、１２件というと、改めて、なぎさ会館をこのまま維持していくかという問題も、これから考えていこうと思っていますので、これは私も勉強して、４か月で１２件という形に、大体逆算してというか、想定だとすると、なぎさ会館の維持をしていくという意味においても、別の課題があると思うので、何かありますか。","respondent":"木村戸籍住民課長","answer":"実際に使用の枠そのものも、減っているというところもあります。それと、今後の使用というか、活用あるいはあり方的なものに関しましては、議会でも答弁をさせてはいただいているところです。現在、検討を進めてまいっているところです。引き続き、それは行ってまいります。","id":"exchange-030"},{"speaker":"横山委員","kind":"質問","question":"新しいものに関してなのですけれども、こちらの耐用年数は大体どのぐらいになるのでしょうか。ロープ式というものに替わるということなのですけれども、どういったところが変わってくるのかというのと、省エネになるということで、今までとどのぐらい違うのかという点、あとは、日常点検のコストみたいなところにも変わるのであれば、その変更点を教えてください。","respondent":"木村戸籍住民課長","answer":"どのぐらいの省エネがされるのかという部分なのですけれども、今、手元に数字がございません。申し訳ございません。それから、保守のコストに関しましては、基本的にそれほど変わりはないです。","id":"exchange-031"},{"speaker":"横山委員","kind":"確認","question":"もう１点なのですけれども、安定性のところにも関わるかもしれませんが、地震等の災害の際に、どのような対応のものになるのでしょうか。避難がしやすいものとか、今は新しい機能がいろいろあるかと思うのですけれども、その辺りだけ確認させてください。","respondent":"木村戸籍住民課長","answer":"基本的には、一番近い階とはいっても、それほど移動する階もないのですけれども、そこに止まって、通報が飛んで、人が来るという、今、エレベーターのベースにあるような新しい部分は、全部網羅する予定です。","id":"exchange-032"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。期間を確認します。休館期間は５９日間ということでしたが、この休館期間を見ると、新設工事のために１０月１８日から１１月３０日、撤去で１月１７日から１月３１日ということで、１２月の１か月間というのは作業がないと思われるのですが、この期間というのはどのような扱いになるのか、確認させてください。","respondent":"木村戸籍住民課長","answer":"新設工事のために休館する、撤去工事のために休館する、この間に関しましては、音とか振動が伴わない部分ということで、通常どおり開館をします。それから、使い勝手の部分ですけれども、現時点では何か改修を行うという予定はございません。","id":"exchange-033"}]},{"id":"topic-04","title":"令和２年国勢調査の速報値","agenda":"令和２年国勢調査の速報値","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"分かりやすく説明していただきたいのですけれども、回答状況が令和２年１１月２０日時点ので出ています。品川区は７７.０％ではないですか。今、最初の説明で、人口がこのぐらい、世帯数はこのぐらいだと説明してくれたけれども、この回答率で、正確なものというのは出てくるのですか。","respondent":"川島地域活動課長","answer":"失礼いたしました。残りの２３％というのは、職員が調査をして回答させていただいて、全て足すと１００％になるです。","id":"exchange-034"},{"speaker":"藤原委員","kind":"確認","question":"それを確認したくて、だから、限りなく１００％に近いから、正確な数字は出ていますということで説明していただかないと、あれだけの予算を使って国勢調査するわけですから、この辺がきちんとしていなければ、人口だけを調べる調査ではないのです。文面では、統計法でみたいに出ていましたけれども、その辺についてお伺いします。","respondent":"川島地域活動課長","answer":"国勢調査につきましては、統計法に基づいて行われるということで、今、委員がおっしゃったとおり、たしか５０万円の罰金という形で、報告をしなかった場合というのは定められておりますが、あくまでも私どもとしては、罰則はありますが、調査のほうはお願いをするという形で。","id":"exchange-035"}]},{"id":"topic-05","title":"しながわ区民公園屋外水泳場への予約システム導入","agenda":"しながわ区民公園屋外水泳場への予約システム導入","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"逆に私などは、すぐずるいことを考えてしまうのだけれども、１０人ぐらい申し込んでしまって、当たったらご近所に声をかけるとか、そういうのはどうなのかなとは思うのですけれども、１組何人なのか、そこの説明をいただけますでしょうか。","respondent":"中元スポーツ推進課長","answer":"すみません、ご説明が不足しておりました。１組５人までということで、ホームページには詳しく記載をさせていただいたのですが、また、枠についても１日１枠、午前なら午前だけ、午後なら午後だけということで、システムでチェックをします。","id":"exchange-036"},{"speaker":"西村委員","kind":"確認","question":"１点だけ、すみません。ホームページを見ていればよかったのですけれども、ウェブを使えない方とか、その他の申込方法の確認だけさせてください。","respondent":"中元スポーツ推進課長","answer":"幸い今のところ、電話は１日３件ぐらいでして、やはりプールの利用者はお子様がいる世代の方なので、割とウェブでの扱いが皆さん熟練していらっしゃるようで、そこのところは混雑することなく対応させていただいてあります。","id":"exchange-037"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"新妻副委員長","kind":"質問","question":"１点だけお伺いします。ここに出ています屋形船・クルーズ船の紹介ですが、１２件出ておりますけれども、これは全部ではないと思うのですが、もっとほかにも船宿があるのではないかと思うのです。ここに掲載されている１２件というのは、どういう条件で載せられているのかお伺いします。","respondent":"篠田文化観光課長","answer":"こちらは、観光振興協議会水辺部会で整理いたしまして、基本的には全部載っているということで認識しています。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/943539?Template=document&Id=2902#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":25608,"voices":127}},{"id":"r03-20210706-7","meetingId":"r03-cm07","date":"2021年7月6日","dateIso":"2021-07-06","committee":"厚生委員会","time":"午前１０時００分～午後 ３時２６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件抜き出しています。","topics":[{"id":"topic-01","title":"第４０号議案、品川区手話言語条例","agenda":"第４０号議案、品川区手話言語条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それとアンケート調査もされたということですけれども、「身体障害者手帳の交付を受けている聴覚障害の方（約８００人）」とあるのです。そこから抽出をして２７６人に送付をされたということで、回答数が１４３人ということなのですけれども、私は、８００人の方、皆さんに聞いてもよかったのではないかというふうに思うのですが、抽出とした理由、絞った理由を聞かせていただきたいと思います。","respondent":"松山障害者福祉課長","answer":"１、２、３級の手帳をお持ちの方は、やはり手話をお使いいただいていると区のほうでも考えておりましたので、実際に抽出した結果、障害の程度が重い人ほど手話を使っているということが判明したです。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"アンケートですけれども、そうすると、この２７６人というのは、手帳の１級、２級、３級の方に絞ったということではないのですか。ということは、２７６人という数字は、１、２、３級の方だけではなく、バランスよくと言われているということは、そういうことですね。そこを伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"抽出の方法ですけれども、無作為抽出です。こちらの回答ですが、一定程度の母数があれば明らかになるものがありますので、調査の母数としては、これで有効であるというふうに判断しております。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"そしてさらに、この条例のモデルには、「この条例の施行後３年を目途として、この条例の施行の状況について検討を加え、その結果に基づいて、必要な見直しを行うものとする」という、さらによくしていくという、ＰＤＣＡサイクルではないですけれども、そういったものも盛り込まれているのですが、こういうモデル等は参考にされたのかどうか、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"４つの団体と協議するにあたり、条例のモデル等のお話もいただきましたが、地域の実情に合わせて、各区で決めるということになっておりますので、２年間にわたるかなり長い話し合いの中で、それは十分に意思疎通を図り、今回、条例案として提案をさせていただいたところです。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"ということは、条例には入れ込んでいないけれども、実施計画なり推進計画をつくるべきだと思うのです。そうしていかないと、どういうふうに区が進めいくのかということが、区民も分からないし、そしてさらに検討していいものにしていくということができないと思うので、そうした推進計画をつくるべきだと思うのですけれども、そこら辺は検討されているのでしょうか。","respondent":"松山障害者福祉課長","answer":"理解促進を進めていくにあたり、この条例をつくったから終わりではなく、この４つの団体の話し合いの中でも、この条例制定を機に、さらに理解促進を進めるということで、今後も定期的に理解促進を進める方策について一緒に話をしていきましょうということで合意がとれております。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、こうした条例を制定して、そして推進を進めていく計画等がしっかりあると、区民の変化とか反応もすごく変わってくると思うのです。ですので、普及させていくために環境整備を推進するという区の責務があるわけですから、計画、方針、そうしたものに基づいて進めていくということを検討するべきではないかと思うのですが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"今後も４つの団体とは丁寧に話し合い、意思疎通を図って一歩ずつ進めるということが大事なのではないかというふうに合意をしておりますので、計画ありきではなく、ご本人たちの思いを条例の前文にも反映しています。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"意見","question":"でも、計画なしにどうやって進めていくのかと思うところですので、意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"その辺については、区としては、どう捉えられているのか。そういうことも制定の理由などのところに、本来であれば、私は前文のところにも入れていただいたほうがいいのではなかったかというふうな思いがあるのですけれども、その点についてはいかがでしょうか。お聞かせください。","respondent":"松山障害者福祉課長","answer":"こちらの第４０号議案の中で、手話言語条例の第１条（目的）の前の前文のところには、「手話の使用は様々な制約を受けざるを得なかった歴史があります」ということで、こちらにつきましては、団体のご意見も可能な限り、前文に思いを反映させていただいたところです。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほどありました団体へのヒアリングを合わせて５回されたということなのですけれども、これの結果は、その団体の皆さんからどのような課題ですとか、要望で出されたのかというところは、何かまとまったものがあるのでしょうか。具体的に課題や要望がどのようなことが出されたのかということについてもお聞かせいただきたいと思います。","respondent":"松山障害者福祉課長","answer":"ご要望につきましては、例えば、全ての団体というよりは、品川区聴覚障害者協会のほうから、障害者福祉課における手話通訳者の配置を、今回、４月から１日増やしましたけれども、そういったことであったり、あとは、タブレットのことであったり、あとは日常的に。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"区としては計画は策定する考えはないということなのですが、その計画は、例えば障害福祉計画の中に具体的に織り込んでいくだったりとか、そういうふうなところでの具体的にどうしていくのかというのは、見える形でしていくものはないのかということを１点お聞かせいただきたいのと、それから、団体の皆さんと一緒に話し合いをしながら具体的に進めていくということで言われましたけれども、それであれば。","respondent":"松山障害者福祉課長","answer":"今後も全日本ろうあ連盟の条例のモデルにあります会議の名称とは違いますが、この４つの団体と話し合って進めていくということは変わりませんので、この条例に基づいて同じような形で進めていきたいと考えています。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"ということは、この４つの団体とは、推進協議会みたいな名称はつくることはないけれども、それと同じような形で定期的に話し合いを進めて具体化をしていくということで確認させていただいてもいいでしょうか。それで、『手話でＧｏ２！』とか、こういう冊子があります。その点についても伺います。","respondent":"松山障害者福祉課長","answer":"そちらの条例のモデルにつきましては、全国に、あくまでもモデルということで出しておりますので、各区、やはり地域の実情ですとか、地域の手話に関わる団体というのは、それぞれ異なりますし、それぞれの方の思いは尊重して進めていきたいと考えていますので。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"実際にそういう普及だったり、理解だったり、環境の整備だったりが具体的に進むということが一番大事なので、それは本当にそういうふうにぜひ進めていただきたいと思います。それから、ここのところに、全国手話言語市区長会がつくられたということで書かれていたのですけれども、ちなみに、濱野区長がここに入られているのか、その点についても伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"１点目ですけれども、話し合いの頻度についてのお尋ねですが、４つの団体のそれぞれお仕事を持っていらっしゃる方だったり、相手があるものですから、まだ頻度については特に決めてはおりませんけれども、この間、年に２回は必ず実施してまいりまして、あとは、それ以外でも。","id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"実態のところがよく分からない部分がありまして、教えていただきたいのですが、アンケートの２ページのところで、手話を使用していない方が４７％いらっしゃるということであったのですけれども、その使用していない理由は、どういうことで使用されていないのかというふうなところを教えていただきたいのと、あと、この冊子のところでも、ろう学校で学ぶときに。","respondent":"松山障害者福祉課長","answer":"１点目、アンケートの中で、使用していない人が、なぜ手話を使用していないのかということにつきましては、その方それぞれによって、例えば口話法ですとか、筆談ですとか。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問","question":"補正予算のほうにも約４００万円つけて、審議の話になるのでここでは一端なのですが、動画をつくったり、広報をつくったりということで、区の条例制定に向けた意気込みというか、それが感じられるので、その点もすばらしいことだと思います。発展型と言えばいいのでしょうか、そこにいかずに、手話言語条例。","respondent":"松山障害者福祉課長","answer":"４つの団体との協議の中では、実際、手話が言語であるという趣旨と、意思疎通を尊重するというものとは趣旨は全く違うものですので、今回は手話は言語であるということで、手話言語条例のみとしまして、コミュニケーション条例については、今後。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"理解しました。ありがとうございました。今お話にあったように、ぜひ障害の特性に応じたコミュニケーション支援に係る条例ができればすばらしいのですが、その制定に向けて、また検討をしていっていただきたいと思います。いろいろな特性に応じた意思の疎通がなかなかできない方、難しい方がいらっしゃるので、ぜひよろしくお願いします。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"それから何よりも、まさにここに書いてあるように、地域の方々の参加というか、参画というか、そういうことが１つ重要ではないかという強い思いの中で、一般の方と違うので、自立支援協議会で、今、様々な部会といいますか、分科会といいますか、ああいうものがありますけれども、例えばそういうところも活用しながら、いわゆる町会も含めた一般区民の方の理解促進のための裾野をどのように広げていくか。","respondent":"松山障害者福祉課長","answer":"何点かご質問をいただきました。今まで４団体の方々と意見のすり合わせを丁寧に行ってきたわけなのですが、団体の方々もいろいろご苦労があったのではないかと考えています。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"賛成でありますけれども、理由を少し述べします。やっとここまで来たのかなと考えています。我々の会派も団体の方々と何回もヒアリングをさせていただいて、区長要望も提出をして、何度もこの話はしてきたと考えています。その点だけ要望させていただいて、この議案については賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"せお委員","kind":"質問・要望","question":"私も賛成なのですけれども、１点、要望だけします。先ほど、高橋しんじ委員からお話があったように、本当に手話以外のコミュニケーション手段というところで、例えば知的障害をお持ちの方とか、重複障害の方にとっては、手話が難しかったりしますので、手話以外のコミュニケーション手段を含めた条例を、追加でもいいと思うのですけれども、ぜひそこは期待して、要望して賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-02","title":"会議の運営上、予定表の順序を入れ替えまして、(4)第３６号議案、令和３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"会議の運営上、予定表の順序を入れ替えまして、(4)第３６号議案、令和３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"条例の上程に合わせてということで、先ほど、全会一致だったわけですけれども、そういうことがされましたとか、広報しながわ臨時号の内容はどのような内容にすると考えているのか、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"それから３点目の広報しながわ臨時号の内容についてのご質問です。手話言語条例の制定を機に、条例の周知、そのほかには障害者の福祉の特集号といたしまして、この条例に限らず、広く障害者理解を進めるような記事の掲載を考えております。","id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。次にいきたいと思います。この対象者のところで、どういう方が不承認になるのかということを伺いたいのと、あと、そもそもの総合支援資金、緊急小口資金の実績、人数と総額を教えてください。そして、事務費ですけれども、３,５００万円余ですが、これはどういったもの、人件費と、そのほかにもあるのか。人件費もあると思うのですけれども、何人体制ぐらいのものなのか、伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"受付期間につきましては、国のほうから８月末ということで示されておりますので、まずはそちらに向けて対応していくということで、特に現時点で延長等の話について検討できる状況ではないです。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこはしっかりと開示されないと、不承認になった理由、別にプライバシーに入るようなところではなく、そういった理由が分かるようにするほうが、区のこうした事業の対象者にしても分かりやすいのではないかと思うので、そこは公開を求めていいのではないかというふうに思うのですが、いかがでしょうか。国が全部、１０分の１０ですよね。ですので、ここは増額等も今後求めていただきたいと思います。","respondent":"櫻木生活福祉課長","answer":"それと、申請数が超えた場合ですが、こちらが超えてきた場合は、また状況によっては、再度補正予算等のご提案をする可能性もありますし、状況によって、また臨機応変に対応させていただこうと思っているところです。","id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今回の生活困窮者自立支援金は貸付ではないので、緊急小口資金も総合支援資金もコロナが特例で対象になって、そして、とても借りやすいということで、本当に社会福祉協議会のほうも大変な仕事量になってしまっているということはあるのですけれども、今回のこの事業は返さなくていい、給付型というところでは、本当に困窮者にとっては助かるものですし、自立につながっていくものだと思いますので。","respondent":"鷹箸保健予防課長","answer":"未遂者への支援ですけれども、いろいろと相談の中で、過去に未遂の経験があったというような事例については、これまでも保健センターでの対応の経験がありますが、今回の未遂者に関しては、実際に救急車で運ばれて、そこで既遂に至らず、病棟まで上がって看護師とお話をして。","id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問","question":"区の職員としてもそういうふうな現場の経験をしたほうがいいのではないかと思うのですけれども、そこの協力関係というのは考えているのかどうか、伺いたいと思います。それと、予算額です。これが４８６万円ということで、もうちょっとかかるのかなというイメージだけなのですけれども、これはどういうふうに算定されたのか、内訳をお聞きしたいです。伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"今後ですが、こういった取組については非常に重要だというふうに思っておりまして、この補助金、コロナが終息した後も、もちろん自殺対策としての区の当初予算で要求をして、当然、これについては続けていく予定で考えているところです。","id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。約３億６,０００万円ですけれども、人件費とか、回線を引く経費とか、どういうものにどれだけかかるのか。こちらの場合はすごくかかるのだなと思ったのですけれども、どういう算定の仕方で、何にどれくらいかかっているかということを伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"その中には、人件費も含め、回線を引くお金も含め、会場確保のお金も含め、全て含まれていて、１人頭大体３万５,０００円程度というふうな算出になります。","id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、人件費が高騰していると、１人３万５,０００円というのは、１日ということなのですか。そして、１００回線と５０回線、要するに、１５０回線分みたいな数え方でいいのか、そこを伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"私の説明が不適切ですみません。１人頭というか、１回線当たりというふうにご理解いただければと思います。大変失礼いたしました。","id":"exchange-024"},{"speaker":"せお委員","kind":"質問","question":"自殺未遂者等支援事業のところなのですけれども、先ほど答弁があったように、救急で入院して、退院されるところからアプローチするみたいなお話で、双極性障害とか統合失調症の方は、退院される、症状が治ってきたところで自殺を図るという方がすごく多いというのは聞いていますので、そこの退院のところはすごく重要だと思うのですけれども、関係機関と連携したり。","respondent":"鷹箸保健予防課長","answer":"我々保健所のほうに情報が来るのはかなりずっと先でございまして、基本的には、今は区内の全ての病院との連携はなかなか難しいのかと思っておりまして、三次救急をやっている、初めは１つか２つの病院に、我々のほうでこういった事業を始めますということを、委託するＮＰＯと。","id":"exchange-025"},{"speaker":"せお委員","kind":"質問・要望","question":"今、ご答弁がありましたけれども、本当に、時間というところも重要になってくる、早さ、スピーディーなところも重要になってくると思いますので、ぜひ情報共有を。それは、オンラインだったりとか、情報共有システムだったりとかを、高齢者の包括システムのように、少しずつできていけばいいなと、そこを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"自殺対策支援事業について伺いたいと思います。それで、予算額が４８６万円というと、すごく少ないと思うのです。これだけの予算で、どういう体制で継続的なサポートまでやっていけるのかということがイメージがつかないのですけれども、そこら辺の具体的なところも教えてください。","respondent":"鷹箸保健予防課長","answer":"予算額が少ないという件につきましては、実際にどういう支援になるのかということですけれども、何分、自殺未遂者等支援というのは、特に自殺の重点施策の区の２つ目で、中年女性の取組という部分を取り上げていた中で、女性、特に中年の女性は未遂者が多いということが。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"本当に自殺等ですごく悩んでいる方も、私も相談を受けながら胸が痛む思いをよくするのですけれども、どこに相談して、どういうサポートを受けられるかというふうなところが、なかなか分からないままになっているというふうなところがすごくあるなと思いまして、そういうところで、保健所なり、「たいむ」だったりとか、そういうふうなところにつながったら、ぜひフォローしていただきながら。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"高橋（し）委員","kind":"質問","question":"自殺対策のほうなのですけれども、こちらは保健予防課のほうでやるということですが、自殺未遂の方というのは、いわゆる学生である人が多いと思うのですけれども、学校のほうもどうかということではなくて、学校、教育委員会等に対してこういうことを保健予防課ではやっていますということの情報共有とか、そういうことについては、どのようにお考えか。","respondent":"鷹箸保健予防課長","answer":"特に先生たちを対象としたゲートキーパー研修も以前から実施しておりまして、こちらについては私立の学校の先生たちからのご希望も多く、先生方が受講しやすいように、毎年夏休み、８月に実施しておりまして、ちょうど今、募集をしているところです。","id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"賛成をいたしますが、それぞれ要望というか、意見だけ少し述べさせてください。それで、先ほど、入札と言っていたのだけれども、指名、一般、様々な入札の在り方があると思うのですが、私は、２００万円というと、結構心配しています。プロポーザルでもいいし、最終的には随意契約ということもあるかもしれないけれども、安かろう悪かろうというふうにならないように、ぜひお願いしたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問","question":"この２つの条例で、「温泉を貯留する槽のみに」ということですので、お湯ではなくて、温泉ということでいいのですか。それで、温泉を貯留する槽があるのが区内にどれくらいあるのか、分かれば伺いたいのと、あと、モノクロラミンの消毒というのが、塩素系薬剤による消毒とその他の方法というところでモノクロラミンということは、そういう清掃の衛生措置の基準が強くなったと考えていいのでしょうか。","respondent":"鈴木生活衛生課長","answer":"年齢制限につきましては、やはり国のほうで研究成果が出されまして、本来の公衆浴場の目的や、それから性的な犯罪被害の防止という観点でふさわしいと考えられたものであって、これも国全体で、各都道府県、それから市区町村で、今、順次改正が行われておりますので。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、消毒のところですけれども、塩素系の薬剤とほかの方法ということは、要は、基準というか、使う薬剤が塩素だけではなくて、その他の薬剤も使って衛生を保ちましょうということで、だから、少し強化されたという見方になるのですよねということと、あと、年齢制限のところは、守られない場合に、公衆浴場が注意するということになるのですか。","respondent":"鈴木生活衛生課長","answer":"モノクロラミン等の消毒の方法ですが、具体的に文言でご説明しますと、今までは基本となる塩素系の薬剤による消毒によりがたい場合は、塩素系薬剤による消毒とその他の方法による消毒とを併用するなどという形で、規定には具体的な例が、表現が出ていなかったものです。","id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問","question":"第４２号議案のほうの混浴の年齢のところなのですけれども、国の要領などで引き下げるということですが、東京都でも生活衛生審議会の答申で同じようなことが言われていて、７歳以上に引き下げることはいいのですが、この中に、「介助の必要な子供が入浴の機会を確保できるよう」にとあるのですが、その点について、どのようにお考えでしょうか。","respondent":"鈴木生活衛生課長","answer":"ご質問の、特定の配慮なり介助が必要なお子さんに関しての部分については、実は特別区の生活衛生課長会に都から課長がいらっしゃって、説明があったときに、やはり同様の質問が出ました。","id":"exchange-033"},{"speaker":"若林委員","kind":"確認","question":"旅館業のほうと公衆浴場、両方共通する気泡発生装置等のところは、経過措置がありまして、既存のものは適用しないと。区民には直接の影響はないということなのですが、これに関わる、事業者の新たにしなければいけないこと、負担等、それを１つお聞きしたいのと、定期的な区の検査、構造物の確認とか、区のほうで何かやられるのか、その２点だけお伺いさせてください。","respondent":"鈴木生活衛生課長","answer":"新規の方につきましては、当然、新規の申請のときに、構造設備基準などを説明いたしまして、実際に設備の設置をする前に、この規定に沿ったものを設置してくださいというような指導をする形になりますので、こちらについても。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、そこら辺をどう担保していくというか、区はその辺をどのように考えているのか。それで、今まで愛成会で働かれていた方というのは、運営事業者が変わることで、皆さんがほかへ行ってしまうということなのでしょうか。そこを伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"職員につきましては、職員個々のご自身のご判断というのがありますので、現時点でどれくらいの職員に残っていただけるかということはお答えすることができないのですけれども、いずれにしましても、ご利用者が安心して継続してサービスを利用できるような体制ということで。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問","question":"その子が一つひとつやること、行うこと、これがどういうことなのかというのを見極めながら、今何を楽しく思っているのか、そして、安定しているのかというのを、一人ひとり考えて研究しているという姿勢があるわけです。それが丸々引き継がれるというのは、運営事業者そのものの姿勢や理念等も違ってきますので、そこは完全に保証できるとはならないと思うのですけれども、そこはいかがでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"もちろん集団のプログラムも用意されておりますし、集団のプログラムの中で取り組める方は取り組んでいますし、少しそういうことが苦手だという人は、個別性を重視した個々のプログラム等々、その人その人に合わせた支援が現在も行われているところです。","id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうやって課長は口ではおっしゃるのですけれども、やはり皆さん、陳情にもありますけれども、今、課長がおっしゃっていることと感じられていることが違うわけです。そういったことをどのように考えられているのでしょうか。ですので、継続を望まれているし、再考を強く求められていると思うのですけれども、そこはどのようにお考えでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"支援の在り方なのですけれども、同じ説明になってしまうかもしれないのですが、その人らしい生活をということで、個別性を重視した利用者中心の支援が共に行われているということで認識をしております。次期指定管理者になった際も、同様にサービスを継続していくです。","id":"exchange-037"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、守ります、やっていきますというのではなくて、そこをどう保障できるのかというのをしっかりと示していただきたいと思いますし、そういうやり方を、福栄会が今までの自分たちの施設での延長ではなく、ぐるっぽではそうした支援ができるというふうになることが必要だと思うのですけれども、区としてはそこをお考えでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"支援につきましては、丁寧に引継ぎを行っていきます。その中で、個々のご利用者様の具体的な支援ですとか、支援方針というものも引き継いでいきます。","id":"exchange-038"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本当に利用者、当事者の皆さんの日々の暮らし、どういうことに困られていて、どういうことを求めていてという、そこにしっかりと向き合ってきた愛成会、ぐるっぽの体制を、私は本当に改めて確保していただきたいと思いますし、今からでも改めて再び考え直すということをしていただきたいと思います。そこの現状を教えていただきたいのですが。","respondent":"築山障害者施策推進担当課長","answer":"１点目ですけれども、今回の公募の趣旨といたしましては、障害児者総合支援施設の設置目的である、区内の障害者の福祉増進を図るために、拠点施設として運営するにあたって最も優れた指定管理者を選定したものですので、拠点施設として機能できるよう、取り組んでまいります。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問","question":"福栄会では得られていなかった支援が愛成会でしっかりされるようになったと、皆さん口をそろえておっしゃいますので、区もそこは認識しているということでいいのですよねというのを伺いたいのと、あと、日精看のほうは、大人のほうも今は受け入れられている。それは、非常勤の先生がいらしているということなのでしょうか。それとも、障害児担当の先生が一緒に診られているということなのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"１点目のご質問ですけれども、現指定管理者も次期指定管理者も、同様に利用者に寄り添った支援が行われているという認識をしております。ただ、障害児者総合支援施設につきましては、新しく造ったばかりですので、ハードが非常に広い空間だったりします。","id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問","question":"日精看のほう、区として望ましい体制として、院長は障害児が担当だということをお聞きしていますし、そうしたら、やはり大人の担当の先生も必要だと区は考えているのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"日精看の部分でいいますと、上の児童学園の部分の連携というところで、協力をしてもらっているところです。診療等につきましては、これは日精看の判断で職員の配置等をされているものと認識しております。","id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問","question":"だから、最初の駆け出しの、歩き始めのところからつまずいたということなのではないかと思うのです。そこから人員確保が、医者を確保するというのは本当に大変ですし、それが精神科医になってくると、そこもなかなか難しいと思うのです。大人の担当の医者も必要だと考えている、それがニーズと捉えているのか、そこを伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"区の支援というところでいきますと、日精看が運営するにあたって、区のほうも補助という形で支援をしております。それから、ニーズの部分ですが、精神障害の方の、福祉的な視点での通いの場というのも不足している部分がありますので、拡充していく必要があると考えています。","id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問","question":"その中で精神科クリニック、デイケア、訪問看護、そうした様々な施策につながっていくというのが利用者の皆さんの思いだとは思うので、改めてそうしたニーズを、陳情にも書いてありますけれども、行政単独の企画ではなくて、当事者と協議する場をつくって良質なサービスをつくっていく必要があると私も思うのですけれども、そこら辺はどのようにお考えでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"当事者との協議というところでいきますと、計画策定にあたりまして、当事者の方に入ってもらったりですとか、ヒアリングをしながら、どのような施策が必要なのかを考えていっているところですので、引き続き、障害のある当事者、障害者団体の方を交えて。","id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１つ伺いたいのが、日精看なのですけれども、もともと４つの団体で一つという形で今の障害児者総合支援施設をやるということで、同じグループの中で日精看も誘われて来たという経過があったと思うのです。","respondent":"築山障害者施策推進担当課長","answer":"ですので、日精看のほうから、また期限が切れる段階で申請が上がってくるということで、それを受けて区が許可をするかどうか判断をするということで、１年単位で行っておりますので、日精看の経営判断もあることなのかと考えております。","id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"貸付けということは、ここでも説明を受けてきたので分かっているのですけれども、その期限というのは１年ごとで、日精看がまた１年ごとの契約という形でしていくということで、まだ方向性としては、継続していくのか、それとも、３つのグループが福栄会に変わることによって、一緒に撤退するのか、そういう方向性というのは全く決まっていないということなのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"日精看の事業は、指定管理とは別ですので、今回のプロポーザルとは関係はございません。継続するかどうかにつきましては、日精看の経営判断によるものなのかと捉えております。","id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"分かりました。別の方が、「生活全般について、いろいろと教えてほしいが、やってもらえていない。シャワーでも使用したいと要望を伝えたが、使用できないとの返答があった。本人が安心して楽しく過ごせる場であってほしい。この違いという点については、区としてはどう捉えられているのでしょうか。そのことが私は問われていると思うのですけれども、その点についてはどう考えられているのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"ただ、支援につきましては、最初からご説明していますとおり、どちらの法人も、個別性を重視して、利用者に寄り添った支援、それを基本的な考え方として取り組んでおりますので、両者共に利用者中心に取り組まれているという認識です。","id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、区としては、この事業者はまだサービスを利用する人と人員体制のそこの違いのために、この質が出てきているのだと。この体制が同じようになれば、福栄会も、今のグロー、ゆうゆう、愛成会も変わらないのだと。そういうことで考えられているということでしょうか。体制上の問題が普通に表れたと考えられているということでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"体制上の問題につきましては、アンケートを取る時期等によって、前提となる条件が違うのかという認識をしておりますけれども、支援につきましては、体制が同じだったら同等かというご質問ですが、それは最初から、同じ説明になりますけれども。","id":"exchange-047"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"同じ体制であれば、同じような形で、例えば、今のぐるっぽの体制で福栄会が同じような形でやれば、今のぐるっぽの質は担保できると考えているのかということなのですけれども、この点はいかがですか。","respondent":"築山障害者施策推進担当課長","answer":"今の愛成会の体制は、立ち上げ期ということで、定員に応じた職員配置をしております。福栄会になった場合も、同様に定員に応じた職員配置になりますので、体制は適正な配置で実施をしていくことになります。","id":"exchange-048"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そういうところもあると思います。でも、実際は、中身としてちぐはぐしているというのが皆さんの感覚なのです。そういう、質をどう担保していくのか、そこのところは、これだけ満足度が違うということが歴然と出てきたわけですから、私は区がそこのところにしっかりと目を向けて、そこのところを引き上げていくという対策も必要なのではないかと思うのですけれども、その点ではいかがでしょうか。","respondent":"松山障害者福祉課長","answer":"もちろん、それぞれきちんと相談支援事業所をはじめ、生活介護の事業所は、その方に対して、ご希望ですとか、どういう過ごし方をしていきたいかということを丁寧に聞いていただくのが通例ですし、その方に合ったサービス、そして、寄り添った支援というのは。","id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そういう点では、今回、グロー、ゆうゆう、愛成会、この３者がそういう形で期待に応える中身をやっていただいていると思うのですけれども、その点で、さらに例えば、選択肢をなくさないというところで、今回、ぐるっぽが福栄会に変わるというのは私たちは反対しましたが、指定管理者で決定されましたけれども、例えば、区内でこの事業所に別の場所で相談事業所、発達支援センター、それから、生活介護。","respondent":"松山障害者福祉課長","answer":"生活介護につきましては、また特別支援学校の卒業生の動向を見ながら、今後、つくっていく形になろうかと思います。その際につきましては、やはり公募という形を取らざるを得ないかと考えております。","id":"exchange-050"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は、やはり現在の指定管理者をぜひ継続、これだけ当事者の方たちが継続を求めているわけですから、継続をすべきだということで、指定管理者そのものに対しても反対をしましたけれども、改めてこういう陳情が次々と上がってくる中で、ぜひ再考していただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今、委員長からのお話でありましたが、理由は陳情第２５号、２９号、３４号、一括してお話をさせていただきたいと思います。第２５号については、不採択でありますけれども、理由としては……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"石田（秀）委員","kind":"意見","question":"結論を出すで、不採択。それで、結果として３年の指定管理となったということであります。その中で指定管理を行って、いろいろ今やってきたけれども、我々の耳にも、大変よくやられていると。今、こういう段階でもう何度もこういう話をずっとしているので、あれでありますけれども、個々のものについては、我々としては不採択ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"若林委員","kind":"質問・要望","question":"４月から福栄会が入ってくる。今月には説明会がある。そして、いよいよ来年の１０月には指定管理が変わるという、まだ１年以上ある中で、この不安をずっと抱えて、現在のぐるっぽに通うという状況が続くわけですよね。実際に１０月からはすばらしい見事なサービスの質の現状、さらには、満足度がさらに上がるような、そういう施策展開、また、事業所へのご指導をしっかりお願いしたいということは要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"せお委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。今、自民党、公明党がおっしゃっていたように、私にもいろいろなご意見をいただいています。先ほどもお話がありましたけれども、やはりこれだけ声が上がるということは、現場にいらっしゃる職員に特に質の高い方が多いのだと思いますので、ここの現場にいる職員にできるだけ残っていただく努力を必ずしていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"石田（ち）委員","kind":"質問","question":"本日結論を出すで、採択でお願いします。先ほど鈴木ひろ子副委員長も紹介した満足度の違いというのは本当に歴然ですし、そういう中で不安を抱えられているというのが、運営事業者が変更するという、このときからずっと出されていたわけです。変わらないでほしい、残してほしいという。引き続き、丁寧な説明等だけではなくて、やはり担保できる体制を取っていくことが必要だと思いますので、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"高橋（し）委員","kind":"質問","question":"結論を出すで、不採択でお願いします。現在の事業者と新しい事業者で丁寧に引継ぎをしていくということ、それから、サービスの継続に関して安心して利用できるように、個性や特性を重視されるということをご説明で伺いましたので、不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この陳情にもありますけれども、１２年間福栄会に通われた、そして、昨年からぐるっぽに通ったという経験が、本当に全てを語られているという思いがしています。これは本当に当事者や家族にとっては不安であり、大変に生活が不安定になっていくということにつながりますので、ぜひそこをしっかり見ていただいて、当事者の思い、願いを最優先に、改めて今からでも考え直していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"結論を出すで、採択でお願いします。当初言っていた精神科クリニックと精神科デイケア、そして精神科訪問看護、こうした事業が行えるように、さらなる支援を区がしていくべきだと思いますし、さらに当事者が行政機関と意見交換する場、そういったものを当事者参加でぜひしていただいて、この陳情にあるように、良質なサービスをつくっていくことを求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、前回の議論なども踏まえて、陳情の中では、八潮にもあってしかるべきなのだということが述べられています。高齢化率が１％程度下がっているのです。これ、ずっと急速に八潮だけが高齢化が進むという状況を見ても、シルバーセンター、高齢者の健康の維持増進、生きがいづくりというのを支援する場があっていいのではないかと、余計に私は思うのですけれども、そこら辺はどのようにお考えでしょうか。","respondent":"菅野高齢者地域支援課長","answer":"委員ご指摘のとおりの高齢化などというところのお話はあるのですけれども、一定のニーズがあるということも捉えてはいるところなのですが、やはり入浴施設を造ることへの費用対効果とか、あと、他の施設の改修計画なども検討されている中で、様々な要素がある中で。","id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ほかの施設がありますというのはずっとご説明されているのですけれども、やはりシルバーセンターの設備というのはないわけですから、高齢者の健康の維持増進、生きがいづくりというものに特化した施設、設備、備品がないわけですから、そこは４０万区民に対して１万１,０００人で３％なのだとおっしゃるのですけれども、でも、高齢者は多いわけですので、そこはぜひシルバーセンターなので。","respondent":"菅野高齢者地域支援課長","answer":"ぜひ造ってほしいというご要望だと思うのですけれども、先ほどもご説明させていただきましたが、シルバーセンターが老朽化して、シルバーセンターを改築するときには、多世代の区民の方が交流できるゆうゆうプラザに転換を図ってきているというところから。","id":"exchange-061"},{"speaker":"石田（ち）委員","kind":"質問","question":"八潮だけが特出しているというわけではないと思いますし、そういうソフトの面も必要だと思うのですけれども、やはり高齢者が優先されるというのですか、ゆうゆうプラザもそうですよね。八潮だけない。ですので、八潮にないシルバーセンター、ゆうゆうプラザ、そういったものを今から検討してもいい段階ではないかと私は思うのですけれども、区の考えをお聞かせください。","respondent":"菅野高齢者地域支援課長","answer":"そこにあたっては、シルバーセンターやゆうゆうプラザのような高齢者に特化した施設ではなくても、既存のこみゅにてぃぷらざ八潮や、あとは八潮地域センターなどでも対応できるのではないかということで、再三説明をさせていただいている次第です。","id":"exchange-062"},{"speaker":"石田（ち）委員","kind":"質問","question":"ソフトの面からという通いの場、身近な地域の皆さんでというのは、八潮は大きく進んでいる状況なのでしょうか。そしてまた、さらにもっともっと取り組んでいくという状況なのでしょうか。","respondent":"菅野高齢者地域支援課長","answer":"通いの場に関するご質問だと思うのですが、こちらは昨年度から取り組んでおりまして、本年度、リハビリテーションの専門職の方とともに通いの場の条件整備等をして、地域の方に働きかけていく施策です。","id":"exchange-063"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほど区の施設の改修計画のときということで言われたと思うのですけれども、本当にシルバーセンターではなくても、多世代交流のゆうゆうプラザになっているので、私はゆうゆうプラザでいいと思っています。区の施設の改修計画のときというのは、どんなときになるのか。老朽化したものを改修するということになると思うのですけれども、おおよそいつ頃みたいなことは、分かっていたら教えていただきたい。","respondent":"菅野高齢者地域支援課長","answer":"八潮地区における他の施設の改修計画というところなのですが、改修の計画というのは区全体で立てるものなので、こちらの所管として、この施設が何年頃にということは、今、この段階ではお話はできないというところです。","id":"exchange-064"},{"speaker":"石田（秀）委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。理由を言います。だけれども、我々もそのときに何回も言いましたけれども、当時１万４,０００人弱の人口だったけれども、それで活用できるのだろうかという話をしてきたのだけれども、結果として、やはりなかなか活用ができなくて、行政の部分も相当入れ込んできて、大変ご苦労いただいてきているところがあるということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"結論を出すで、採択でお願いします。それで、先ほどの地域の皆さんでつくる通いの場というのも、これから期待するという状況ですので、それも含めて、やはりハード面でも高齢者の方が健康増進・維持、生きがいづくりとして使えるシルバーセンターまたはゆうゆうプラザというものを造っていくという検討を始めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/779921?Template=document&Id=3600#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":63386,"voices":231}},{"id":"r03-20210706-8","meetingId":"r03-cm07","date":"2021年7月6日","dateIso":"2021-07-06","committee":"建設委員会","time":"午前１０時００分～午後 ２時４４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を91件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"のだて委員","kind":"意見","question":"審議の支障がない程度で、動画撮影、頭撮り以外でも認めるべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回の事故が前方の不注意ということでしたので、今までは後方などというところだったと思うのですけれども、ちょっと一段安全性をさらに重視していただかなければいけないと思います。この事故が起こった原因を分析して、再発防止に力を尽くしていただきたいと思います。その原因と再発防止について伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"正面の事故ですが、運転手のほうが１つ先の信号の右折、そこに気を取られてしまって、前方の車両のほう見ることができなく、そのときに追突したというものです。今後、このような事故を検証しまして、再発防止に向けて指導徹底のほう行っていきたいと考えております。","id":"exchange-002"}]},{"id":"topic-02","title":"第４３号議案、品川区立環境学習交流施設条例","agenda":"第４３号議案、品川区立環境学習交流施設条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"なぜ公園の中なのだということで、公園の中につくるということに当たって、利用者の理解が必要だと思うのですが、区の考えを伺いたいと思います。そして、今回この施設、指定管理者制度を活用するということなのですが、なぜそれを活用しようと考えたのか、その理由を伺いたいと思います。区の直営の施設としてもできるのではないかと思うのですが、いかがでしょうか。","respondent":"河内環境課長","answer":"利用形態の工夫といたしまして、区民の方からこういった声が寄せられておりまして、今回これを設置するに当たりまして、ＣＯ２の排出など温暖化対策の声も高まったという点もある、また、緑の大切さを今以上に皆さんにご理解いただく必要もある、また。","id":"exchange-003"},{"speaker":"のだて委員","kind":"確認","question":"変更点については、遊具とじゃぶじゃぶ池以外にはないということでいいのかというところを確認します。","respondent":"河内環境課長","answer":"は細かい点で何点かあります。全体的に温室効果化ガスの対応など、ＣＯ２排出に向けてＥＶなどの普及促進も世の中では大変時流として起こっていることからも、急速充電器の設置につきまして変更といたしました。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"この住民の声のところで、環境問題の意識が高まったので、緑豊かな公園内にということなのですけれども、そこにやはり疑問の声が上がっていて、緑があるところを緑をなくしてつくるということですので、そこはしっかりと受け止めていただいて、住民の皆さんに説明をしていっていただきたいと思いますが、いかがでしょうか。","respondent":"河内環境課長","answer":"周辺環境などの配慮、いろいろな面で進めているところですが、理解促進へ向けまして、しっかりと周知をしていきたいというふうに考えております。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"しっかりと説明をしていっていただきたいと思いますし、あとこの施設はやはり公園内ということで、公園の雰囲気を壊さないように、なじむようにしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"西本委員","kind":"確認","question":"すみません、幾つか確認をさせてください。そもそも論から入りたいのですけれども、この環境学習交流施設というものは、いつ頃にどのような観点で出てきたものなのかをまず確認したいのです。","respondent":"河内環境課長","answer":"先ほどご説明したとおりで、今回のこの施設の大きな目的といたしまして、温室効果ガスの排出などの抑制についてという点もございまして、さらに今まで品川区といたしまして、主に周知、啓発などでいろいろな活動を行ってまいりましたが、他区の状況などを見ておりますと。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"ですから、もうこの施設、要はそのような施設をつくることによっての効果ということを期待できるものの、非常に難しいだろうと思っています。１つはリピートです。先ほども年間を通してということを、地域の方のご意見もあったということですから、ではリピートできないといけないということがあるので、それと目的がいろいろあると思うのです。この周りというのは食がないのです。食べ物が。","respondent":"河内環境課長","answer":"その際に、食についてなのですが、もちろん環境講座の中でフードドライブなども積極的に取り上げる予定でおりますけれども、近隣の方にケータリングなどを活用しながら、環境に関係するような食とともに。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"教育に関していうと、年齢によってテーマが違うと思うのです。山北町などもありますけれども、そのようなところからの協力を得ながら、食に対しての環境も含めて広げられたら、割と興味があって、今の特産物、今のなのでしょうか、旬の食べ物やどこどこのものですよとなってくると、意外と周りの人たちは、あそこに行くとおいしいものが買えるとか、だから物販もぜひ考えていただきたいのです。","respondent":"河内環境課長","answer":"その中で農業の知識と言うまでのことではないのですけれども、このように苦労をして育てて作っているのだという点は触れる予定ではありますが、実際の農業体験でいいますとスペースに限りがありますので、工夫をしながら検討を重ねていければと考えています。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"ですから、指定管理者制度を導入するということなのですけれども、広い考え方というか、広い発想の方々にお願いしたいと思います。区のほうも、そこはあまりやってはいけないなどではなくて、自由にやってもらうという余裕をもった形で指定管理者を決めていただければありがたいと考えていますので、ぜひリピーターということで、継続できるようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"本多委員","kind":"質問","question":"条例では品川区立環境学習交流施設ということなのですが、愛称や通称など、その辺を教えてください。それともう１点なのですが、環境施設なので、やはり環境に配慮した施設であるべきだと思うのです。ＣＯ２を削減するお手本になるような施設であるべきだと思うので、その着眼点から、空調がどのようになっているのか、何か工夫などを施してあるのか、その点を教えてください。","respondent":"河内環境課長","answer":"トータルで２２０件のご応募をいただきまして、現在その愛称の決定に向けて進めているところではありますが、８月の発表に向けまして、その前に議会のほうにご報告させていただきながら、進めてまいりたいというところで、現在進行中のところです。","id":"exchange-011"},{"speaker":"本多委員","kind":"質問","question":"分かりました。もう１点質問いたします。環境学習のところで、体験型を進めていくのは分かります。体験するのに農作物を耕す、それと同じような考えで、品川の風土というものをどこまで活かせるのかと、その点を教えてください。","respondent":"河内環境課長","answer":"家庭菜園などでは、いろいろそういった体験をできるのですが、残念ながら生き物に関しましては、実際に育成というのは変ですけれども、飼育することは非常に困難と聞いておりまして、アイデアとしては今のところ出ているのですが、なかなかいろいろ諸設備など。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問・要望","question":"中でも、特にＳＤＧｓと。これまでもうちの会派ではこれを訴えてまいりましたけれども、この観点、今の資料を見ても取り入れていらっしゃるということは十分確認できますが、改めて、このＳＤＧｓという理念に沿ったいろいろなプログラムというのですか、そういったものをしっかりと進めていただきたいなと。","respondent":"河内環境課長","answer":"現在進めているプログラムですが、こういった世界的な取組になぞらえながらも、我がまち品川の中でこのような点が大事だという点を併せまして、これがＳＤＧｓのここに当たるのだというようなところで進めるということで、現在やっているところです。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問・要望","question":"ぜひ指定管理者を選定するに当たって、そういった観点を十分に考慮しながら進めていただきたいと思います。たくさんの方に来ていただくには交通手段ということで、駐輪場が、またこれが十分でないと、近隣へのご迷惑ということが発生する大きな原因になるので、その台数がどれぐらいかと、その台数はどのような根拠でその台数とされたのかというところを確認させてください。","respondent":"河内環境課長","answer":"現在の環境講座や来場者の最大人数までは及びませんが、おおむねの来場人数が、瞬間的に、時間ごとにきちんと対応できる台数というところを見込みながら、限られたスペースの中で効率的という点をいろいろ考慮して、４０台という台数を設定したものです。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問・要望","question":"４０台で、これだと経験値的に大丈夫だというところなのですか。いろいろな区有施設、地域センターなどのところで経験値的に、これぐらいあれば、まずはあふれて近隣に何か駐輪被害が出るというようなことは起こらないというようなことの裏づけがあるものなのかということで、もう一歩踏み込んで確認させていただきたいと思います。","respondent":"河内環境課長","answer":"今後不足が生じないように、運用なども併せていろいろ進めてまいりたいというふうに考えているところです。","id":"exchange-015"},{"speaker":"塚本委員","kind":"質問","question":"利用料のことについてなのですけれども、減免・免除規定ということで、これは規則で今後定めていくという中で、活動を支援する環境保全活動団体・個人、町会・自治会、これは免除というようなことで、こういった免除というものの導入というのは、品川区の区有施設に他の例、どのようなものがあったのか、もしくは、私も不勉強で申し訳ないのですが、初めての試みのようなことなのか。","respondent":"河内環境課長","answer":"当施設におきましても、先ほど申し上げましたとおり、環境団体や、それから環境に対する個人など、発掘、支援、育成などを行うというところの位置づけの施設ですので、そういった団体は主に、やはり活動資金的にも乏しく、また予約などもなかなかできかねる。","id":"exchange-016"},{"speaker":"塚本委員","kind":"質問・要望","question":"なるべく幅広くというか、ハードルを下げて、最初はやはりスタートしていくということなので、それはぜひお願いしたいと思います。いわゆるキャッシュレスというものが今出回りつつある、もちろん現金支払いを否定するわけではないですけれども、キャッシュレス等の対応、ぜひ電子決済等を行っていけるようにということも、最後に１つ確認させていただきたいと思います。","respondent":"河内環境課長","answer":"これは理由がございまして、やはり主に公園内の利用者の方、あるいは利用者の方がキャッシュレスの部分をなかなかご存じない方も多いというようなところも踏まえまして、まずは現金からスタートしていきますが、そういった需要の高まりなどを受けまして。","id":"exchange-017"},{"speaker":"芹澤委員","kind":"提案","question":"４点ほどお伺いしたいのですが、１点目、これは単純な話で、エレベーターというものは、ごめんなさい、図面のどこにあるのでしょうかということが１点と、あとこの施設がＺＥＢというお話だったと思うのですけれども、Ｎｅａｒｌｙ ＺＥＢなどではなくて、ＺＥＢで５０％削減、８５％の数字が先ほど出てきたと思うのですが、ちょっとその辺の削減がどれぐらいで。","respondent":"河内環境課長","answer":"時間軸で環境を捉える体験型展示などで年間３万人程度の来場者を見込むということで計画をスタートしておりますが、何周回ってどの程度かというあたりをヒアリングを通じて、次のステップに移ったなという点と。","id":"exchange-018"},{"speaker":"大沢副委員長","kind":"意見","question":"簡潔に。一番の事業である展示物についてですけれども、これは丹青社ということで記憶をしておりますが、この丹青社について、担当としてどのような認識を持ち、どのような評価をされて、ここへ導入をされたのかを聞かせてください。","respondent":"河内環境課長","answer":"丹青社の認識です。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"賛成です。近隣住民にしっかりと話をして、理解してもらうように力を尽くしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-03","title":"第３６号議案、令和３年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第３６号議案、令和３年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"西本委員","kind":"質問","question":"区の職員ということなのですが、いつ、どのような条件のときに使うのか、それとも常にこのようなことというのはあるのですか。タイミングというか、あとは、例えばここのエリアは見ましょうとか、何かそのような計画があって使うということなのか、どのような条件なのでしょうか。","respondent":"河内環境課長","answer":"それで対策上、その現場のほうで判定する必要もある点と、それから石綿につきまして、どの程度の危険認識度があるのかという点をやはり現場で確認する必要がありますので、こういったものを効果的に使いながらという点で。","id":"exchange-021"},{"speaker":"西本委員","kind":"確認","question":"どのようなきっかけ、例えば建築確認か何かあって、そこで解体も含めて申請があるということで、そこでリンクするのか、それとも事業者の方々が何かありそうですなどというものがあって、それで申込みがあって、職員の人が行って確認して、それで指導するという形なのか。","respondent":"河内環境課長","answer":"特に中小事業者にとりましては、なかなかそういった分析もハードルが高いものですから、そういったところのアドバイスも含めてやるという点と、それから、事業者の方で解体や改修をご予定されている方が、直接窓口にお見えになります。","id":"exchange-022"}]},{"id":"topic-04","title":"令和３年陳情第２１号、区民住宅の住替えに関する陳情","agenda":"令和３年陳情第２１号、区民住宅の住替えに関する陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"こうした要望が出てきた下で、柔軟な対応が必要なのではないかと思うのですが、申し込めない理由は何か伺いたいと思います。陳情の中に、このままだと区外への引っ越しも検討せざるを得ないと記載されておりますけれども、区はこうした方が区外へ転出をしてもよいと考えているのか伺います。","respondent":"竹田住宅課長","answer":"それから交換ということですが、交換には今回は該当しないというふうに考えております。それから他の自治体への転居ということですが、品川区に長く住み続けていただきたいと考えておりますので、別の形でご支援できればというふうに考えているところです。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"住宅交換が該当しないということは、それはまだ相手先が見つかっていないので、まだそのようには進んでいないと思うのですけれども、このような場合でも、お子さんが育って手狭になってきたという理由であっても、住宅交換で合意すればできるということを確認させていただきたいと思います。それと住み続けたいというところで、ほかのことで対応したいということですが、どのような対応をされるのか伺います。","respondent":"竹田住宅課長","answer":"それから他の自治体ですけれども、基本的に公共住宅の方針というものは、ほかの自治体も似たような、もちろん詳細において違うところはありますが、品川区の公共住宅の考え方としては現在ご説明した内容で進めていきたいと思います。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはりこうした要望が実際に住民から出てきていますので、柔軟な対応をしていくべきだと思います。区はほかの対応でということですが、この住替えも含めて、ぜひ検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"西本委員","kind":"確認","question":"確認します。ここの場所は、具体的に間取りというものはどのぐらいなのでしょうか。間取りです。それと家賃は、恐らく条件によっては違うのかもしれないのですけれども、大体どのぐらいなもので、あと品川区の間取りに対しての金額というのは、大体何でしょうか、一般的な話でいいのですが、どのぐらいになっているのでしょうか。","respondent":"竹田住宅課長","answer":"今回陳情された方の間取りですが、２ＬＤＫの６３.１２m2のお部屋です。それから家賃の考え方ですけれども、周りの民間賃貸住宅を参考にしながら決定することということになっておりまして、一昨年に見直しを行って、一部賃料のほうを下げさせていただいたところです。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"家賃を下げたということですか。それとも、大体似たような、大体幾らぐらいなどと言えますか。大体でいいのですけれども。それと２ＬＤＫなので、６３m2だとすると、大体家族でいうと２から５人、５人はどうなのでしょう。でも品川区の中だと普通なのかなと思うのですけれども、その辺は一般的にどうなのでしょうか。","respondent":"竹田住宅課長","answer":"２年ほど前に近郊の家賃相場のほうを調査しまして、近郊よりも一部高くなっている部分については、少し下げさせていただいたところです。それから、今回の陳情者がお住まいの区民住宅の場合、２ＬＤＫですと大体１１万７,８００円から１４万５,７００円ほどになってあります。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"相場でいうと少し安めなのかなという感じはするのです。ですから、なかなか高いところに住替えするということは難しいことかもしれませんけれども、ただ品川区の現状を考えると、そうかなという感じがあって、住宅事情はこの方だけではなくて、品川区に住む以上は問題が多いと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"塚本委員","kind":"質問・要望","question":"本日結論を出すで、結論としては不採択です。その要綱の規定等を変えて申し込めるようにという思いだと思うのですけれども、こういった様々な公的な住宅、本当に住まいの話なので、この住まいということは本当に生活していく上で基本中の基本なので、大変に大きい選択、判断というものを求められるところだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"大沢副委員長","kind":"質問","question":"本日結論を出していただいて、不採択でお願いいたします。この方のこの個人的なものを認めてしまうと、ほかにおいてやはり公平性を害する、混乱を生じるという危険性もありますので、これについては承服できないので不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。やはり入居時に小さかったお子さんが大きくなって手狭になるということは、生活している上であることですので、もっともだと思いますので採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出していただきたいということと、不採択でお願いします。お気持ちは分かります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"進め方のところで、この４件の陳情はそれぞれの方が自分の思い入れで出していますので、そうした思いに丁寧に応えていくために、一括ではなく、一つ一つ審査していただきたいと思います。いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"効率的なということはコロナ禍ではあるかもしれませんが、やはりその中でも陳情を出してきていただいていますので、一つ一つ審査をしていただきたいと思うので、ぜひ各委員の意見も聞いていただいて、採決をしていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問","question":"第３１号についてなのですが、これは大井町で生まれ育った方が出されたものです。品川区を住み続けるところと位置づけていると書かれています。やはりそれを脅かすのが、あのＣ地区の再開発だということです。ここに心の叫びを聞いてほしいということも書かれておりますが、区はこうした声を聞き、反映すべきだと考えますけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"はやはり地域の方がどのように思われているのかということを、区としてもそのような形で聞かせていただいて、そこをどう進めるかについては、やはりまずはお聞きしながら一緒に考えていくということが、区としても取り組んでいくことだというふうに認識しています。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"１項目めでは、再開発を望んでいるかどうかということを調査してほしいということで、区はこの住民の意向を調査したことというのはあるのか伺います。２項目めで、このコロナ禍の下で再開発のための予算をこのコロナのために使ってほしいということで、私たちもやはりこのコロナ禍の下で、開発予算はコロナ対策に充てるべきだと言ってきました。区の考えを伺いたいと思います。","respondent":"多並都市開発課長","answer":"人権に配慮する、要するに住んでいる方々の生活に支障がないように、皆さんが安心して暮らせるようにという観点かと思いますけれども、それはそのとおりで、そのような観点で、皆さんで一緒にどのような形にそのまちを進めていくのがいいかということを。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問","question":"今は住民で考える、勉強している段階だというお話ですけれども、そうした中で再開発をやりたい人、やってほしくない人がいるわけです。そこで実際にどうなのかということを区として調査してほしいということですから、そこの合意形成を図っていくためにも、区として調査をしていくということは必要なことではないかと思うのですが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"まちのいろいろな課題、例えば東小路の建物の件であったり、市道の今の状態だったり、いろいろな課題があるということをお聞きしていますので、そのようなものを解決していくために、皆さんでどう行っていくかということが一番肝要かということも含めて、それがまず一番で。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"再開発とは決めていないということですが、そうであれば、いろいろな手法、どれがいいですかということで調査することもできると思うのです。そういった調査はしないということですか。必要に応じて調査するということでしたので、どのような状況になったら調査をするということなのでしょうか。","respondent":"多並都市開発課長","answer":"やはり勉強会、もしくは地元の方々、いろいろ今お話しいただいている状況、いわゆる検討のお話をいただいている状況、その中で、どうしても進める中でいろいろな方がいらっしゃる中の、どう進めていけばいいかということでかなりお困りになることもあるかと思います。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"次に第３２号についてなのですけれども、ここでは東小路を残してほしいということが書かれております。こうした修復型のまちづくり、いいところは残して悪いところを改善していくということで、修復型のまちづくりは私も主張してきたことですので、そうした考えを持つべきだと思いますけれども、いかがでしょうか。こうした開発は辞めてほしいということで書かれております。伺います。","respondent":"多並都市開発課長","answer":"それをどうしていけばいいかということが、１つの今の、何というのでしょう、答えの１つに修復型はもちろんありますけれども、皆さんでそこをどうしていくのがいいのかということをお話しいただく、そして、そこを形にしていく、１つにしていくということですか。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはりこの東小路のところは、古きよき街並みというのでしょうか、これが残っていて、やはりそこが好きな方も多くいらっしゃると思いますので、火災など、そういった危険性というのですか、課題があるということは私も認識していますので、そうしたところを予算を残しつつ、修復型のまちづくりを行っていくということが、やはり必要だと私は思っておりますので。","respondent":"多並都市開発課長","answer":"地域の方が皆さんで、どのような形でそれを進めていきたいかということをお話しいただくということが、やはり区としては一番重要だと思っていまして、そのお話し合いが円滑に進むように支援することが区の役割ということで、そのような形で。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"一括して聞きます。確かに密集市街地ではあるのですけれども、ただ商業をしている方もたくさんいて、いろいろな立場の方が、いろいろな方がいらっしゃって、なかなか考え方もばらばらで、１つになるのはまず難しいだろうなと。これ全部、４つに関しては不安なのです。どの陳情も不安から来ているものだと私は思うので、その辺の交通整理はある程度示すこともできるのではないかと思うのですが、いかがですか。","respondent":"多並都市開発課長","answer":"今の段階的なまちづくりの進め方という点ですけれども、まず区のまちづくり方針の中でも、段階的なまちづくりということで、今回大井町にも書かせていただいております。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"やはり透明性です。今何をやっているのという。確かにこの陳情の中には残してほしいということはありますけれども、あのような雰囲気を残すという残し方の問題であって、あのままを残せではないと思っているのです。まちづくりというと何か壊されてしまったとか、そのようになってしまっていると思うので、そうならないような状況にしてあげられるといいのかなと思うのですけれども、いかがですか。","respondent":"多並都市開発課長","answer":"そのようないろいろな方の思いが１つにならないと、事業としては進んでいかないところもありますので、それがいいのか、そうではない形の進め方がいいのかも含めて、皆さんでお話しいただいて、そこのまちがどう変わっていくかという、まずは細かいところよりは。","id":"exchange-042"},{"speaker":"芹澤委員","kind":"質問・要望","question":"その意味において、先ほど課長もご答弁いただきましたけれども、この再開発自体が、区がどうしても再開発をさせるというようなものではないと理解をしていますので、住民のそれぞれの意見の合意形成を待って、それのサポートをしていくということが区の仕事だと思っていますので、我々議会も行政側も、この今回の個々の意見に対して賛成、反対というところに対して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"塚本委員","kind":"質問・要望","question":"まちというのは不変ではございませんから、老朽化していくという中で未来を開くために手を入れていこうという考え方の方、やはり一切手をつけないでほしいという、そういった保守的な考え方、それぞれあるということは承知をいたしておりますけれども、ここに今の段階で、公的に議会として何かしらのサジェスチョン的なものを与えるということは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"大沢副委員長","kind":"意見","question":"本日結論を出していただいて、不採択でお願いします。今、自民党、公明党、両会派からもありまして、全く同感でありまして、本来まちづくりというものは地域の主体、地域主体に基づいて進められるべきであり、既にもうここの地域でも、反対、賛成を含めた勉強会等々が行われているわけでありまして、そのような意味では、今後の合意形成に向けた動きもある。以上によりまして、これは不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。再開発によって土地や建物を奪われることがないように、基本的人権に配慮してほしい、地域のつながりを壊さないでほしいということはもっともなことですので、また区民の思いを後押ししていくためにも、採択したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出すということで、趣旨採択でお願いしたいと思います。お気持ちは非常に分かります。ただ、今回出された４つの方々に関しましては、何かやはり不安なのだろうなという、その不安なお気持ちだけは私はしっかり受け止めさせていただきたいと思いますので、趣旨採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"塚本委員","kind":"意見","question":"本日結論を出すで、結論は不採択です。理由は先ほどと同じで、現時点で議会としての一定の方向性なり何なりというものを示すべきものではないです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"結論を出す、不採択でお願いいたします。理由は第３０号、これは後の第３２号、第３３号にも関係してまいりますが、理由は冒頭に述べた、第３０号で述べた理由により不採択としていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。私も求めてきた修復型のまちづくりをしてほしいということと、区民の生活を尊重してほしい、生活基盤を奪うＣ地区の開発をやめてほしいというものですので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。今の場所で家族みんなで住み続けたいということは、やはり当たり前の願いであり、それを脅かすのがＣ地区の再開発をやめてほしいということですので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"}]},{"id":"topic-05","title":"および(5)の陳情２件につきまして、関連する内容のため、一括して議題に供します。 進め方といたしましては、２件の陳情","agenda":"および(5)の陳情２件につきまして、関連する内容のため、一括して議題に供します。 進め方といたしましては、２件の陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"陳情第２０号のところで、この陳情は、国側の騒音軽減策として出した３.４５°の着陸降下角、飛んでいる便数を明らかにしてほしいというものです。やはり騒音軽減のためというのであれば、実態を明らかにすることは重要だと思いますので、ぜひこの機数を明らかにしていただきたいと思うのですが、区としては問合せなどはしたのでしょうか。","respondent":"鈴木都市計画課長","answer":"そうした意味で、既に問合せをしたかというご質問に関しては、まだ、当委員会終了後ということになろうかと思いますが、区としてはほかの声と同様に、国のほうにしっかり届けて、その辺の数字を示していただくように求めていきたいというところは考えとしてはあります。","id":"exchange-052"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、騒音測定器設置の陳情ですけれども、これは東大井集会所ということで地図も示していただいて、立会川駅の近くの勝島運河のところですけれども、ちょうど陳情にもあるとおり、ルート直下ということで、より住民の被害実態を明らかにすることが、ここに設置すればできると思うのですけれども、区の考えを伺いたいのと、実際にこの東大井集会所では飛行機の高度は何ｍなのか伺います。いかがでしょう。","respondent":"鈴木都市計画課長","answer":"こちらの集会所の施設については、いろいろ検討もしましたが、基本的に下が集会室でその上層部が、上階の２階から上が職員の寮となってございまして、４階建てになるのですが、屋上はフラットな屋上になっていまして、面としては広い面があるのですが。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、東大井集会所での検討はされたということですが、今回こうした陳情も出ていますし、立会小学校のほうは若干ルートからずれているのですね。やはり直下のところで測ってほしいというのは住民の願いだと思いますので、そこは東大井区民集会所でもぜひ設置をしていただきたいと思います。","respondent":"鈴木都市計画課長","answer":"設置の容易性ですとか定期点検の容易性ですとか、そうしたところと、あとは施設の、子どもが活動する施設というところを総合的に勘案して立会小学校に設置したものですので、今、現在。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"区として今、考えはないということですが、やはりこうした騒音測定器、多くつければ住民の実際の被害実態、より細かく分かると思いますので、実際にここに設置してほしいという陳情も出されているわけですから、ぜひ設置するようにしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"芹澤委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。説明いただいたとおり、ある程度データももう品川区のほうで把握されていらっしゃるということですので、わざわざ問い合わせるほどでもないのかなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"塚本委員","kind":"意見","question":"本日結論を出す、不採択でお願いいたします。今、自民党さんからもありましたけれども、大体傾向性は十分につかめるデータが出ているということがありますし、様々な区民のご意見については、区のほうにも例の窓口を通じて届いているということで、それに応じて今後も適切に対応していただくということがあるということで、この陳情については不採択ということでお願いをいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"本日結論を出すということで、不採択でお願いいたします。以上によって、不採択としていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"西本委員","kind":"意見","question":"本日結論を出すということで、採択をお願いします。役割分担は分かるにせよ、品川区のことでもありますので、監視という意味では、できるだけ情報は収集してということで、こう思うのは当たり前なのではないかなと思いますので、採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"芹澤委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。国も区も複数のポイントを作っていて、そのポイントの選定も今、総合的に判断してというお話がありましたので、さらに追加でというのは必要ないかと理解をしています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"塚本委員","kind":"質問","question":"理由としては、どこに設置するかということについては、個々にここに設置してほしいという思いはそれぞれいろいろな方々がお持ちかとは思いますけれども、それを一つ一つ採択をしていくということはやはり現実的ではないかなと。区のほうにいろいろなご意見をしっかり総合的に判断していただいて、適切な場所に設置していただくということでお願いをしたいと思いますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"本日結論を出していただいて、不採択でお願いします。設置場所については、区あるいは国との連携の下に最も合理的な場所に配置されていると考えておりますので、住民の方たちのお考えも分かりますけれども、それによって場所あるいは合理的でない場所も有り得るわけで、そこのところ、一つ一つ要望として受け入れることは不可能であると考えますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで採択を主張します。やはり、より住民の被害実態を明らかにするということで、騒音測定器を設置していくべきだと思いますので、採択します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"西本委員","kind":"質問・要望","question":"ここでおっしゃるように、ポンプ所のところは中間地点ということもあって、もちろん要望どおりに全部設置するのは不可能なことではあるのですけれども、場所によって騒音の大きさとか聞こえ方とかがいろいろ違うので、私はいろいろな環境において測定は必要だと思うので、できるだけいろいろな地点での実際のリアルの測定値というのは今後かなり必要だと思いますので、採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"}]},{"id":"topic-06","title":"令和３年陳情第２７号、品川道踏切にエレベーターの設置を希望する陳情","agenda":"令和３年陳情第２７号、品川道踏切にエレベーターの設置を希望する陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この品川道踏切、陳情にもありますけれども、開かずの踏切としてよく知られているということですが、遮断時間というのが分かりましたら教えていただきたいと思います。それで、陳情の中にも、階段はあるのですけれども、やはり高齢者とかベビーカーの方が上ることは困難だということが書かれております。こうした区民への支援が必要だと思うのですけれども、いかがでしょうか。","respondent":"溝口道路課長","answer":"今現在でいきますと、大井町の東西の自由通路が、エレベーターつきでバリアフリーの動線が確保されている状況になりますので、少し遠回りにはなりますけれども、歩行者のベビーカーを押した方、または車いすの方、高齢者の方。","id":"exchange-065"},{"speaker":"のだて委員","kind":"質問・要望","question":"遮断時間が５時間にわたり４０分以上あるということで、開かずの踏切の指定もされているということでしたので、やはり区民への支援が必要だと思いますので、スペースが確保できれば区としてもやりたいということでしたので、ぜひスペース確保していく方法を考えていただきたい、検討していただきたいと思います。いかがでしょう。","respondent":"溝口道路課長","answer":"そういった中で、やはり大井町駅周辺のまちづくり、そういったところの動向を捉えながら、スペースの確保、また、歩道橋の関係、そういったところも含めまして、さまざま検討しながら進めていきたいですので、いずれにしましても。","id":"exchange-066"},{"speaker":"のだて委員","kind":"質問・要望","question":"ＪＲとも協議していただいて、設置できるように力を尽くしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"西本委員","kind":"質問","question":"事故に遭わなきゃいいなというぐらい滞留してしまうのですよね。それと、自転車がたくさんいるので、むしろ私は自転車を何とかすれば、少しは危険性を回避できるのかなという思いがあって、ここの歩道橋の持ち物、それから管理というのは品川なのでしょうか。ＪＲも関わってくるとなると、ＪＲがやるとは思えない部分があるのですけれども、管理者というか、権限はどちらにあるんでしょう。","respondent":"溝口道路課長","answer":"大井町歩道橋の管理につきましては、品川区の道路課のほうで維持管理をさせていただいている橋梁です。","id":"exchange-068"},{"speaker":"西本委員","kind":"質問","question":"せめてエレベーターは、それなりのスペースが必要になってしまうのですけれども、スロープをつけるとか、自転車が通れるようなスロープを、ちょっと構造的に難しいかもしれないですけれども、階段の幅も狭いので、そのスペースもとれないし、歩道も狭いのでなかなか難しいというのは理解できないことではないのですが、通路を通る人は下を通ってもらうとか、もうちょっと歩道橋を逆に延ばして。","respondent":"溝口道路課長","answer":"そういった中、やはりこれもエレベーターと併せて、例えば大崎駅のそばの百反歩道橋の架け替えの際には、エレベーターを設置し、かつ、歩道橋、階段にスロープをつけて、自転車も上がれるように整備したという経緯もありますので、同じように。","id":"exchange-069"},{"speaker":"西本委員","kind":"質問・要望","question":"それと、すみません、陳情と全然関係ない話になっちゃうのですけれども、この下の喫煙所のほうは、ここ、本当に関係ないので申し訳ないのですけれども、喫煙所のほうは非常に問題が起きておりますので、まちづくり全体を考えるならば、道路、そして歩道橋、そして喫煙所、それを全部総合的に考えていただきたいと思いますが、いかがでしょうか。","respondent":"溝口道路課長","answer":"所管が異なりますので、いろいろ苦情が来ているという話は私どもも聞いているところですので、喫煙所についてはしっかり所管と考えていかなければいけないところだと考えていますし、委員言われたように、ただ歩道橋を整備すればいいという話じゃなくて。","id":"exchange-070"},{"speaker":"塚本委員","kind":"質問","question":"現状、今、これだけしまっているよというお話は伺ったのですけれども、運行ダイヤ等でのいろんな調整については、区として意見を言っていったりとか、有り体に言えば、うまく時間帯をそろえて、少しでも踏切を開けられるようにするような工夫を区のほうから申し入れたりとか、話し合う場があったりとか、何かそういうことというのはある程度できるものなのでしょうか。","respondent":"溝口道路課長","answer":"踏切の遮断時間のご質問のときにお答えしましたが、２０１４年の調査では５５分だったものが、最近の調査では４４分に変わっている、そういったところでは、ＪＲのほう、ダイヤ改正等をしながら、工夫しながらやってきていただいているという実情はあるのだとは思っております。","id":"exchange-071"},{"speaker":"芹澤委員","kind":"質問・要望","question":"思いは非常に分かるのですが、区も課題を認識していて、前向きに改善に取り組んでいきたいというお話があって、エレベーターを単純に設置すればいいという話でもなくて、なかなか歩道とか車道の問題もあって非常に難しいというのも分かりましたので、もう少しペデストリアンデッキじゃないですけれども、再開発とか、そういうところも広い視野でご検討いただきたいという思いを含めて、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"塚本委員","kind":"質問・要望","question":"本日結論を出します。できることならつけたいということもよく分かりました。ただ、現実的に場所がないという中で、あえて議会から区に対して、さらに何とか強く要望するというところについては、やはり現実的になかなか難しい中で、それを採択していくということは、やはりやや無理があるかなと感じておりますので、不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"大沢副委員長","kind":"質問","question":"本日結論を出すで、不採択でお願いします。そこのところは非常に不確実なもので、不確定なものでありますので、ここのところのエレベーターを設置ということの断言については、願意に沿うことはできないと思いますので、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。区民の負担軽減というのを区としてやっていくということが必要だと考えますし、区議会としても後押しをしていくということが必要だと思いますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出すということで、趣旨採択でお願いします。ここは非常に危なくて、皆さんからの何とかしてほしいという要望はたくさんいただいております。なので、可能なことがあるならばチャレンジをしていただきたいなと思っていますので、ご検討のほど、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"}]},{"id":"topic-07","title":"令和３年陳情第２６号、しながわ区民公園北側ゾーン改修計画に関する陳情","agenda":"令和３年陳情第２６号、しながわ区民公園北側ゾーン改修計画に関する陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"こうした細かな声を区としては聞いているかどうか、伺いたいと思います。そして、やはりこういった声が上がっているので、再度、住民、利用者へのアンケート調査あるいは説明会を要望しますということでなっておりますが、ぜひこうした説明会、アンケートなどを行ってほしいと、住民の理解を得ていく必要があるというふうに思うのですが、いかがでしょうか。","respondent":"高梨公園課長","answer":"そういったご要望の声を受けまして、説明会の中でもご答弁申し上げてありますが、例えばパラソルの設置であったりとかという形で、日陰の設置についてはソフト面を含めて対応を進めていきたいというふうに考えているところです。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"３０年経つと、また更新等が必要になってくるということになると、結局、完成した姿が短過ぎるというのですか、そういうことになると思うのですが、そこのところ、どのように考えていらっしゃるのか、具体的に３０年後を見据えた更新としている部分がありましたら伺いたいと思います。","respondent":"高梨公園課長","answer":"老木への対応といったところですと、一定程度、年数ごとにしっかりと更新を行っていかないと、安全面等でも問題があるといったところがあります。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"３０年後を目指してと、よりよい形を作っていきたいということですけれども、やはりそういったことを含めて樹木を切る、切らないという声も多くありますので、ぜひ住民に対して説明会、アンケートを行って、より理解を得ていくということが必要だと思いますので、そこをぜひやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"本多委員","kind":"質問・要望","question":"教えていただきたいのですけれども、台風などでの倒木ということで、そういうことが起きているというのは分かるのですが、それの前に、事前に日頃の樹木の管理がどうなっているのか教えていただきたいのですけれども、例えば台風が来たらもう本当に倒れてしまいそうな弱っている木ですとか、中がもう空洞になってしまうとか、例えばキノコが生えているともう弱っているとか。","respondent":"高梨公園課長","answer":"そういったものが、やはり老木が多うありますので、特に今回はそういった年数が経っている木を中心に、また樹勢の弱っているところ等を見ながら伐採等をしていく、そのような計画としています。","id":"exchange-080"},{"speaker":"本多委員","kind":"質問・要望","question":"これからの公園のあり方ということで、防災機能も向上させていくということですから、点検もしっかりしていただきたいと思います。公園の利用者なのですが、当然、もう万人がそれぞれの目的で使うわけですから、意見もたくさん出ると思うのですが、先ほどの答弁でもありましたように、いろいろな意見を吸い上げて総合的に進めていくということですから、まさにそれが必要だと思うのです。","respondent":"高梨公園課長","answer":"皆さんの意見を１００％取り入れることはできないのですけれども、皆さんの考えに寄り添いつつ、区として区立公園がどうあるべきか、それぞれの公園に応じた状況は違いますけれども、そういったところをしっかりと見極め、それをまた真摯に皆さんにご説明をして。","id":"exchange-081"},{"speaker":"西本委員","kind":"質問・要望","question":"このしながわ区民公園北側ゾーンの改修計画は、前期の委員会でやりましたよね。報告いただいたと思うのです。今回、それを受けて、またこの陳情が出てきたということなので、こういう要望が、結構強めの要望があるのだなというのは私は認識があまりなかったので、実際、その説明会のときにはどんな感じだったのかをお願いしていいですか。","respondent":"高梨公園課長","answer":"資料のほう、１枚目の右下のほうに、説明会の主な意見と回答ということでお示しをさせていただいているところですが、やはり一番多かったのが、野球場の土埃に対する懸念という声が非常に多く寄せられたところです。","id":"exchange-082"},{"speaker":"西本委員","kind":"質問・要望","question":"思いがあるし、樹木に対しても本当に大切にしていただいている区民性なのかなと思うのですけれども、だからこそこういうのが出てくるのかなという思いがあるのですが、ただ、もう一つ質問としては、２回アンケートをしたというのは、何かそういう要望があったからですか。もうちょっと詳しく調べてみたいとかと、何かあって２回されたのでしょうか。","respondent":"高梨公園課長","answer":"２回のアンケートをした理由ですけれども、先ほど一回目のアンケートで示した案から二回目の間に変えましたということを説明させてもらったのですけれども、やはりサッカー場の新設であるとか北側ゾーンのしつらえを大きく変えるといったところは。","id":"exchange-083"},{"speaker":"西本委員","kind":"質問・要望","question":"通常、２回もしないと思うのですよね。１回で終わってしまうのだろうと思うのですけれども、２回された。全部の要望にお応えできればいいのでしょうが、それはなかなか難しいことだと思いますので、そこはご理解を求めていくしかないのかなというふうに思っておりますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"大沢副委員長","kind":"意見","question":"ただ、公園という、先ほど本多委員がおっしゃったように、万民のための公園ということの中で、理由の前に、サッカー場は要りません、北口を２つにする必要はありません、災害車両のために拡張する必要はありませんと言い切っていらっしゃいますけれども、これについてどういうふうにお考えになりますか。","respondent":"高梨公園課長","answer":"公園は万人のためというのもありますし、あらゆる状況で役に立つ公園であるべきだというふうに考えてありますので、やはり様々な方からアンケートという形、ヒアリングという形でご意見をいただいて作った改修計画案の中でお示しをさせていただいたといったところですので。","id":"exchange-085"},{"speaker":"大沢副委員長","kind":"意見","question":"それともう１点、青少年のスポーツ・レクリエーションのための公園から、高齢者の心と体を健康に保つための公園にシフトすべきと、こういうふうに断言されていますけれども、いろいろな公園があろうかと思います。そこのところというのは、もう既に年齢層、種類によって公園事業は区のほうで行われているということで私は認識をしておりますけれども、それで間違いないですね。","respondent":"高梨公園課長","answer":"繰り返しになりますが、公園はいつでも誰でもといったところですので、やはり地域に根差した小さい公園で、利用が高齢者の方が多いとか、子どもが多いというような差があってしかるべきだというふうに思ってありますが、区民公園におきましては、総合公園ということで。","id":"exchange-086"},{"speaker":"芹澤委員","kind":"質問・要望","question":"理由としまして、この要旨がアンケート調査、説明会の要望ということでありますけれども、先ほどからご答弁ありましたとおり、今回、かなり丁寧にご説明、ご議論があったのかなというふうに理解をしています。万人受けするというのはなかなか難しいのですが、引き続き広報はしていただきながら、非常時も含めて、あってよかったと思える公園をぜひ造っていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"塚本委員","kind":"意見","question":"そこには相入れない２つの意見が反目し合ってしまうというようなことは間々ありがちなことでございまして、また、近隣環境とのあつれきというか、こういったことは公園については常に付きまとっている課題、問題なのですけれども、そういったことの中でこの事業を進めていくに当たっては、やはり手続きあるいは進め方ということについて瑕疵なくやっていただくということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-088"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、趣旨採択を主張します。公園の改修やサッカー場は必要だと思いますが、いろいろな意見が出ている下で、再度、アンケート、説明会は必要だと思いますので、趣旨採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-089"},{"speaker":"西本委員","kind":"質問","question":"本日結論を出すと。不採択でお願いします。やはり、十分に、本当に丁寧にしていると思うのです。なので、これからも皆さんにご理解いただけるように、それでも１００％は理解できないところもあるので、諦めずに丁寧な説明をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"安藤議員の「住民を追い出し開発企業の利益を優先する、大崎西口駅前地区・品川駅南地区の超高層再開発は撤回を」の質問で、大崎の計画は、区域内全員を転出させる前提の計画を問題だと思わないのかとの質問に、区は、個々の選択の自由と答弁をしました。この個々の選択の自由とはどういう意味か、選択できないと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297355?Template=document&Id=4324#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":64985,"voices":266}},{"id":"r03-20210706-9","meetingId":"r03-cm07","date":"2021年7月6日","dateIso":"2021-07-06","committee":"文教委員会","time":"午前１０時００分～午後 ０時３１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"文教委員会のところになると思うのですけれども、安藤たい作議員の最初の質問、「ワクチン、大規模検査、十分な補償などコロナ収束に集中を感染リスクを広げ国民の命を危険にさらす東京五輪は中止を」というご質問の中に、学校連携観戦プログラムの中止を求めるという趣旨のご質問があったと思うのですけれども、区長のご答弁でしたが、区としてのお答えは、結局進めるという方向なのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"第４４号議案、学校教育職員の給与に関する条例の一部を改正する条例","agenda":"第４４号議案、学校教育職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"統括副校長を義務教育学校に配置することとか、配置の先ですね、あるいは職務権限とか役割についても資料に書いてあるのですが、条例上の文言でこういうのは規定しているのでしょうかというのを確認したいのが１点目です。そこら辺も伺いたいと思います。","respondent":"工藤指導課長","answer":"具体的には異学年での移動教室を行っているところもありますので、そういったところで、一貫教育そのもののいわゆる連続性などを担保する上では、中心的な存在というふうに私ども認識しています。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。私は、そういう点で一貫教育というのは見直すべきなのではないかと思っているのですけれども、いかがでしょうか。","respondent":"工藤指導課長","answer":"あわせて、私ども、教科担任制を５年生から推奨して行っているところですが、担任との関係性を一定程度継続しつつ、複数の教員の目で児童・生徒を見るという観点でいえば、教科担任において様々な教員の目が行き届くという面で効果があると認識しておりますので。","id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"今、区教育委員会のお考えは聞かせていただきましたけれども、納得できるものではないのですが、今後、私も、小中一貫教育について、子どもにとって何が最善なのかという観点で、現場の方や当事者のお子さんとも話しながら、さらに研究・提案をしていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"松本委員","kind":"質問","question":"資料としてつけていただいているＡ３のものなのですけれども、この中に組織図というところがあります。校長と統括副校長が並列的に記載されておりますが、組織上、指揮権が重複する部分はあるのか、そうすると混乱も生じ得ると思うのですが、その下の権限・役割のところで書き分けがなされておりますけれども、指揮命令系統が重複する部分はあるのかどうか、伺ってもよろしいでしょうか。","respondent":"工藤指導課長","answer":"これは平成２８年に義務教育学校になるまで継続したのですけれども、その場合には、都費校長同士ですので、きちんと役割分担をし、基本的に学校運営について支障はなかったと私どもも認識しています。","id":"exchange-005"},{"speaker":"松本委員","kind":"意見","question":"固有教員を選んだことによって、キャリアの一番進んだ先が統括副校長になるということだと思うのですが、統括副校長から、いや、それでもやはり校長になりたいのだと思った場合に、どういう選択肢があり得るのかというところをお示しいただければと思います。","respondent":"工藤指導課長","answer":"そのほか様々な施策、手だても考えたところですけれども、まずもっては定数１であるという、また、県費負担の教員に限るというところになりますので、そういったものが必要になるということがあります。","id":"exchange-006"},{"speaker":"松本委員","kind":"意見","question":"会社が普段いろいろと経営はしているけれども、最終的な人事権は親会社が持っているという、ある意味、不思議な状態だと思うのですが、これは多分条例で、そもそも県費のほうの権限を区に全部移譲することは、やろうと思えば最終的にはできると思うのですが、その辺りは可能かどうかというところをお願いいたします。","respondent":"工藤指導課長","answer":"ただ、まずもってそれが、都教育委員会が広域行政の公平性などを担保するというところで、まだかなわない部分はありますけれども、そういった声は都教育委員会に届けているです。","id":"exchange-007"},{"speaker":"吉田委員","kind":"確認","question":"基礎的なところを伺いたいのですけれども、Ａ３資料の最初の現状のところで、平成２１年度の採用から令和３年度までに２７名を採用となっているのですが、１３年間になりますかね、に採用されたのが２７名ということで、今、何人ぐらいいらっしゃるのですか。その辺、確認させてください。","respondent":"工藤指導課長","answer":"それぞれ退職や採用を繰り返しておりますので、令和３年度につきまして２７名いるです。職層につきましては、５級職の副校長、また、主幹教諭、主任教諭、教諭というふうに、各職層の中で、それぞれいるところです。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"副校長もいらっしゃるということですよね。今は校長が区独自の教育に関しても職務を行っていらっしゃるということで、義務教育学校でなくても一貫教育というのはあるわけだから、それぞれ都費の校長先生がそれを滞りなく、特に不都合もなく行っておられるということでよろしいのでしょうか。都費の校長だと、区独自の教育について何か不都合があるのかというところを確認させていただきたいと思います。","respondent":"工藤指導課長","answer":"そういった意味では、特に滞りがあるわけではありませんが、区の固有教員は、市民科の理解につきましては、異動等伴ってくる都費の方に比べますと理解が十分でありますし、また、推進役として担えるという部分では、私ども、特に市民科あるいは品川コミュニティ・スクール、あと。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。ただ、今の校長先生とか、今一緒に働いていらっしゃる都費の先生方とか、それからＰＴＡとか、そういう方たちとは意見交換とか、例えば今こういう制度を考えていますぐらいのご報告はあるのか、その辺についても教えてください。","respondent":"工藤指導課長","answer":"そういった意味では、ＰＴＡ等含めて、こういった制度設計を伴うところ、実際には今、議案として上げていく流れの中では、考えているという案内は、特に固有教員の先生方中心に私ども案内はしておりますが、特に広くこれを周知して。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"この手順でいくと、今回こういう形で、しかも条文としてこういう役割が増えますというようなことは明記されないで、給与の変更とか固有教員にこういう級ができるということになってしまうのかなと。その辺、そういう心配はされていないのか、ごめんなさい、お答えになりにくいかもしれないですけれども、もしお答えいただけることがあれば教えてください。","respondent":"工藤指導課長","answer":"条例としましては給与等の一部改正をする条例ですが、この条例で承認いただきましたら、教育委員会規則のほうで様々職務等を定める予定ですので、そのように進めるところです。","id":"exchange-011"},{"speaker":"つる委員","kind":"提案","question":"この間、議会からの様々な質問とか提案など含めて、資料にあるとおり、まさに区固有教員の方のキャリアプランの体系化とか人材育成の面というのは、いろいろな議員から指摘・提案があった中で、今回、やっとといいましょうか、校長という１つの目標といいましょうか、そうしたところの形がやっとできてきたのかなと、質疑を確認している中で思ったのですけれども、そういう意味では。","respondent":"工藤指導課長","answer":"体制面のところでは、現状、法令上は統括副校長となりますけれども、勤務の中では、仮になのですけれども校長と合わせて学園長という呼称を使うなどといったことを私ども検討しています。そういった意味では、児童・生徒から見て、校長先生が２人いると。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"現場のそういう管理職の立場の方が子どもたちと本当にしっかり接していただいているのだなというのを肌身で感じる中で、先ほど確認させていただいた児童・生徒との時間というのをどうつくっていけるのかなというのはやはり気になるところでありますので、そういったところも含めて、再度、今伺った大きく２点ですか、教えていただければと思います。","respondent":"工藤指導課長","answer":"そういった意味では、先ほどの指揮系統も含めながら、子どもと接する時間というところでは、それぞれ役割を分担するからこそ、児童・生徒とお話しする機会も設けられる、また、様々な行事についても、複数の学年に引率も含めながら関わることができると考えますので。","id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"教員の方たちには説明をされる、子どもたちには説明される、これは十分理解したのですけれども、これから連携という部分で大切な地域、町会長であるとか、そういった方への説明はやはりもっとしっかりしていかないと、学園長という新しい名前があったりというものも、学校以外、要は地域に混乱を招くのかなというのを危惧しているのですけれども、そういった観点において、周知の説明であったり。","respondent":"工藤指導課長","answer":"あくまでも選考を実施した上で任用が可能な場合に、早ければ令和４年４月１日からの任用になりますけれども、私ども、タイミングとしては、まずこの制度ができたというところでの周知を、様々、地域の方含めて、しっかり行いたいと思いますし、また。","id":"exchange-014"},{"speaker":"安藤委員","kind":"提案","question":"区独自の一貫教育というのは、質疑もさせていただきましたが、検証が必要で、進めるべきではないと思いますけれども、区固有教員というのは、一貫教育の推進と任務を担わせるのではなく、先ほど子どもたちと向き合う時間がという質疑もありましたが、子どもたちのきめ細やかな学びを保障するための少人数学級の前倒しとかさらなる推進のために活用すべきで、そうした提案も何度かさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"この件については大変悩みました。それで、これ、情報開示して、非開示だったので、争って２年かかってしまったのですけれども、最終的に開示していただいた議事録を見ると、皆さん、とても急ぐべきではないと。今回のことについても、この制度について決して悪いとは思わないのですけれども、議論の経過とかを伺うと、もう少しきちんと議論してからこれを実施されたらどうかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-03","title":"第３６号議案、令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第３６号議案、令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"食材を配る対象者は何世帯何人になり、１世帯につきどのような食材が何回届けられるのか、伺いたいと思います。","respondent":"伊東子育て応援課長","answer":"配布の時期としては、夏休み頃に需要があるかなというところで、そのときに合わせて配布しようと考えています。８世帯で１０万円ですので、夏休み頃にセットして１回配布ということを考えております。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問","question":"これは、しあわせ食卓事業とは別のプログラムと考えてよろしいでしょうか。これを基に制度をつくるとかいうことではなく、単発で行うということでしょうか。その２点、しあわせ食卓事業とは違うのか同じなのかということと、これ単発で終わりなのかということについて、これをきっかけに何かするとかそういうことではないのでしょうかということを伺いたいと思います。","respondent":"伊東子育て応援課長","answer":"こちらにつきましては、しあわせ食卓事業とは別のものと考えています。寄附者のご意向で、場所も指定されていたというところで、今回寄附をいただいて、その意向に沿って、単発で配布ということで考えてあります。","id":"exchange-018"}]},{"id":"topic-04","title":"令和３年陳情第３６号、区立子どもの森公園の工事に関する陳情","agenda":"令和３年陳情第３６号、区立子どもの森公園の工事に関する陳情","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"生活者ネットワークとしても同様に、やはり審査に当たって、陳情者の方の気持ちを理解する上でも、最初に意見陳述をぜひしていただきたい、その上で審議をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"松本委員","kind":"確認","question":"私としても、先ほど通例にという言葉がありましたけれども、申合せ確認事項に記載があるのは、審査上必要があると委員会決定した場合ということで、順番については特に記載がありませんで、特に今回の場合は、提出が６月１７日で、もう２週間たっていて、状況の変化もあり得ると思いますので、きちんとご意見を伺った上で、それを踏まえた上で審査が必要だと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"今、説明会５回ということでありましたけれども、工事着手までに行われたそれぞれ説明会の参加人数を教えていただきたいというのが１点です。それと、広報しながわには掲載していないということで陳情にもありますが、影響の大きさを考えるに、建設候補地案の段階で掲載して、広く意見を聞きながら建設を進めるべきではなかったかなと思うのですけれども、掲載しなかった理由を伺いたいと思います。","respondent":"加島児童相談所移管担当課長","answer":"１点目の説明会の参加人数についてお答えいたします。事業説明会の第１回、平成３１年１月に開催いたしましたものは、約５００世帯に周知いたしまして、いらっしゃったのが７名の方です。","id":"exchange-021"},{"speaker":"安藤委員","kind":"提案","question":"子どもの野球場もあるわけですし。ですから、広報しながわには、決まってから広報するというのでは、今の時代には全くそぐわないと思いますので、私は本当にこれは掲載していくべきだったなと、自戒も含めて、提案はしたのですけれども、もっと強くご提案すればよかったなと思います。聞いたとしたら、どのような意見が上がって、それは候補地選定にどのように反映したのかというのも伺いたいと思います。","respondent":"加島児童相談所移管担当課長","answer":"そこでいただいた主な意見ということですけれども、陳情の項目にもありますように、公園になぜ児童相談所をつくる必要があるのか、また、計画地内にある樹木についての扱いのこと、それから陳情関係者の方以外からも。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"この公園をどうするかということに関して、子どもたちの意見をぜひ聞いてほしいという声が保護者の方から出たと聞いたのですが、そこら辺の意見は何かなかったのかなということをお伺いしたいというのが１つ。","respondent":"高梨公園課長","answer":"今後の子供の森公園の再整備に係る子どもたちの意見収集についてなのですけれども、ほかの公園でも行っていますとおり、今回、下水道工事が終わった後の公園の再整備に当たりましては、子どもたちも含めた利用者からの意見収集、それと子どもたち以外にも。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは、２５日の個別説明で子どもたちの意見を聞いてほしいという意見が上がったのではないかと聞いているのですけれども、そこら辺、どんな意見が上がったのかというのを伺いましたので、お答えください。いろいろな公園のタイプを並べて、どれがいいですかと聞いたみたいですけれども、結果、冒険公園が過半数で、原始林公園が３割を占めて、現在の公園の原型が造られたと。","respondent":"加島児童相談所移管担当課長、高梨公園課長","answer":"あわせて、児童相談所で必要な子どもの権利と今まで遊んでいた子どもの権利は共存するのか、その議論はされたのかというところで、広報につきましては、冒頭説明で申し上げましたとおり、工事仮囲いに、横２メートル縦１.５メートルで。児童相談所の適地選定の際に、子供の森公園の経緯を踏まえたかどうかといった点についてお答えしますが、区内の公園に限らず、いろいろな公有地の取得の際には、様々な経緯があって。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"私もそういう意味ではまだまだ認識不足だったなという自戒を込めて質問しているのですけれども、そういった点で、区は今回反省すべき点がなかったのかなというのを伺いたい。今後の施策を進める上で活かすべき点をどのように考えているのかというのも併せて伺いたいと思います。","respondent":"加島児童相談所移管担当課長","answer":"区といたしましては、条例等の定めにのっとって、これからもしっかりと対応してまいりたいと考えているところです。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"やはり今後に関わってくるのです。私が伺ったのは、今回の件、今のご答弁ですと、法令にのっとって、条例にのっとってやってきて、何も問題はないと。これからも変わらず、もちろん子どもの声は聞きながらやっていくというふうにしか聞こえないのです。私が伺ったのは、今回の件で反省すべきところはなかったのかなというシンプルな質問なのです。しかし、区としてはないのか、伺いたいと思います。","respondent":"加島児童相談所移管担当課長","answer":"それ以前には任意の事業説明会を２回開催いたしまして、近隣の方にもこういった児童相談所設置の整備の計画について、また、必要性について、ご理解を求めてきたところです。区としては、今後も条例等に基づき、しっかりと対応してまいりたいと考えております。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"これは建築物を建てるわけですから、中高層建築物紛争予防調整条例にのっとってやるという答弁になるかもしれませんけれども、子どもが愛して使っている公園をどうするかということに関わる施策で、児童相談所はもちろん大切だと思います、思うのですけれども、そういう事例でもなお、中高層建築物紛争予防調整条例にのっとって問題ないという答弁は、子どもの所管としてどうなのかなというか。","respondent":"加島児童相談所移管担当課長","answer":"区として、今後、建築物の建設に当たりましては条例等の定めに従ってまいりますし、それ以外にも今回任意の事業説明会を開催してまいりましたので、区としては適切に対応してきたものと認識しております。","id":"exchange-027"},{"speaker":"松本委員","kind":"質問","question":"私も進めることはもちろん賛成しているので、それは進めていくという立場なのですが、やはり説明のところは今後も含めて考えていくべきかなと思っていまして、先ほど条例に基づく説明会と、あと任意の説明会というところがありましたけれども、その周知の対象ですね、ポスティング等の対象というのが、どういう根拠で、どの程度だったのかというところをもう１回ご説明いただければと思います。","respondent":"加島児童相談所移管担当課長","answer":"説明会の周知範囲の根拠についてお答えいたします。任意の事業説明会につきましては、こちらは特段条例ですとかの定めがございませんので、区といたしまして、計画地周辺、建設によって影響の大きい住民の方々、約５００世帯に周知をさせていただいたところです。","id":"exchange-028"},{"speaker":"松本委員","kind":"質問","question":"先ほど安藤委員も指摘されていたとおり、そこは本当にありがたいなと思うところなのですが、周知の範囲というのは、影響が大きいと思われるところということなのですが、影響が大きいと思われるというところをどういうふうに検討されたのか、伺います。","respondent":"加島児童相談所移管担当課長","answer":"平成３１年１月に開催いたしました説明会のときは、まだ基本設計の最中でしたので、建物の大きさ等が定まっていたわけではございません。ですので、現在計画地の周辺をご覧いただきますと、川ですとか都道というところで、住宅地と続き地でないところがあります。","id":"exchange-029"},{"speaker":"松本委員","kind":"質問・要望","question":"これは我々も当然反省なのですけれども、行政におかれましても、特に大きな公園ですから、利用者との関係で、今日は所管もいらっしゃっていただいていますので、周知の在り方については引き続き考えていただきたいなと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのときの要望で１つ確認したいのですけれども、ここは保育園の子たちも来ていると思います。今までのご答弁の中では保育園へこういう情報提供をしましたということはなかったのですけれども、その辺についてはどうだったのでしょうか。","respondent":"加島児童相談所移管担当課長","answer":"その際の先方のご反応ですけれども、ご理解をいただいたと区としては認識しております。","id":"exchange-031"},{"speaker":"吉田委員","kind":"確認","question":"任意の説明会を開かれたことについてはとても評価したいと思うのですけれども、それをさらに広げるというようなことはなかったのか、検討はされなかったのか、その辺についても確認したいと思います。私たちとしてはすごくしつこく説明会、広く説明してくださいねと。基本的に生活者ネットワークの意見というのは、いろいろな人たちの意見を聞きながら進めてほしいというところに終止していると思うのです。","respondent":"加島児童相談所移管担当課長、小林施設整備課長","answer":"その後、設計の煮詰まりとともに計画説明会の開催という運びとなりましたので、現在、任意の説明会につきましては２回というところになっております。工事を所管する部署からもご答弁申し上げます。今年の３月から工事に着手ですが、その１か月前、２月ですが、公園の中に大きな看板で工事着手に関するお知らせの掲示をしています。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"ありがとうございました。そういう意味でいえば、私たちももうちょっときちんと確認しながら、さらに意見を言っていくということが必要だったのだなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"松澤委員","kind":"質問","question":"説明会を５回開かれたというお話の中で、７名、２名、１３名、１５名と、私としてはだんだん増えているのかなと感じています。そういったことというのは、同じ広報をしている中で、住民の方がだんだん後半になってそうやって認識を持ったのか、周知にちょっと特徴があって人が増えたのか、そういったのはどうお考えですか。","respondent":"加島児童相談所移管担当課長","answer":"平成３１年１月に任意の事業説明会を開催させていただきました際には、ポスティングですとか町会回覧板というところをメインにやっていたのですけれども、令和元年８月以降の個別要望による任意の事業説明会においては、住宅内の共用部に掲示をさせていただいたり。","id":"exchange-034"},{"speaker":"松澤委員","kind":"意見","question":"子供の森公園、雑談ですけれども、私は北品川が実家なので、怪獣公園で遊んでいて、ティラノサウルスなんかも見にいって、なくなって、ちょっと寂しいなと思っていましたが、再整備という考えの中で、品川区は大井坂下公園であるとか、子どもたちの声を聞いて、インクルーシブ公園にするなど、住民だけでなく、子どもたちにもきちんと話を聞こうという姿勢の中で。","respondent":"高梨公園課長","answer":"子どもたち含め、近隣の方、子どもたち以外の利用者もいますので、しっかりとご意見を聞いて、また恐竜公園がいい、怪獣公園がいいというようなご意見が出されれば、しっかりとそのご意見を聞いて、新しい怪獣公園としてどのような公園がふさわしいのかといったところを検討し。","id":"exchange-035"},{"speaker":"松澤委員","kind":"質問・要望","question":"周知の課題というのは、いろいろなところで必ず起こるかなと思っています。皆さんからもお話があったように、我々議員というのは地域に根差したというのを目標としていますので、こういう話があったときに地盤の人に声をかけていくという、行政と一緒に周知していくのはやはり大切なのかなというのは本当に感じているところですので、引き続き徹底した周知に協力してやっていきたいと思っています。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"つる委員","kind":"質問・要望","question":"質疑も含めて、陳情書もよく拝見させていただいて、陳情者が指摘されている視点というのは、至極当然なご指摘かなと私は理解しているところです。１点、ここで聞きたいのですけれども、看板を設置していただいたのはどのくらいの期間、そこに……、施設整備課長か、設置していただいたのか、教えていただいていいですか。","respondent":"小林施設整備課長","answer":"これにつきましては、建物の規模、大きさ、それから建物がどのような用途なのかというのを掲示する看板ですが、それにつきましては、令和２年８月に掲示しております。それで申し上げますと、約１年弱ぐらいは掲示をしたと認識しております。","id":"exchange-037"},{"speaker":"つる委員","kind":"質問","question":"公園課長ではなく、施設整備課長のご答弁ですね。大変失礼しました。広報広聴課としての仕事なのかもしれない。さっき、条例の範囲の中で一生懸命やってきたと伺いましたけれども、教えてほしいのが、その条例に書かれていることで、できること、逆にやってはいけない、できない広報・周知の在り方、これは施設所管のほうですけれども、というのはあるのでしょうか。できない、やっていけないこと。","respondent":"小林施設整備課長","answer":"先ほどからお話のあります紛争予防条例の所管部署ではないのであれなのですけれども、広報してはいけないというような、駄目な規定というのは基本的にないと認識しております。","id":"exchange-038"},{"speaker":"つる委員","kind":"質問・要望","question":"それを行政だけに求めるというのはまたいかがなものかなというところは一方である中で、だけど、さっき、条例のことを伺って、いろいろ工夫はできるのだなと思ったのです。さらにみんなの声を聞いていこうという未来志向な形ではないですか。いろいろ申し上げてしまいましたけれども、広報広聴の所管ではないのでご答弁は結構ですので、ぜひ要望として参考にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"様々ご意見がありましたので、私からも１点だけ。そこから今度、区のホームページに行って検索をすると、私の確認する限りですと、子供の森公園、恐竜が写っていて、恐竜がいるよということをまだうたっている。近隣の人たちにも親しまれているところがあると思いますし、あとはやはり遠方から来る方もいらっしゃる。もう工事が始まっていて、恐竜が使用できない。これは要望として言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"安藤委員","kind":"意見","question":"やはり子育てされている当事者の方ですので、意見陳述をするというのはなかなか大変な苦労の中で、自分の意見をまとめたりとかということもしていますので、ぜひそういう区民の皆さんの、これに限らず、意見陳述したいという、議会に区民の声を述べたいという、そういう思いは極力尊重しなければいけない、そういう議会にならなければいけないと思っていますので、ぜひ意見陳述をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"吉田委員","kind":"質問・要望","question":"私も、原則的なところで、せっかく陳情を出されたその中で意見陳述したいというお申出があった場合には、議員として陳情の中身をより理解するためにも、意見陳述はぜひやっていただきたいと思います。ですので、今回も意見陳述を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"松本委員","kind":"質問","question":"そういう意味では、やはりきちんと意見を聞いた上で考えるべきと思いますし、何よりも委員会というのは、議会もですけれども、平日に行われる、その中で、仕事をされている方であれば仕事を休まれて、ご家庭がある方であればいろいろとやられていることがある中でいらっしゃって、しかも文案も用意されて、その結果、聞かないというのは、開かれた議会というところとは違うかなと考えていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"つる委員","kind":"意見","question":"陳情が先月１７日に受理されていて、先月２４日付でも補足資料ということで私も頂戴しております。本当に資料の中できちんと多様な意見を拝見させていただきましたので、この資料が非常にすばらしいと思いますので、私はこの資料で十分、今の質疑も含めて、いいかなというところで、あえて陳述をいただかなくとも、こちらの資料で非常に理解させていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"松澤委員","kind":"意見","question":"私も再資料、この資料のほかに新しくもらった資料熟読させていただきました。その思いの中で十分伝わったのではないかと、資料を読み込む中で私も十分理解できたと考えていますので、意見陳述はなしでいいと思います。","respondent":"あくつ委員長","answer":"令和３年陳情第３６号、区立子どもの森公園の工事に関する陳情についての意見陳述の申出を受けることについて、意見が分かれましたので、採決を行いたいと思います。意見陳述の申出を受けることに賛成の方は、挙手を願います。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"今の委員長の決定の理由、委員長がそういうふうに判断した理由を伺いたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"安藤委員","kind":"意見","question":"それは理由になっていないといいますか、今までの質疑を聞いて、どこをどう判断して、委員長としてあえて意見陳述をやりたいという方の意見陳述を聞かないという判断をしたのかというのを聞いています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"松澤委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いいたします。看板の設置、いろいろな周知・広報はしていると思います。ただ、やはりほかの委員からもありましたように、求められる周知・広報の在り方、文教の課ではないのかもしれないですけれども、これは課題として必ずいろいろなところから声が上がりますので、子どもたちの話を聞くということも含めて、広報の在り方という部分に対しては強く要望してまいりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"つる委員","kind":"質問・要望","question":"本日結論を出すで、態度は不採択でお願いします。広報とか周知とか、いろいろなものについては、先ほど質疑の中でお伝えをさせていただきました。ぜひ積極的な工夫を、いろいろできる範囲の中でやっていただきたいなというところ、これはあります。ただ、しっかりと説明については工夫と努力を惜しみなくやっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"本日結論を出すで、採択を主張したいと思います。対話は続けるべきだと思います。そういう意味でも採択すべきだと思います。工事は進んでいるのですけれども、発注者は区なのですから、きちんと子どもを含めた当事者と対話を続けて理解を得る努力をすべきだし、そのような中で必要があれば工事を止めることが必要なこともあるかもしれないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほど意見をいろいろ言いましたけれども、ほかの委員の方のご意見を聞いても、広報というのは、する側もそうだけれども、やはり受け止める側がどう受け止めるかということをもう少し工夫されるべきというのは、一致したご意見なのではないかなと思いました。ぜひそういうことも含めて、これについては採択で、きちんと説明を改めてしていただきたいと思います。そういう意味で、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"松本委員","kind":"質問","question":"行政に丸投げをしているのではなく、きちんと具体的にこういうのではどうですかというレベルまで本当は言わなければならないのに、それを広く広くと言って、では全区民ですかという話にもなり得るところで、一方的に広く周知をお願いしますというのはやや無責任と思いますし、この陳情との関係では、第４項、一旦停止ですが、この一旦停止というところは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/186280?Template=document&Id=5036#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":42095,"voices":154}},{"id":"r03-20210706-5","meetingId":"r03-cm07","date":"2021年7月6日","dateIso":"2021-07-06","committee":"総務委員会","time":"午前１０時００分～午前１１時３６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","topics":[{"id":"topic-01","title":"冒頭に申し上げたとおり、取り上げる順番を変更し、議案審査(3)から行います。 それでは、(3)第４５号議案 三ツ木保育園改築工事請負契約","agenda":"冒頭に申し上げたとおり、取り上げる順番を変更し、議案審査(3)から行います。 それでは、(3)第４５号議案 三ツ木保育園改築工事請負契約","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"これは園庭が狭くなるのですか。どのくらいからどのくらいの広さになるのか、狭い広いということを一つお聞きしたいのと、周辺への建築に関しての周知あるいは合意というところがどうなっているのかということ、その２点についてお伺いしたいと思います。","respondent":"小林（剛）施設整備課長","answer":"具体的には、公園敷地に対して、特に南側に対して防音壁が欲しいとか、あるいは各種のフェンスが欲しいとか、そういうところのご意見を頂きまして、それらの意見につきましては、設計をしていく中で対応したところです。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"園庭が半分になるということですけれども、その点について、ここの内部、利用者の方とか、それから保育士の方とかから何かご意見があったりはしたのでしょうか。","respondent":"初貝保育教育運営担当課長","answer":"園庭が狭くなってしまうというところに関しましては、代替の公園としまして、近くに西品川公園、品川中央公園、三ツ木公園等々がございまして、そちらを活用して、そこで外で遊んでいただくというような保育を工夫していくということで、ご理解を頂いているです。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問","question":"三ツ木保育園で聞きたいところが屋上緑化なのですけれども、この契約の相手方というのは、屋上緑化をこれまでもやられてきた契約相手なのかというところと、また、この屋上緑化の中に、やはり遊べるスペースというのを確保されているのか、安全性という部分でお知らせいただければと思うのですが、いかがでしょうか。","respondent":"小林（剛）施設整備課長","answer":"今回の契約先の業者ですが、建築工事の業者です。区内の建物を建設する上で、様々な建物に今まで携わってきたところです。その中には、今お話のありました屋上緑化の経験もあったかと思いますので、屋上緑化ができない業者ではないと認識しています。","id":"exchange-003"},{"speaker":"田中委員","kind":"確認","question":"遊ぶところがないということで、例えば何か畑みたいなものを作って食育につなげていくとか、そういったものが用意されているのかというところを確認したいです。やはり遊ぶスペースというのをできるだけ確保してほしいということを思っていて、そういった設計なのか、そういう契約なのかと思っていたので、ちょっと確認をしたかったです。","respondent":"初貝保育教育運営担当課長","answer":"今のご質問にありました食育のスペース等々ですが、園庭自体は１階のところにありますので、スペースは少し狭くなってしまいますけれども、そこを工夫して、保護者の皆様であったり、そういったお声を聞きながら。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"今のお話にもありましたとおり、やはり園庭が少し狭くなったというところもあると思いますので、今のこの感染症の関係もあって、遊ぶところで子どもたちが密にならないような工夫がとてもされているのです。ですので、何歳児が今日は園庭で遊べる、何歳児がどこどこで遊ぶといった分けられるような工夫という観点も、これから入れていただきたいということを要望したいのですが、いかがでしょうか。","respondent":"初貝保育教育運営担当課長","answer":"今ご指摘のございましたコロナ対策で集団にならないようにということですけれども、今現在も保育の中で、なるべく集団が大きくならないような形で工夫をしております。今後もコロナ対策で、なるべく小集団になるような形で、保育のほうで工夫をしてまいりたいと考えています。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"ただ、小さいお子さんにとっては、何か事故があったときですけれども、スロープ状の滑り台みたいな簡易に素早く避難できるような工夫も、この中にはされているのでしょうか。それとも、あくまで３歳児だろうが４歳児だろうが、もう階段を利用して、園児を誘導するのも保育士だと思うのですが、その方に委ねるということなのでしょうか、お聞かせください。","respondent":"初貝保育教育運営担当課長","answer":"今ご指摘がありました避難路ですけれども、２方向避難は一応確保しています。今想定しておりますのは、２階が３、４、５歳の園児になりますので、基本的には階段を使いまして、保育士がきちんと安全に避難できるように付き添って避難するということを想定しております。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"ただ、素早く簡易に誘導するには、そういうスロープ状のものも保育園によっては設置されているとお聞きしていますが、ここにはないということですか。あくまで手で何人かを連れて下に下りて、また上に上がってきて下りてやるというような状況なのでしょうか。これは意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"おくの委員","kind":"意見","question":"民営化自体は元に戻すべきですけれども、老朽化しているのは改修すべきということで、賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどの屋上の利用だったり、食育とか遊ぶ場所の確保とかも十分に検討していただいて、なるべくそういう場所を確保していただきたいという要望も併せての賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"おくの委員","kind":"質問","question":"工事中、あるいは工事後のかむろ坂側の道路への影響、道路が広くなったり狭くなったりというような影響があるのか。それから、桜並木で有名な道路ですけれども、その桜並木などの景観も含めて影響があるのかということが第１点、お伺いしたいと思います。それと関連しますけれども、先ほどの三ツ木保育園と同様、周辺への周知、合意の点で問題はないのかということもお伺いしたいと思います。２点です。","respondent":"小林（道）学校施設担当課長","answer":"かむろ坂および桜並木につきましては影響がないものと、まず手を付けるということは今考えておりません。周知につきましても、計画説明会を去年やりまして、参加者が２８名、そして資料のみ持って帰った方が１名というところで、計画説明会をやって周知をしたところです。","id":"exchange-010"},{"speaker":"おくの委員","kind":"質問","question":"この学校が完成した暁には、この学校の設備でかむろ坂ホールというものができると伺ったのですけれども、ここの多目的室というところがそれを兼ねるのでしょうか。これは一体どのようなものなのか、それからどのような運営や利用形態を考えられているのか、もしできるのならそういうこともお伺いしたいと思います。","respondent":"小林（道）学校施設担当課長","answer":"１階にかむろ坂ホールというものがあるのですが、これはいわゆる多目的ホールで、地域に開放することを考えております。詳細はこれから検討に入るです。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどの質疑の中で気になった点をまずお伺いしたいのですけれども、かむろ坂等への影響はないということですけれども、通学路の影響というか、通学時は大丈夫なのかというところを確認させていただきたいのと、あと、契約の中で人工芝があるのですけれども、その人工芝がどのような人工芝なのかということ。","respondent":"小林（道）学校施設担当課長","answer":"それと、最後に雨水利用のご質問ですが、雨水利用は今回も約３４ｔのピット、水槽を造って、それを緑化の水まきに使用するとか、トイレの排水に利用するとか、そういうことで考えております。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"雨水利用のことも考えられての改築ということで安心しました。動線を確保ということだったのですけれども、安全性が担保されるような確保になるとは思うのですけれども、一応そこを確認させてください。その際にとてもうるさくて本当に困るということなので、そういう防音対策ということがされているのか、そういう契約になっているのかというところも伺いたいのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"１５ページの平面図を見ますと、校庭の面積が以前と比べるとかなり狭くなっているように感じるのですが、以前の面積と比較してどのぐらいの広さになっているのか、割合として教えてください。そしてコストですが、総額数十億円かかる。小・中一貫校ができたときに、総額で７０億円、８０億円ぐらいだったと思うのですが、やはり今これほどコスト的に上がっているのですか。","respondent":"小林（道）学校施設担当課長、東野経理課長","answer":"私のほうから、質問の３点のうちのまず２点をお答えします。校庭につきましては、既存が１,７４０m2、これに対しまして、今度の改築後については２,１３０m2ということで、若干大きくなっています。今回の第四日野小学校も１０億円を超えるものですとか、それから電気のほうですと７億円を超えるようなものという形になりますので、十分にＪＶ工事として取り扱うべきものとして考えております。その形で発注をしているものです。","id":"exchange-014"},{"speaker":"田中委員","kind":"質問・要望","question":"ほかの学校では、今まで花火をやっていたものがやはり人工芝によってできなくなったりとか、大きな車が入れなくなった等々あるので、そういったことはどのように検討されたのか確認したいのと、あと、今校庭が広くなった分、縦に大きくなったという話もあったので、やはりそうなるとさらに騒音への影響が大きくなってくるので、防音対策というのをしっかりとやっていただきたいと思うのですが。","respondent":"小林（道）学校施設担当課長","answer":"校庭は今現在人工芝等と考えておりますので、これについては火には不向きというか利用はできません。火を利用するものについては、土ではございませんので利用ができないと。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問・要望","question":"そこは所管がずれるのかもしれないですが、要望として。騒音の影響の部分は、電車の音を重視したと先ほどお話がありましたが、電車の音とともに、その羽田新ルートでの騒音、不動前駅周辺は思いのほか騒音の影響が大きかったので、そういうところをちょっと考えていただきたいと思うのですが、一言頂けたら。","respondent":"小林（道）学校施設担当課長","answer":"今言った騒音対策につきましては、先ほども少しお話ししましたけれども、鉄道の騒音を重視したのですけれども、当然防音対策の一つとしては、防音サッシ並びに吸音とかいろいろあるのですけれども、授業に影響するような計画というのはやはり避けなくてはいけないので。","id":"exchange-016"}]},{"id":"topic-02","title":"第４６号議案 大井坂下公園改修工事請負契約","agenda":"第４６号議案 大井坂下公園改修工事請負契約","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"そうすると、ユニバーサルデザインということですけれども、障害のあるお子さんとは無関係に、普通の小学校から集まってもらったというようなことなのでしょうか。そこら辺、障害のあるお子さんを特に集めたとか、そういうところはどうなのでしょうか。","respondent":"高梨公園課長","answer":"ただ、今回はユニバーサルデザインに配慮した公園づくりのアイデアといったところで、ワークショップの途中で品川特別支援学校の中学部の生徒さんに先生を含めて参加していただきまして、そちらのほうからもご意見を頂きながら。","id":"exchange-017"},{"speaker":"おくの委員","kind":"質問","question":"特別支援学校から中学部の方ということですけれども、もう少し詳しくどのくらい集まってどのような意見が出たか。そのワークショップは３・４年生の方が集まって、特別支援学校からは中学部の方が集まって、それぞれどのような意見が出たか、ざっとでいいですから教えていただければと思います。","respondent":"高梨公園課長","answer":"ワークショップの進め方ですけれども、まず子どもたちを幾つかのグループに分けて議論をしていただきました。今回特別支援学校の生徒さん２名に参加していただいて、それぞれからというよりは、そのグループごとにアイデアを頂いたといった形で出していただいております。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"今後は、ぜひそういったワークショップにしていただきたいということを、先に要望したいと思います。まだ直せる段階で当事者の方が参加して、この座り心地だったりとかを確認できるのか、そういうことも契約の中に含まれているのかということと、バリアフリートイレについては、ユニバーサルベッドはきちんとされているのかということを確認させてください。","respondent":"高梨公園課長","answer":"今まで公園の中には、ベッドを設置するとどうしてもそこにいついてしまうところから、設置を見送ってきたところではありますが、今回は、障害のあるお子さんにも使っていただきたいといったような思いから、まずは設置をしてみて、その後利用の状況等をしっかり見て。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"契約の相手方の方たちは、これまで区内公園のメンテナス等々をやってきたということですけれども、ユニバーサルデザインの公園をこれまで造ってきたかどうかについてはちょっと分からないということで、もう契約されているのかこれからするのか、やはり当事者の方たちのチェックというのは絶対必要だと思うので、ぜひ完成をする前に、それぞれの障害のある方たちが本当に大事なのはトイレですけれども。","respondent":"高梨公園課長","answer":"特別支援学校から参加していただいた方の意見聴取等についても、学校の先生との話し合いの中で今後検討してまいりたいと考えております。","id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"これは最初に言った要望と重なりますけれども、やはりほかの公園とかの今後の改修のときには、前もってその当事者の参加、その子どもたち、そして障害児たちの参加というのをぜひしていただきたいということを強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"最近防犯カメラももちろんつけて安全面もあるのですが、今後も遊具を含めて、安全で、そして子どもが集まりやすい公園環境などを含めて、そういうものをやはり工夫しながら、改善しながら、よりいいものを目指して進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"当事者の参加というのを強く求めて、賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-03","title":"第５０号議案、防災ラジオ他の買入れ","agenda":"第５０号議案、防災ラジオ他の買入れ","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"要するに、私としてはできるだけ買いやすい値段を設定してあっ旋販売をしていただきたいということを申し上げたいのですけれども、その辺はどのようにお考えになっているのかということをお伺いしたいです。住民税非課税世帯、それから生活保護受給世帯には無償でお渡しいたしますとなっていました。もう一つ、平成２４年度にやられているときは、そこら辺をどのようになさったのかもお伺いしたいと思います。","respondent":"平原防災体制整備担当課長","answer":"１点目、今回新たに導入いたします防災ラジオの価格の問題ですけれども、こちらにつきましては、販売そのものを令和４年度に行うということもありますので、今後の予算編成過程におきまして、具体的な金額を検討していくこととなりますけれども。","id":"exchange-024"},{"speaker":"おくの委員","kind":"質問・要望","question":"いろいろ研究しながら、なるべく買いやすい形でと答弁をいただきました。そのようにしていただきたいと思います。そのように要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"私も今の販売対象者のところが気になっていて、価格は今後の検討ということですけれども、販売対象者の2)高齢者・障害者等々については、やはり買いやすいというか、金額の差がつくだろうとは思うのですけれども、そこのところを確認させていただきたいのと、どういった契約の条件を出していたのかというところを確認したいのですけれども、そこの部分についてお知らせください。","respondent":"平原防災体制整備担当課長、東野経理課長","answer":"その関係もありまして、高齢者・障害者、あるいはスマートフォン普及率のやはり低い住民税非課税世帯といったところに普及できるよう、そういった価格の設定を今後考えてまいりたいと思ってあります。契約条件ですが、こちらの概要書に書いてあるものを仕様書に充てておりまして、１台幾らですというようなもの、それから起動装置につきましても１台幾らでというようなものを合計したもので入札いただいたという形です。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"この防災ラジオにどういった機能を求めたとか、そういうものは条件の中になかったのでしょうか。そういう細かな部分を知りたかったのですけれども、ご説明いただけたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区では様々場所を変えたり、いろいろ工夫をされていますが、これはもうどんどん聞こえなくなるというのが事実なので、そういう情報弱者に対する対策としては、やはりこういうものを何らかの形で普及させて、私はやっていただきたいと思います。防災課から購入したと思うのですが、そうするとそれはもう全く使わなくなる、使えなくなる方向で品川区は動くということでよろしいのでしょうか。","respondent":"平原防災体制整備担当課長","answer":"続きまして、現行の防災ラジオについてですけれども、こちらにつきましては、現在の防災行政無線はアナログ波で発信していますが、そちらの電波が令和４年１２月から、国の省令改正に基づきましてデジタル波に変更されるのですけれども。","id":"exchange-028"}]},{"id":"topic-04","title":"第３７号議案、一般職の任期付職員の採用に関する条例の一部を改正する条例","agenda":"第３７号議案、一般職の任期付職員の採用に関する条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"確認","question":"人事に関することですから、ちょっと確認をさせてください。当然労使の合意は得られているのかということです。それから、昇給ということがもちろんメインですけれども、少しご説明にも出ていましたが、降給、給料が下がる場合も含まれているということですけれども、例えばどういうことなのでしょうか。その点も少しご説明いただければと思います。","respondent":"崎村人事課長","answer":"任期の定めのない職員を含めましても、近年この降給の分限処分を行った実績はございませんので、今回の制度変更については、降給をすることを前提としたものではないということだけご理解を頂ければと思います。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問","question":"総務省のほうでそのように通達をしているのか、法令で決まったのならいいのですけれども、公務員の任期付職員の方はこのように昇給もしますよ、ボーナスも出ますよ、様々な待遇がよくなるのですけれども、ほとんど国民の多くの方が対象にならないということなのですか。それとも総務省のほうで、そういう事業所に対してもこういう通達が行っているのですか。その辺をお聞かせください。","respondent":"崎村人事課長","answer":"ですので、今回そういった常勤職員が行う業務を担っている職員ということも鑑みまして、昇給を実施すべきということで、条例を改正するといったものです。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問・要望","question":"ならば、もう一般の非正規雇用の人も、正規雇用で働いている職員と同じような仕事をされている方が本当に大多数だと思うので、そういう方たちもやはり上げてもらうように、私は区から総務省のほうにやはり進言していただきたいと思います。今回の件は、これはこれで働く任期付職員の方の処遇を改善するということはいいことだと思いますが、その辺、意見として、要望として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"たけうち副委員長","kind":"質問","question":"今実際にこの例に当てはまる方がいるとしたら、どのような方なのか。それから、もしくは今はいないけれども、今までこういう方がいたとか、何か具体的にこういう仕事の方というのを教えてください。","respondent":"崎村人事課長","answer":"現在の特別区の状況では、オリンピック・パラリンピック関係の業務のほかに、例えば新型コロナウイルス関係業務ということも今回追加をされたところですので、こういったところで今後、先ほど言いましたように一定の期間内で業務を終了することが見込まれるものですとか。","id":"exchange-032"}]},{"id":"topic-05","title":"第３８号議案、品川区特別区税条例の一部を改正する条例","agenda":"第３８号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"この一番上のほうで、個人住民税非課税限度額等の算定に係る扶養親族の範囲の見直しというところがありますが、海外にいらっしゃる親族の方、その方の例えば所得とか、それから実際どういう生活をしているかとか、そういうことは把握できるのですか。大体この程度ぐらいしかできないのだけれどもということなのですか。その点について教えてください。","respondent":"提坂税務課長","answer":"正直申しまして、なかなか詳細に把握するのは難しいところですけれども、年齢が３０歳以上７０歳未満ということでございまして、海外で一定水準以上の収入を得る能力があるだろうということと、あと、所得要件の判定というのは。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"感想なのですけれども、今、２９歳以下でも、ＩＴとか様々いろいろなことをやったり、いろいろなベンチャーをやったりして、逆にすごく収入が多いという方もたくさんいらっしゃるという話も我々はよく聞くので、やはりこれだけではまだまだ足りないのだろうなということで、あくまで不公平感の解消にできるだけ努めるという考え方でいればいいのでしょうか。それだけ教えてください。","respondent":"提坂税務課長","answer":"年齢要件とか、国外居住の親族の数とか、内容も随時見直しとかその辺を行いまして、この辺の制度も改正していくとかそういう可能性はありますので、その辺の国の動向を注視してまいりたいと考えています。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"区民税の非課税の範囲のところ、新旧対照表のところで、１６歳未満の部分のご説明がありました。説明によってすごく分かりやすかったということを感じました。ですので、資料の作り方としてもう少し丁寧に、今のご説明はすごく分かりやすかったので、分かりやすい資料を頂けたらということを要望したいと。もし一言ありましたらお願いします。","respondent":"提坂税務課長","answer":"それで、字のポイントとかその辺も踏まえまして、どうしてもここに記載できる内容というのは限定されるので、その辺は口頭で捕捉するしかないのかなと思いますけれども、今頂いたご意見を承りまして、またよりよい資料を作るよう努めてまいります。","id":"exchange-035"}]},{"id":"topic-06","title":"令和２年度品川区一般会計予算繰越明許費繰越計算書","agenda":"令和２年度品川区一般会計予算繰越明許費繰越計算書","exchanges":[{"speaker":"小芝委員","kind":"意見","question":"ここ最近、品川区の公式ＬＩＮＥのほうで少し内容に不備があって、その訂正が連発している事例がございまして、まず７月４日の都議会議員選挙の投票日にＬＩＮＥで投稿された内容の中で、投票日に期日前投票の案内が出ていたことと、あともう一点が、新型コロナウイルスのワクチン接種会場のこみゅにてぃぷらざ八潮の予約枠の日が違っていたということで、それが全く内容が違っていたということで。","respondent":"堀越企画部長","answer":"所管の職員、それから広報担当の職員とで複数のチェック・確認をするとともに、こういった間違いの事例を共有して、二度とこのようなことがないようにしっかりと、かつ迅速に区民の皆様に情報をお伝えするという形で、そのような姿勢で進めてまいりたいと思っているところです。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/307500?Template=document&Id=2202#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":30139,"voices":177}},{"id":"r03-20210707-6","meetingId":"r03-cm07","date":"2021年7月7日","dateIso":"2021-07-07","committee":"区民委員会","time":"午前１０時００分～午後 ０時０３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","topics":[{"id":"topic-01","title":"荏原第一地域センターの移転","agenda":"荏原第一地域センターの移転","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"１点だけ、旧荏原第一地域センターと、移転した新しい新荏原第一地域センターですけれども、ランニングコストというのか、維持管理費というのか、比較した場合どういう違いがあるのか、この点だけご説明いただけますか。","respondent":"川島地域活動課長","answer":"令和４年度以降も大体年間２,０００万円ほどの維持管理費、管理費ですとか修繕積立金ですとか、そのような費用も新たに生じるということで、その辺のところについては、区の支出も多くなっているところです。","id":"exchange-001"}]},{"id":"topic-02","title":"東京２０２０大会期間中の事業（予定）","agenda":"東京２０２０大会期間中の事業（予定）","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"近隣住民への周知や説明、どういう対策を行っているのかの説明などはどのように行っているのか、お伺いしたいと思います。あわせて伺いますけれども、ホスピタリティハウス「しながわハウス」ということで、現地は見合わせるという説明がありましたけれども、つまりは一般の方の入場はできないということでよいのか、確認をさせてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"２点目の事前キャンプですが、なかなか日程等が決まったのがつい最近ということもございまして、地元説明ということでは、これから入るという形になるのかなと思います。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"先日の本会議で濱野区長は、「東京２０２０大会を成功させることが区の役割と認識」という答弁がありました。私はとんでもないと思います。コロナから住民の命を守ることが区の役割だと、私は思います。そこでお伺いしたいのですけれども、なぜコロナの感染が広がり命のリスクを伴う中、東京オリンピックの開催が区の役割だと思うのか、伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それに関しましては、品川区内は走らないのですが、品川区の火ということで、火を採る採火式というのは行う予定になっておりまして、それもオンライン等で配信をして、みんなで一つになるというような形で進めていきたいと考えています。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、命のリスクを伴うオリンピックの成功が、なぜ区の役割だと思うのかと伺いました。こうしたコロナ感染を高めてまで、命の危険を冒してまで、東京２０２０大会の成功が区の役割だとなぜ考えられるのか。最後に改めて伺いたいと思います。そして、国や東京都や関係者に、品川区としてオリンピックの開催の中止を申し出るべきだと思いますが、それぞれいかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"人の命が大事なことはもう当然なことでして、きちんとそこを担保した上でオリンピックを成功させる、それが私たちの仕事ですので、中止を訴えるような考えは特にございません。","id":"exchange-004"},{"speaker":"中塚委員","kind":"意見","question":"命は大事だとおっしゃっていただきましたが、私も命ほど貴いものはないと考えています。しかし、オリンピックの開催は、たとえ無観客であっても、世界中から関係者が数万人東京に集まるわけで、各種事業も、規模は縮小したとはいえ、人の流れが生まれていく。リスクを伴うオリンピックの開催は中止すべきだと述べて、終わりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"くにば委員","kind":"確認","question":"１点だけ確認させてください。例えば私は、この２番目のパラ・パワーリフティング、こみゅにてぃぷらざ八潮の道を挟んだ向かいの棟に住んでいるのですけれども、それは周辺住民に含まれるのかどうか、団地なのでかなり周りに棟があるのですが、どこまでの範囲を周辺と考えているのか、その説明の方法であるとか周知、時期をどのように考えているのか、お教えください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"周辺の定義ですが、練習場所所在地の地域センターの管轄になろうかと思います。周知の仕方ですが、通常は何かそこに関わることがあるときには、町会長会議、または自治会長会議等でご連絡するというのが大体の流れですので、そういった形になろうかと思います。","id":"exchange-006"},{"speaker":"くにば委員","kind":"質問","question":"自治会長会議、町会長会議で報告する。それは、周辺住民ではなく、周辺住民のある意味、長というか、集団の中のトップの人に説明する。それは、周辺住民に直接説明が行き届かないということでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"自治会長、町会長から周辺の住民にまたお知らせいただくということで、そのようなルートを使って、区の事業やご連絡というのは通常差し上げてありますので、同じようにさせていただきたいと思っています。","id":"exchange-007"},{"speaker":"くにば委員","kind":"質問","question":"その町会長、自治会長が、そこの中の人たちに周知をするというのは、きちんと区のほうからその周知をしなさいという命令で周知をするのでしょうか。例えば私は地元の自治会には加入していないのですけれども、加入していない周辺住民の方にも連絡は来るのでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらの案件としましては、町会長、自治会長にご連絡を申し上げて、そこから周知していただくという方法を取りたいと考えていますので、自治会長や町会長に命令をするというものではなく、こちらとしては周知のお願いをするというような位置づけになろうかと思います。","id":"exchange-008"},{"speaker":"くにば委員","kind":"質問","question":"すみません、少しご答弁が、私が質問したことにいまいち足りていないと思うのですけれども、要するに、端的に、自治会に加入していない方のところに連絡は行くのでしょうか。私も利用していますし、そういった方たちも感染リスクは当然あると思うのです。なので、周知すると思うのですけれども、周知が徹底されるのは、区の責任で周知を徹底するべきだと思うのですけれども、その２点についてお伺いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"八潮に住んでいる方全員にお知らせするというのは、なかなか難しいこともあるのかもしれないですけれども、私どもは、そこはきちんと皆さんに安心して生活をしていただけるような形を取りながら、周知はしていきたいと考えています。","id":"exchange-009"},{"speaker":"くにば委員","kind":"質問","question":"何度も申し上げているとおり、そこに一任をしてしまうと、例えば八潮全体の方に周知をすることはなかなか難しいというお話がありましたけれども、そこに関してはその他様々、例えば、それでしたらポスティング、区のほうで責任を持って周辺住民の方に、例えば工事とかがあるときは、普通に周辺住民の方たちにポスティングでお知らせが入るではないですか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"現在のところ、ポスティングまでは検討しておりません。ただ、住民の方で知らなかったとかいうことがないような形で、今、委員もおっしゃられたようなＳＮＳですとか、そういったものも使いながら、周知はしていきたいと思います。","id":"exchange-010"},{"speaker":"くにば委員","kind":"質問","question":"すみません、何度もやり取りして申し訳ありません。要するに、きちんと行き届いてほしいのです。それで周知をしても、八潮に住んでいる高齢の方々には恐らく行き届かないです。本当にそれは、先ほど、動線を分けるから直接接触はしないとおっしゃいましたけれども、直接の接触だけではないではないですか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それと、バブル方式の話ですが、委員がおっしゃいますとおり、都内のホテルからシャトルバスというか、貸切りバスで中に入って、そこから帰るという形で、動線も分けていますし、区民とは全く接しないような方法で。","id":"exchange-011"},{"speaker":"くにば委員","kind":"質問・要望","question":"例えばこみゅにてぃぷらざ八潮の中の施設の係員の方とも、一切接触をしない。なのであれば、そういった形で、感染リスクをもっと深く丁寧に、慎重に考えてすべきだと思っているのですけれども、では、その広報についてはしっかりとしていただけるというご答弁で、それはお願いしますという要望にしておきます。というふうな形で、区民の方が一切触れないように、完全に施設の利用も分けていただきたい。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そこに関しても、今時点でももう、例えばこみゅにてぃぷらざ八潮でしたら、外に机を置いておいて、そこに置いて、それで利用する方が取りに来るという形を取っていると認識しておりますので、同じようにさせていただこうかなと思います。","id":"exchange-012"},{"speaker":"くにば委員","kind":"質問","question":"もろもろご答弁ありがとうあります。すぐ向かいに住んでいる僕にも、必ず周知が届いてしかるべきであろうと思うので、周知徹底のほうは必ずお願いします。でも、本当に命に関わっているから、どこまでの範囲できちんとやっていただけるのかというのを、ざっくり徹底してやりますという、その徹底してやりますというのが、本当に徹底してできているかというと、実際にざるの部分があったりするので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"横山委員","kind":"確認","question":"幾つか確認させてください。そして、あと２点目ですけれども、キャナルアートモーメント品川２０２１です。こちらは、今、まだ検討中ということですが、観覧客の方の受入れがもしあるとすれば、予約制で限られた人数でということだったのですが、対象者については、こちらは区民限定など、現時点で、調整中ということですけれども、何か対象者に関しての情報で分かる部分がありましたら、教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"事前キャンプの件です。実は２年前にも１回行いまして、そのとき、区民の方ですとか小学生とも交流をしまして、非常にいい交流ができたと考えています。地球の裏側の国の方と心が通じ合うというのは、本当にいい経験だったかなと思いました。","id":"exchange-014"},{"speaker":"横山委員","kind":"意見","question":"本当に難しい中で、様々検討・調整していただいているということが分かりました。そうしたところも何とか頑張って、選手を応援する気持ちというのが私たちにあるのだということも、何とかうまく伝えられたらいいなと思いますので、ぜひ引き続き、できる範囲で、無理のない形で、感染症対策に気をつけながら進めていっていたければと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり、区民委員会ではなくなってしまうけれども、公園を造るときでも近隣の方に影響を及ぼす際には、ポスティングもするし説明会もやるし、理解を得ながら進めていくというのが、これまで品川区もやっているところもあるわけですから、今回もポスティングや説明会はぜひ検討していただきたいと思いますけれども、その点だけいかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そういった中では、公園を造るときのような住民説明会だとか、そういったことは今のところは考えてはいません。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"ポスティングは何で検討できないのですか。住民説明会がなぜ検討できないのか。理由を説明いただきたいと思います。改めて実施していただきたいと思いますが、いかがでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"住民周知の方法については、事案に応じて様々な形があると考えています。今回の事前キャンプに関しましては、私どもとしては、自治会長や町会長に説明ということで、今のところ考えております。","id":"exchange-017"},{"speaker":"新妻副委員長","kind":"確認","question":"事前キャンプの件ですが、総合体育館、こみゅにてぃぷらざ八潮、これまでもサークル、団体で使っている方が多くいらっしゃると思うのですが、これらの方々への周知というのはどういうふうになっているのかというところを、１点確認させてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"どちらの施設も住民の方が、団体で定期的に使っているような方もいらっしゃると思います。そちらに関しましては、施設のほうで、もう既に貼り紙をしてありますとか、そういった形で周知はしています。","id":"exchange-018"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ただ、八潮において言えば、私も一八潮の住民としては、やはりほかの地域と比べては自治会への加入率も高いところであって、これまでも周知徹底というのが、自治会を通じて様々地域センターから発信をされていることにおいては、周知率は高いのかなというふうに、それは私が感じるところではありますが、いま一度、そのお声もまた地域センターともご相談をしていただきながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/943539?Template=document&Id=2904#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":16745,"voices":58}},{"id":"r03-20210707-7","meetingId":"r03-cm07","date":"2021年7月7日","dateIso":"2021-07-07","committee":"厚生委員会","time":"午前１０時００分～午後 ２時０１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","topics":[{"id":"topic-01","title":"会議の運営上、予定表の順序を変更しまして、初めに、(3)新型コロナウイルス感染症の影響により収入が減少したこと等による第一号被保険者の介護保険料の減免","agenda":"会議の運営上、予定表の順序を変更しまして、初めに、(3)新型コロナウイルス感染症の影響により収入が減少したこと等による第一号被保険者の介護保険料の減免","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１つは介護保険料なのですけれども、国民健康保険料等のほうは実績が書かれているのですけれども、介護保険料のほうの実績について教えていただきたいと思います。","respondent":"宮尾高齢者福祉課長、池田国保医療年金課長","answer":"以上が令和２年度の減免実績です。それから、対象の額の考え方ですが、今回は、令和２年度の収入と令和３年度の収入を比較して、資料に記載のあるように、例えば、アの場合ですと１０分の３以上減額が見込まれる場合に対象となるです。あくまでも、コロナによって今年減少が見込まれるということで、対象となってまいります。","id":"exchange-001"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"ということは、コロナで令和２年度が本当にかなり減収になってしまって、３割以上減収になってしまって、国民健康保険料が減免されたという方でも、同じ減少が続いているという状況でも対象にならないということになるのでしょうか。そういう状況、そういう制度というのは、ちょっと問題なのではないかと思うのです。そこのところの確認をさせていただけますでしょうか。","respondent":"池田国保医療年金課長","answer":"あくまでも令和２年度は令和２年度の収入ということで、減免の申請ということになります。令和３年度、今年の分のコロナ減免につきましては、今年の収入が、コロナの影響により、今現在、これから先、減った場合ということで該当になるです。","id":"exchange-002"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"こういう方でも、令和２年度で免除されたという収入がそのまま続くという方でも、減免の対象にはならないということなのでしょうか。それで、この方には、国民健康保険料として１５万円の請求が来たということなのですけれども、同じように３割以上の減収がずっと続いているにもかかわらず、令和２年よりもさらに３割減収にならないと減免の対象にならないということなのでしょうか。","respondent":"池田国保医療年金課長","answer":"今お話があったように、昨年の収入から減少していない限りは対象にはならないです。","id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"去年はコロナの影響でということで免除されたにもかかわらず、同じ収入が続くにもかかわらず減免の対象にならないというのは、制度として問題なのではないかと思うのですけれども、その点はいかがでしょうか。","respondent":"池田国保医療年金課長","answer":"昨年、減額・免除になった方というのは、昨年の収入が減る見込みということで申請されている方でございまして、令和３年度の保険料については、もしそのとおりであれば、その少ない収入に対しての保険料が賦課されている状態です。","id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"私はそれは制度の矛盾だと思うのです。この方は年収が１０９万円だというのです。それなのに１５万円の国民健康保険料なのです。やはりコロナの前から３割減ったという状況がずっと続けば減免されるという制度であるべきなのではないかと思うのですけれども、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"この減額の制度につきましては、例えば政策減額等で既に減額されている世帯については対象にならないということで、低所得者の方に対しては、きちんとした減額について、これ以前からやっておりますので、令和３年度、引き続きやることに対して。","id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"本当にこれは国の制度ですから、課長が変えるということはできないことは分かりますけれど、だけれども、コロナの前から３割減ったというのがずっと続いていて、それの影響で令和２年度は免除になったものが、そのまま続いているにもかかわらず、今年度は１５万円もの国民健康保険料がかかってくるというのは、そして３割減少という収入の減少がずっと続いているにもかかわらず。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"品川区成年後見制度利用促進基本計画のパブリックコメント実施結果","agenda":"品川区成年後見制度利用促進基本計画のパブリックコメント実施結果","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それとも、後見人がついたときに、何か問題が生じたときにチームとして集まって検討するみたいな形になるのか。チームのイメージをもう一度教えていただきたいと思います。それで、成年後見制度が計画に対してどこまで到達していて課題が何かとか、その後どうしていくかなどというのが、１年ごとに出されていくということになっていくのかという、その辺のことを教えていただけたらと思います。","respondent":"寺嶋福祉計画課長","answer":"したがいまして、今後の開催につきましても、しっかりその中で検討していって、年に１回は少なくもあるとは思うのですけれども、必要に応じて開催できるような形で取り組んでいければと、今の段階では考えておりまして、策定委員会でもそのような意見が出ていたところです。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"平成１４年にできて、それからずっと全部の、累計の人数だと思うのですけれども、今、令和２年度の段階でどれぐらいの方が使われているのかという数字を教えていただけたらと思います。この報酬の負担が重い方への支援というのは、国でも検討されているとか、区でも検討されているということがあるのか、この点についても伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"もちろんまだ依頼もしていませんし、お答えも頂いていない、そもそも決定はしていないのですけれども、見込みとしてこちらの方に、立ち上げ期はやっていただきたいと考えているところです。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問","question":"品川区の成年後見の仕組みは先進的な取組をされているということで、品川モデルというようなことで、非常にすばらしい取組だと思います。ただ、区民の方々への周知などというところがなかなかだと思うのですが、パブリックコメントの３２件という意見の数がどうかということ。皆さん、どういうご意見というのは中を見たら分かるのですけれども、３２件という数字について、どういうふうにお考えでしょうか。","respondent":"寺嶋福祉計画課長","answer":"そこも含めまして、今回、計画とは別に、いわゆる誰でも分かるようなパンフレット、リーフレットになるかもしれないですけれども、それを作成して、かなりの部数を作って普及啓発に努めようということも考えておりますので、今のご指摘も踏まえて、さらに普及啓発。","id":"exchange-009"},{"speaker":"高橋（し）委員","kind":"意見","question":"非常に大事な仕組みをつくっていただいていて、すばらしいことなのですが、結局、見てみるとすごく複雑な仕組みで難しいので、今お話があったように、分かりやすいパンフレット等で周知を進めてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"}]},{"id":"topic-03","title":"令和２年度品川区介護保険制度の運営状況","agenda":"令和２年度品川区介護保険制度の運営状況","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、１ページで高齢化率が２０.２％で同じなのですけれども、高齢化率が八潮以外が全部、下がっているというのが、第八期の介護保険事業計画の中でもありましたけれども、八潮以外で高齢化率が下がっているということに対しては、どう分析されているのかということについてもお聞かせいただきたいと思います。この点をお願いします。","respondent":"宮尾高齢者福祉課長","answer":"ただ、率は横ばいになったとはいっても、高齢者の方の数が今後も一定程度、高い水準で推移していくことを考えておりますので、高齢者対策はしっかりと推進していく必要があると認識しています。","id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"認定率が下がったのもコロナの影響かということなのですけれども、本当に令和２年度というのはコロナの影響が様々なところに出ていると思うのですけれども、そういう点では、令和２年度の介護保険制度の運営状況の中で、認定率もそういうことで、コロナの影響ではないかということなのですけれども、運営状況を見たときに、コロナの影響が、あとどんなところにどういう形で出ているのかということも。","respondent":"宮尾高齢者福祉課長、菅野高齢者地域支援課長","answer":"コロナの影響ですが、令和２年度は、やはり通所系のサービスを中心に、対前年でサービスの利用実績が減少しているという傾向が見られております。ただ、全体としては、対前年で件数・金額ともに微増という形の数字が出ているところです。栄養改善事業など、中止になった事業ということで、０回、０人ということなのですけれども、こちらはやはり飲食を伴う事業なので、ほかの運動系の事業などについては、いろいろと感染症対策を講じながら再開したものの。","id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"デイサービスなども、本当に、コロナの影響で介護報酬を２段階上げたところで請求してもいいという、そうなったときに自己負担が増えてしまうことに対して品川区がすぐに対応していただいたというのは、本当に事業者の方、地域の方々から、すごくありがたいという評価をお聞きしております。コロナの影響がこれからもしばらく続くと思いますので、様々現実に合わせて対応をよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-04","title":"第6期品川区障害福祉計画・第2期品川区障害児福祉計画のパブリックコメント実施結果","agenda":"第6期品川区障害福祉計画・第2期品川区障害児福祉計画のパブリックコメント実施結果","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それと、１３団体の皆さんから出された意見というのを、これは本当に当事者の意見なので、パブリックコメントと同様にご報告いただけたらありがたいと思っているのですけれども、このヒアリングをされて、１３団体からどんな意見が出されたのかというのをまとめられたものというのはあるのか、その点についても伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"障害者団体のご意見の一覧につきましては、第４回品川区障害福祉計画策定委員会で資料としてお出ししているものです。こちらにつきましては、ホームページで掲載しますので、ご覧いただけると考えています。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"分かりました。計画の９１ページから９８ページまで、どういうサービスがどこの地域にあるかという一覧表が書かれているのですけれども、これを見ても、荏原地域というのを私もチェックしてみたところ、本当に少ないのです。そこの文言はつけていただいて、きちんとやっていただけたらという思いが私はあるのですけれども、そこの認識について伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"ただし、区としては、荏原地区に限らずなのですが、必要な施設整備は進めていくという認識は変わっておりませんので、前回と同様の方向の考え方というのは変わっておりません。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"その点は、なぜ補助金が使われなかったのか、補助金があるということも知らないということもないのかなと思ったりして、補助金が使われないのがなぜなのか、補助金を活用しながら、もっと増やすというところに持っていくにはどうしたらいいのか、その辺の区の考えをお聞かせいただけたらと思います。","respondent":"松山障害者福祉課長","answer":"ずっとご相談を頂いていた事業所ですけれども、やはり東京都の指定の時期ですとか、東京都の補助金の時期が、かなり影響がありまして、コロナの影響もあり、グループホームの説明会も延期していたりという時期もありまして、こちらの事業所は、事業所の判断として。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"こういうふうに、補助金を使わないで建てられたとお聞きしましたので、どうしたら補助金を使えて、なおかつ施設開設が進むのかという、補助金の使いやすさとかその辺のところが改善の余地がないのか、そういうことによってさらに進むように、ぜひお願いしておきたいと思います。そういう点についても伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"品川区障害福祉計画推進委員会というのを立ち上げまして、こちらは新たに立ち上げまして、計画の進捗状況の検証・分析・評価を行うということで、必要に応じて改善・見直しを行っていきますというところですので、実績については。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そうすると、ここに書かれている品川区障害福祉計画推進委員会というのは、３年間、継続して、この計画に対して第三者的にずっと評価をして、実績というのをその次につなげていくという形でやっていくということになっていくのでしょうか。この点についてもお聞かせいただきたいと思います。","respondent":"松山障害者福祉課長","answer":"これは、品川区独自の体制の中で、どういう体制がよろしいのか、あるいは計画の進捗状況の検証や分析・評価を行う体制として、障害福祉計画推進委員会ということで、現在の策定委員会や地域自立支援協議会ではなく。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほど成年後見のところでパブリックコメントについてお尋ねしたのですが、今、障害福祉計画は各自治体で、もうつくったところもあるし、２３区でも策定中だったり、策定したと思うのですが、他区のパブリックコメントのコメントの数というのでしょうか、各自治体の住民の方も大変興味・関心があったと思うので、どんな状況か、もし分かればお願いします。","respondent":"松山障害者福祉課長","answer":"他区のパブリックコメントの状況についてです。品川区は２３人で６７３件と非常に多かったのですが、次に多い意見数から申し上げますと、江戸川区が４５人で１８２件です。次に多いのが大田区で、２５人で１７１件です。","id":"exchange-019"},{"speaker":"高橋（し）委員","kind":"質問","question":"ご意見を大変たくさん頂いているということで、団体も含めて２３人ですか、それで６７３件という、今、２３区で比較して多いというご説明がありましたけれども、２３人の、団体を含めた方々から６７３件ということについて、どんな分析というか、状況ですか。","respondent":"松山障害者福祉課長","answer":"パブリックコメントの意見数の状況ですけれども、６７３件のうち、お一人の方と１団体の方で６００件以上を占めておりまして、大体９割を占めております。","id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"先ほど成年後見のところでもお話ししたのですが、パブリックコメントは、区のホームページにも意義がきちんと説明されて、非常に重要なものですので、このようなご意見を伺いながら、先ほどご説明がありましたけれども、今後、計画を進めていくということですので、今後３年間、計画の推進をきっちりと進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"せお委員","kind":"質問・要望","question":"これは具体的に、保育園、幼稚園、小学校、中学校というところと、どのような場で連携していくのか。今までどのように連携していって、情報共有などをしていって、これから、この計画だと３年だと思うのですけれども、具体的にどういった場で連携や情報共有などをしていくのか、その辺を教えていただきたいです。","respondent":"松山障害者福祉課長","answer":"今、そういった中での共通の、連携についての、どうやったら連携しやすいか、あるいは迅速にスピードアップして情報共有を図れるかというところは、現場レベルで課題を共有しています。これから具体的に少しずつ一歩一歩、進めていければと考えております。","id":"exchange-022"},{"speaker":"せお委員","kind":"質問・要望","question":"私は、本当はあまり連携という言葉は好きではなくて、当たり前なので、これから当たり前にそういったところが、部や課など関係なくスピーディーに情報共有できるようになっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-05","title":"令和2年度品川区障害福祉計画実績","agenda":"令和2年度品川区障害福祉計画実績","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"あと具体的なところで伺いたいのですけれども、１ページの（３）自立支援医療費というところで、令和２年度のところが、利用状況にしても、様々すごく激減しているという感じなのです。","respondent":"松山障害者福祉課長","answer":"２点目の自立支援医療費の、恐らく申請の件数がかなり減っているですけれども、新型コロナウイルス感染症の影響によりまして、受給者証の有効期間が１年間延長するようにということで、厚生労働省が省令を改正しておりましたので、そのために、令和２年度の自立支援医療費。","id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"２３区で１人当たり何時間使っているかというものが、東京都の資料で出ていたのですけれども、そこでも品川区は一番時間数が少ないところなのですけれども、それがさらに少なくなっているというところに、この数字がなっているのですけれども、見込みとしては上げていこうというところなので、その辺はもっと、希望に合わせて使えるというところの、相談事業所への周知ですとか。","respondent":"松山障害者福祉課長","answer":"ただし、これからワクチン等の接種が進み、感染症対策という体制がかなり強化されてまいりましたので、今年度につきましても、事業所と相談して状況を見ながら実施していくという予定です。","id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ちょっと進んで１５ページの放課後等デイサービスなのですけれども、これは先ほどの計画書の中にも、放課後等デイサービスは一時よりはちょっと増えたのですけれども、報酬が下げられたではないですか。それからさらに、これから要望というのはかなり多いと思うのですけれども、それに応えていくところでは、品川区としてはどう考えられているのかについても伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"ただし、国の報酬の考え方として、やはり様々な放課後等デイサービスのサービスメニューの中で、療育に当たらないようなものが散見されるということで、きちんと、重度の方への対応については報酬を上げるというところが、国の大きな報酬改定の考え方だと認識しております。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"これは、今ちょっと本当に、希望する人が希望する日数を受けられないという状況も伺っているのですけれども、さらに開設に向けての制度チェックをお願いしたいと思います。それから、計画相談実人数は約８３０人ということなのですが、では品川区から随分移行したということなのですけれども、品川区として組まれている件数はおよそ何％ぐらいかという、およその割合が分かったら、最後にお聞かせください。","respondent":"松山障害者福祉課長","answer":"何％かというのは手元にはないのですけれども、来年の３月末までにはほぼ移行が可能ということになっております。","id":"exchange-027"}]},{"id":"topic-06","title":"新型コロナウイルス感染症に感染した被保険者等に係る傷病手当金の延長","agenda":"新型コロナウイルス感染症に感染した被保険者等に係る傷病手当金の延長","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"周知についてなのですけれども、広報などは様々、ホームページなどなのですけれども、これは、例えば感染症で治療を受けたとか入院したなどというのが国保医療年金課で把握できて、そこから遡ってというか、受けられますよという周知みたいなものというのはあるのでしょうか。","respondent":"池田国保医療年金課長","answer":"今の周知についてですけれども、昨年度は保健予防課から、感染症にて入院された方についての一覧表みたいなものを頂きまして、確認させていただいたこともあります。ただ、今年度につきましては、まだその辺までは至っておりませんというところが状況です。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それも、今年度もそういう形でされるということでいいのでしょうか。それから、あと感染が疑われる者というものも含めて、感染が疑われるために仕事を休まざるを得ないという人も、保健所では多分、把握できるのではないかと思うのですけれども、そういうところで、国保医療年金課から、傷病手当金が受けられますよという形での連絡が行くような仕組みになっているということでいいですか。","respondent":"池田国保医療年金課長","answer":"その辺の結果については、また保健予防課から頂いたりすることもありますけれども、実際には、ご本人が、こういった症状が起きて会社を休んで給料をカットされたという事実があって申請していただくということで、やらせていただいているところです。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"でも、アルバイトは２週間休んでくださいみたいな形で言われた方というのも、傷病手当金の対象になるということでいいのでしょうか。そういう人は自らが、アルバイトの就労日数を傷病手当金ということで申請できるということでいいのでしょうか。それは、自分で気づいて申請するという仕組みしかないのかというところも、ちょっと教えてください。","respondent":"池田国保医療年金課長","answer":"傷病手当金の申請につきましては、まず勤務状況につきましては、勤務先で、いつからいつまで休んだかという事実を書いていただくところもありますし、また、今お話のございましたアルバイト勤務の方ですと、シフトというものがあるかと思いますので、何日から何日と。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"いまだにＰＣＲ検査までいかなくて、２週間休んでくださいというのが結構あるのです。嗅覚障害みたいな形で、取りあえず２週間休んでおいてくださいみたいな、そういう方というのも対象になるというところでは、本人が気づいて申請するしかないので、そういう点では、広報しながわ、ホームページというところで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"}]},{"id":"topic-07","title":"品川区の新型コロナウイルス感染症にかかるワクチン接種状況","agenda":"品川区の新型コロナウイルス感染症にかかるワクチン接種状況","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ワクチンが足りないというところでは、集団接種会場は、予約が取れている分も、これから予約が取れるという分も、２回分は確保されているということなのですけれども、これからの見通しというのは、今のところのワクチンの確保分は３５％ということですけれども、これからのほうが人数が多いのですけれども、その部分は順調に入ってくると考えていいのでしょうか。それとも東京都から来るという仕組みなのか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"７月と大体同じぐらいの数が国から発出されるということで、通知がありました。ただ、品川区に幾つ来るかということは、現在はまだ分かっておりません。現時点で国から通知があるのは、８月分の今のご説明のところまでです。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"でも、８月も幾つ入ってくるか分からないというふうなことであると、８月分の予約というのもすごく取りにくいのかと思うのですけれども、その辺のところは、７月と同じだけ入ってくるといっても、幾つ来るのかまだ分からないとなると、それが分かってから８月分の予約を取るという形になっていくのでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ただ、これに加えて、今後、８月分の予約枠、一部絞っている部分がありますので、絞っている部分をさらに上乗せできるかどうか。９月以降の予約枠をどこまで開放できるかどうかというのは、現時点では慎重に進めていかなければいけないと考えております。","id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"せっかく体制を整えたのに、今度はワクチンが足りなくて、整えた体制がフル稼働できないという状況というのは、本当に厳しいものがあるという思いがしています。それから、高齢者のワクチンなのですけれども、７月末までに高齢者全員のワクチン接種が終えられるということで、区としても出したと思うのですけれども、７月末までに終える見通しというのはどんな状況なのかも伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"現在、今の件に関しましては、所管と調整を進めているところです。７月末に終わる見込みについては、前回の厚生委員会でもお伝えしているかと思いますが、試算上は、７月末までに高齢者の人数分の枠は開放しております。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"できる限り早くにお知らせされると、すごく安心ということもあるので、ぜひそういう体制を取っていただいて、早めにお知らせをしていただけるようにしていただきたいと思うのですが、その点、お聞かせください。そういうところでは、まず７月２日から始まって、基礎疾患を有する方などを優先的にやるというところは、予約などがスムーズにいっているのか、その点についてもお聞かせください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"所管との調整につきましては、早めに進められるように引き続き努力してまいります。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"本当に人数もたくさんですし、ワクチンがスムーズに入ってこなかったり、次々といろいろ大変ですけれども、これからも様々な対応でスムーズにいきますように、よろしくお願いしたいと思います。本当にお疲れさまです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問","question":"１つだけ、先ほど６月２９日に６４歳以下の方々に発送したという話があって、それで配達が遅れてというお話がありました。これはどういった理由で。２９日に郵便局のほうに持って行ったけれども、その後どこかでというのか、それとも、その前の段階で、少し持っていくのが遅れたかなど、その辺がもし分かればお願いします。６４歳以下の方々で、まだ来ないと随分お問い合わせがありましたので。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"郵便局とは事前に調整はさせていただいておりまして、持ち込んだら、もしかしたら１週間程度はかかるかもしれませんということは確かにご案内はありましたが、通常、２日から３日で到着するというお話がありましたので、こちらも、ではなるべく早くお願いしますということと。","id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"意見","question":"投票所入場整理券については、またちょっと事情が違うのかもしれませんけれども。皆さん、非常に不安な状況だったので、次ということはないのかもしれませんけれども、その辺りの郵便局との交渉は、やっていただけると思いますけれども、よりしっかりとお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"せお委員","kind":"質問","question":"今、２３９箱を確保しているということなのですけれども、これはファイザー社とモデルナ社が混ざって両方あるのかということと、あと、ホームページにも、「１回目の接種と２回目の接種は、同一の接種会場または実施医療機関で受けてください」というのは、すごく大きく書いてくださっているのですけれども、１回目と２回目の接種の予約、２回目の予約などが違う場所になっている場合というのは。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ただ、２回目の３週間後の同じ曜日の同じ時間帯がどうしてもご都合が悪い方は、ご自身の判断の下に翌日以降、ご自身でキャンセルをして予約を取り直すということになっておりまして、その方々がどこの会場に移ったかというのは、こちらでは正直、把握はできておりませんが、一応。","id":"exchange-039"},{"speaker":"せお委員","kind":"質問・要望","question":"他の自治体などでは、１回目がモデルナで、２回目がファイザーのものを打ってしまったということがあったようですので、それぞれ医療機関などでも注意してくださっていますし、集団接種会場でも注意されていると思うのですけれども、その辺は効果が変わってきてしまうので、ぜひ注意して、その辺は対策を練っていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"若林委員","kind":"質問・要望","question":"一方で、特に個別接種の場合は、電話であったり、予約をされると思うのですが、区のホームページの表現が変わっていないので電話をすると、多分いわゆる絞り込みということだと思うのですけれども、「今、予約は新規で受けていないのです」ということがあるとは個別に聞いておりますので、区のホームページの区民へのアナウンス、「今、集団接種、特に個別接種会場での予約については。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ただ、個別接種会場につきましては、今、両医師会とお話もしているところではありますが、医師会、それから各クリニックの先生方の、予約が取れる人数や、予約の開放の考え方もありまして、区の考えに縛られるものではございませんので、現在、医師会が。","id":"exchange-041"},{"speaker":"若林委員","kind":"質問・要望","question":"丁寧にありがとうあります。いずれにしても、どこで目詰まりしているのか、いろいろな報道もありますけれども、国ではしっかり、もう対応していただきたいということで、区も当然、ご要望されていると思いますし、私たちも私たちの立場でしっかり要望していきたいと。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"というのと、現時点では２９歳以下の方も含めて全区民の方のワクチン量が、今、確保できている状態ではございませんので、枠の開放について前倒しどころか、もしかしたらどこかでストップをかけなければいけないことも検討しないといけない状態になるかもしれませんで、これは今。","id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"高齢者施設や障害者施設、障害者のグループホームなども含めて、それから、あと在宅の要介護度の高い方の接種というのは、現状、どんな状況になっているのか、教えてください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"高齢者施設の接種については、時期的にもうほぼ終わる頃になります。それから在宅についても、順次、できるところから、今、スタートしています。","id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"在宅の方というのは、体制としては、往診の先生が何人かでやってくださっているという、往診でもやる先生とやらない先生と、あと自分が往診しているところではないところも巡回という形でやっていただいているという、そこの体制についても教えていただきたいのと、あと障害者のグループホームなども、グループホームに入られている方も。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"同じ日に一度に従事者の方全員に打ってしまうことは副反応等との関係で、そういったことができないのと、あと基本的に余りワクチンで対応するということになっていますので、もちろん打っている方もいますけれども、全ての方が打ち終わっているかどうかというのは。","id":"exchange-044"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけお聞きしたいのですけれども、集団接種会場と１２０か所の個別接種会場があると思うのですが、残が出ますよね。６回分ずつというのか、例えば、１日２とか３とか残りが出たときは、どういう対応をしているのですか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"残についてのご質問です。集団接種会場から出た余りワクチンにつきましては、３時から３時半ぐらいの時間に、総務課に一回、その数の報告が来まして、総務課で持っているリストから割り当てて、職員をその会場に派遣して、余らないように打つという流れになっております。","id":"exchange-045"},{"speaker":"石田（秀）委員","kind":"意見","question":"今の余りワクチンなのですが、そこの接種会場、集団でも個別でもいいのだけど、それぞれご苦労いただいて、例えば近隣の商店街と連携して、窓口は決めておいて、今言った４時頃に連絡を入れて、商店街で打てる人、お店の方とか、すぐ来てくださいとか、そういうことをやっているのは、すごくいいことだと私は思っているのだけど、それはそれでもいいということですよね。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"あくまでも集団接種会場については区のほうでという形でやってはおりますが、個別接種のクリニックにつきましては、クリニックの先生のご判断で動いていただく分は往々にしてあるかと思いますので、結構かと思います。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/779921?Template=document&Id=3602#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":52701,"voices":138}},{"id":"r03-20210707-8","meetingId":"r03-cm07","date":"2021年7月7日","dateIso":"2021-07-07","committee":"建設委員会","time":"午前１０時００分～午後 ２時０５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それと、今回アンケートをやるということですが、この間私たちも指摘していますが、超高層ビルのまちづくりですとか、特定整備路線などの巨大道路計画、こうしたことには批判が上がっていますので、その賛否が分かるようなアンケートをやるべきではないかということを伺いたいと思います。重要な点だと思うのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"今後委員会の中でも、公募区民の方ですとか、町会の団体の方ですとかに入っていただくことになってありますし、パブリックコメントなども実施してまいりますので、そうしたところで環境のところもしっかり検討していきたいと、お声を聞いていただきたいです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"ウェブのことは、ご答弁を聞いたところでは不特定多数の方にやるような感じだったと思うのですが、そうではなくて抽出した方がウェブで回答できる、そうしたほうが回答率は上がってくるのではないかということで伺いましたので、もしご答弁があったらお答えいただければと思います。各地で再開発が行われていくところで、住民からもやめてほしいという声が次々に上がってきているところです。","respondent":"鈴木都市計画課長","answer":"再度質問いただいた、抽出した方がウェブ上でも回答いただけるというやり方ですが、ご自宅がウェブにも対応できる環境にあるかどうかということもあると思いますので、ちょっと研究はしてまいりたいと思いますが、基本は郵送回収という形で考えていきたいところです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで、スケジュールというか今後の委員会のことで指摘をしていきたいと思うのですが、今回、学識経験者、区内関係団体、公募区民等ということで委員会を立ち上げるということですけれども、この中には議員は入っているのかどうかということ、入れるべきではないかということで伺いたいと思います。そして、まちづくりとなると、いろいろな視点があると思うのです。","respondent":"鈴木都市計画課長","answer":"前回は新たに策定するということで、そういう分科会も立ち上げましたが、今回は２０年間の計画期間の中間の改定というところですので、今のところ、分科会という形を立ち上げて検討を進めるという考えはございません。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"分科会については適宜ということでしたけれども、改定なのでということもありましたが、やはりこの状況、１０年経っているということもありますし、質問項目の中にコロナ禍でどう変化したかということもありますので、やはり大きな変化もあると思われますから、ぜひ、分科会を設置するなど深く議論をしていくべきだと思います。","respondent":"鈴木都市計画課長","answer":"今のところ、７月から始めて１か月で実施して、その結果の整理ですとかもありますが、基本的には１回目の１０月で、アンケートの結果についてはご提示をしていきたいと、予定としては考えてあります。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"１つ聞き忘れました。学識経験者というのは、何人入られてどういう分野の方なのか、伺います。","respondent":"鈴木都市計画課長","answer":"学識経験者の人数、並びにお声がけをする方々については、今まさに検討しているところです。前回の策定のときは２名入っていただいたのですが、今回は二、三名程度で考えているところです。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"区がやるわけではないと思うのですけれど、予算と、どこに外注しているのかというのをまずお聞きしたいです。それと、区外の方へはウェブ調査会社の登録モニターということですけれど、これは信憑性があるのか、どうなのだろうと。例えば、品川区長期基本構想とは何ですかと。私たちは聞いて当たり前になっていますけれど、マスタープランって何ですかということだと思うのです。","respondent":"鈴木都市計画課長","answer":"用語の説明ですが、先ほどご紹介いただいたように用語が分からなくならないように、ところどころには説明をつけて作成しているのですが、マスタープラン、あるいは長期基本計画、そもそもそれって何なのというところは確かに、そういう視点を持たれると。","id":"exchange-006"},{"speaker":"西本委員","kind":"提案","question":"それから分析の方法ですけれど、やはりどう読み取るかということがとても大切で、結局、委員会があってそこに提案というか報告すると思うのですね。だから、この事業はどうですかなどと聞くと、賛否を問う形になってしまう。なので、そこら辺を踏まえて、委員会に提案をしていただきたいと思っています。これは意見として言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"}]},{"id":"topic-02","title":"小山三丁目第１地区および小山三丁目第２地区再開発事業事業者による近隣説明会の開催","agenda":"小山三丁目第１地区および小山三丁目第２地区再開発事業事業者による近隣説明会の開催","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"資料に基づいて伺いたいのですが、この説明会の開催予定は、小山三丁目第１地区は６回やると。それで、この説明会の周知というのはどのように行われたのかということなのですが、対象範囲としては敷地境界から約２９０ｍの範囲ということになっておりますが、地域に入っているだろうというところでチラシが来ていないという声もあって、チラシはいつ配ったのか、そういったことを伺いたいと思います。","respondent":"多並都市開発課長","answer":"小山三丁目第１地区につきましては、予定しています、ここに記載させていただいたスクエア荏原の大会議室になりますけれども、コロナ対策をしますのでキャパシティが３０名から４０名ほどの大きさしかとれないということがありまして。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり大きな１４５ｍの超高層ビルが建つということですから、２つの地区を合わせて３棟建つということですので、大きく周辺住民にも影響があるということですので、これはもう広く周知をしていただきたいと思います。やはり、どこまで合意がされているのか、準備組合の会議もやられていると思うのですが、そこでの参加率ですとか、どういった方が参加をされているのか、人数なども伺いたいと思います。","respondent":"多並都市開発課長","answer":"借地権者の方が１３名。準備組合に参加いただいている方は４４.５名、参加率が７５％となっています。総会につきましては、その時々によってまた違います。委任状というのでしょうか、出されている場合ありますので、その時々によって参加率は違うというふうに認識しています。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問","question":"第１地区は９２％の人が参加しているということですが、参加をしても意見が通らないということも言われているのです。そうした方の意見もしっかりと反映できるようにしていくべきだと思いますけれども、いかがでしょうか。それと、今回の小山三丁目の第１、第２地区の総事業費と補助金の額、あと公共施設管理者負担金というものがあったと思いますが、そういうものは幾らなのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"事業費もしくは補助金については、これは組合施工になりますから組合のほうで検討していくことになりますけれども、現時点は両地区とも算定中と聞いているところです。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"既に駅の混雑ということが言われておりますけれども、今、１棟目が出来上がって、２棟目も躯体は出来上がってという状況で、どれだけ埋まっているかも分かれば教えていただきたいのですけれども、やはり住民が増えるということは確かなので、駅の混雑がこれからさらに３棟もできるということになりますので、大変なことになると思うのですが、どのように考えていらっしゃるのか伺いたいと思います。","respondent":"多並都市開発課長","answer":"やはりこういう既存の商店街と連携した事業というのは、全国でも多くあるわけでありませんので、そこはよく、特に商店街本体のところ、今回の開発については２地区進めるということでもありますので、パルム商店街、また各地区の組合とよく連携しながら。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"住戸数はやはり相当な数があると。駅の問題では東急とお話し合いをしているということでしたが、車両を増やすというのはありましたが、ほかにも何か混雑緩和に向けての話し合いをされていることがあったら、伺いたいと思います。それで、Ｂ棟の１と２でこれだけ戸数が違うというのは、どういうことなのかと思ったので、そこも伺いたいと思います。","respondent":"多並都市開発課長","answer":"第１地区と第２地区は両方一緒に検討しているところもありましたから、その中で連携しながら進めようということで、例えば公共貢献施設についても１地区の中だけで考えるのではなく、両地区で合わせながら、どういうものがあればいいのかということで。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"すみません、聞き方が悪かったのか。Ｂ－１と２で住戸数が６１０戸と３８０戸ということで、高さとかは同じなのですが、これだけ違うのに驚いたので、どういうことなのかと伺ったので、ご答弁いただければと思います。それで、今後のこの周辺のまちづくりの開発は、さらにほかのところ、パルム商店街、武蔵小山商店街のほうにも続いていくのか、今後の計画を伺いたいと思います。","respondent":"多並都市開発課長","answer":"今後の予定ですけれども、現時点は賑わい軸地区の中の小山三丁目第１地区、小山三丁目第２地区ということですけれども、それ以降の賑わい軸地区につきましては、今後どのような形で進めていくのがいいかということで、それを今、地元の方とお話しさせていただいています。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"やはりこうした再開発で、住み続けてきた人たちが残れなくなってしまうというまちづくりは、やめるべきだと私は思います。最後に、地権者、権利者の方で残る方というのはどれだけいるのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"今後の進め方ですけれども、都市計画決定は今年度と、予定ということでお話ししました。来年度に、順調にいけば組合設立、その後に権利変換という手続きになります。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"準備組合のほうに、小山三丁目第１地区だと９２％入られている、第２地区は７５％ということなのですが、かなり高い確率で参加されているというのは分かるのですが、多分いろいろな意見が出ているのだろうと思うのです。本当にここの地域は、これで何棟目ですか。そのためにも、今進めようとされているところの住民たちの思いがどうなのかというところが気になるのですけれど、いかがでしょうか。","respondent":"多並都市開発課長","answer":"ここにつきましては、いろいろお話を聞いていると、もっと先にやるべきことと、今のこと、いろいろなことが混在してお話しいただいているように私は捉えていますので、それで組合の事務局の方にお話したのは、今やることがどこまで決まって、今後どうするべきなのか。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"進めていくと、意外ときっかけが分からなくなってしまうということがあって、これだけ長いスパンで開発がされて、次から次へと大きなビルが建ってしまってというようになってくると、もともと何だっけ、このまちはどういうまちを望んでいたのでしょうかみたいな状況になってきてしまうので、これを説明する際にも、もともとはこういう話があって、こういう進め方があって、今ここでというふうに。","respondent":"多並都市開発課長","answer":"今ご指摘いただいたような社会の変化といいますか、この開発による変化ということで、例えば混雑の点でいえば、先ほどご説明したように東急電鉄との調整をさせていただいています。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"最後にもう一つ。新しい方が入ってこられると思うのです。やはり地域から隔離されるのでなく、やはり地域の中で生活していくというようなこともやっていっていただきたい。それは全て防災とかに関係している話なので、その不動産を持っている方と、住んでいる方が違うということも往々にしてあることなので、それは配慮して組合のほうとも調整を図っていただきたいと思いますが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"やはりこれも地区、地区で考えるのではなく、幅広い地区の、今後進める方々の、今進めた、終わった方々がちゃんと連携しながら進めていこうと、そういう機運もありましたので、区としてもそういう場を定期的に開いて、その中でもよく情報交換していただいて。","id":"exchange-017"},{"speaker":"大沢副委員長","kind":"質問","question":"あるイベントというのは１週間かけて７月４日に終わったもので、非常に近隣の方、あるいは商店街の方、迷惑されているのです。かなりのところから、商店街からも、近隣からも苦情が、私のところにたくさん入っています。だから、まちづくりの中で、道路なので、これは警察のほうになってしまうのでしょうけれども、そういう規制というか、何かかけることはできないのですか。","respondent":"多並都市開発課長","answer":"今の交通広場というのでしょうか、警察との連携については、防災まちづくり部ともよく連携しながら、できることがあるか、ちょっと考えていきたいと考えています。","id":"exchange-018"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"やはりまちづくりですから、にぎわいも大事だけれど、ある程度、住環境なり商業環境も考えてやっていただかないと、便がいいからという副産物として、そういういろいろなイベント、あるいは車が入り込んでくるのでしょうけれども、第一はやはり住民目線、あるいは地域の方の目線、生活者目線でやはり見ていただかないと、にぎわいも確かに大事かもしれないですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-03","title":"東五反田二丁目北地区に関する都市計画案","agenda":"東五反田二丁目北地区に関する都市計画案","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"この間、広報でやっているのでということですが、やはり直接チラシがポストに入るということで、多くの方が気づくということがあります。そうしたお知らせを、こうした説明会もやっていくべきだと思いますが、いかがでしょうか。これまでの経緯というところで、２月に開発計画の説明会が実施されたということでしたけれども、ここではどのような意見が出たのか、伺えればと思います。","respondent":"多並都市開発課長","answer":"周知の件ですが、この案件以外も含めまして、都市計画の手続きの周知と意見集約の進め方ですけれども、これまでも、この件で言えば２月には事業者の方、要するにこの事業を進める方が、周知で地域の方へ説明会を開くと。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問","question":"容積率、３００％から５２０％になったということですが、高さについてはご答弁がなかったですが、今までと同じなのかどうか、そこもお答えいただければと思います。それとＢ地区について、容積率の最低限度、最高限度、建ぺい率の最高限度、高さの最高限度についてはここに書かれていませんが、Ａ地区とＢ地区の違いといいますか、なぜ書かれていないのかを伺いたいと思います。","respondent":"多並都市開発課長","answer":"ただ、今回地区計画を定める際に、Ｂ地区で総合設計で予定しているところを追認する形で、この地区計画というのを一緒に定めようということで定めているものなので、建物はもう計画が進んでいるということですので、あえてその計画については設定しないという取扱いにしていると。","id":"exchange-021"}]},{"id":"topic-04","title":"その他の(1)所管質問","agenda":"その他の(1)所管質問","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"安藤議員の、「住民を追い出し開発企業の利益を優先する、大崎西口駅前地区・品川駅南地区の超高層再開発は撤回を」の質問で、大崎の計画は、区域内全員を転出させる前提の計画を問題だとは思わないのかという質問に対して、区は、個々の選択の自由と答弁をしました。この個々の選択の自由とはどういう意味か。選択できないと思いますが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"今、ご質問いただきました大崎駅西口駅前地区につきましては、平成２６年に市街地再開発準備組合が設立し、これまで再開発に関する検討が進められてきております。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"法的には、残ることも、出ることもできるというご説明だったと思うのですが、今の計画上、この大崎西口駅前地区というのは、全てオフィスビルにすると。だからこそ住民の方々も怒っていらっしゃるということですので、その選択の自由というのが実際にはないのではないかということでお聞きしましたので、その答弁をしていただきたいと思います。","respondent":"多並都市開発課長","answer":"ただ、それにつきましても、一番はやはり皆さんがご納得いただけるような生活再建のプランにしていくということでもありますので、それをご検討いただきたいということで、先ほど決まっているというお話でしたけれど、決まっていませんので。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"８割がこの計画を理解しているということでしたが、２割の人は納得してないわけですよね。残りたいわけです。そうした計画を区が認めていくということになると、やはり居住者の生活圏ですとか、そういったことも脅かすことにもなりますので、区としては皆さんで話し合ってという話ですが、残りたいという人がちゃんと残れる案にしていくことが必要だと思いますけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"区が考えるというより、準備組合の方がご自由に、どういうプランにしていくのか考えていらっしゃっている途中というふうに認識していますから、それはやはり皆さんがご納得いただくように、議論をしっかりしていただくことが一番重要かと思います。","id":"exchange-024"},{"speaker":"のだて委員","kind":"意見","question":"話し合いということですが、その方向でもうほぼ進んでいるわけですよね。やはり住民合意が必要だと思いますし、残りたいという人が追い出されてしまうということは問題だと思いますので、区としても、この話し合いを目指して設計していく、そういったことが必要だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"}]},{"id":"topic-05","title":"に戻りまして、(4)区内で初めて確認された「クビアカツヤカミキリ」","agenda":"に戻りまして、(4)区内で初めて確認された「クビアカツヤカミキリ」","exchanges":[{"speaker":"塚本委員","kind":"確認","question":"発見が６月１７日で、区からいろいろ発信されて、私のところにもそういうものがあると届いて、確認した覚えがありますけれども、それ以降区内で区民等から、発見等の通報等はありましたでしょうか。","respondent":"河内環境課長","answer":"こちら、説明が足りずに申し訳ございませんでした。その後の経過ですが、その後６月２１日に同発見場所付近で、通行人がまた成虫を発見したとの報告がございまして、周辺調査をいたしましたが、特にその後発見もなくということでございました。","id":"exchange-026"},{"speaker":"塚本委員","kind":"質問","question":"当面、何か拡大している雰囲気というのは今のところつかんでいないのかと思うのですけれども、これは日本の中で今、結構被害が出ている地域とかはあるのでしょうか。","respondent":"河内環境課長","answer":"今後も、フラスと言いましてフンが大変分かりやすい特徴がありますので、そういったものを目標にしながら、しっかりとした対策を継続していきたいと考えているところです。トップシーズンが６月から大体８月頃です。もう一息ですので、しっかりと対応を進めてまいりたいです。","id":"exchange-027"},{"speaker":"のだて委員","kind":"確認","question":"先ほど少し説明がありましたけれども、以前に確認された足立区、江東区でのその後の被害というのはどうだったのか伺いたいのと、広域的、継続的な警戒が必要だということなのですけれど、なぜ必要なのか、その理由を伺いたいと思います。","respondent":"河内環境課長","answer":"そういったところも踏まえまして、しっかりとした対応を進めるべく、広域的な声かけもしながら取り組んでいるところです。","id":"exchange-028"}]},{"id":"topic-06","title":"第１１次品川区交通安全計画（素案）","agenda":"第１１次品川区交通安全計画（素案）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"これまでの第１０次品川区交通安全計画の課題と、今後の対策を伺いたいと思います。先ほどと少しかぶるかもしれませんが、原因を伺いたいと思います。そして、今、コロナという事態にもなっていますが、令和に入ってから死傷者数が減ってきているというのは、そういうことも関係しているのかなと思ったのですが、コロナ禍のもとでの関係性といいますか、もしありましたら伺いたいと思います。","respondent":"川口交通安全担当課長","answer":"２９年、３０年にそれぞれ下げ止まった部分ですけれども、こちらにつきましては、今説明をさせていただきましたような自転車の事故がだんだんと増えていったというところが、主な原因であるというふうには考えてあります。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"あそこは事故などがあって歩車分離にしたということがあると思いますので、いかがでしょうか。あそこは通常の交差点と違うので、歩車分離だと視覚障害の方が分かりにくいという声も聞いておりまして、ぜひ音響信号を、そしてエスコートゾーンといった設置を、２６号線は都道ですか、そういった関係機関とも調整していただいて、ぜひ設置を進めていただきたいと思いますが、いかがでしょうか。","respondent":"川口交通安全担当課長","answer":"引き続き、そちらの設置について区として働きかけていきたいと考えております。パブリックコメントに関する説明会の実施の関係ですけれども、通常のパブリックコメントの要綱に基づく手続きを踏んでいるところでございまして、現在のところ考えてございません。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"そうすると分析が変わってくるのではないかと思いましたが、その辺はどうかなと思っています。それから、この６つの重点の６、「新しい生活様式」への対応ということで、２つほど書いてあるのですが、よく分からないのです。オンラインを使った交通安全教育ということが、「新しい生活様式」への対応なのかと思ってしまったのですが、その辺も教えてください。","respondent":"川口交通安全担当課長","answer":"２点目の「新しい生活様式」への対応ということですけれども、これは恐れ入りますが、別紙２の４１ページをお開きいただければと思います。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"この「新しい生活様式」、今のお話であれば、この６つの中の１番目、子どもの交通安全の確保の中に入るのではないかと思うのです。そこは非常に問題があって、そういう事業所の方々への指導というのはされてき始めていると思うのですが、品川区もそういう指導は当然必要だと思うし、やはり注視していかないと、事故が非常に多くなっていく可能性があると思っているのですが、その辺はいかがですか。","respondent":"川口交通安全担当課長","answer":"その具体的な対応につきましては、各年度ごとに実施計画、事業計画を立てますので、そちらのほうで中身をもんでいくような形になると思います。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問・要望","question":"まとめます。事故が起きて命がなくなってしまうというようなことに決してならないように、事前に準備を進めていただきたいと思っていますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問","question":"自転車の交通安全というところについて少しお伺いしたいのですけれど、これまでのご説明の中で、自転車の事故が増えていますと。ここが、いわゆる違反した人たちが起こした事故と、自転車通行帯とかの環境がしっかりしていないから違反を起こしてしまって、事故につながっているというような分析はできるのかどうかというのが１点。","respondent":"川口交通安全担当課長","answer":"自転車活用推進計画との絡みですけれども、今回の第１１次計画につきましては、今後の動き、区としてはまだ具体的なところは進んでおりませんけれども、このような自転車活用推進計画策定時には、必ずそういう配慮が行われるような記載方法をしているところでございまして。","id":"exchange-034"},{"speaker":"芹澤委員","kind":"質問・要望","question":"何点かお伺いしたいのですが、自転車に私も毎日乗っているのですけれども、自転車は免許制度でもないと思うので、意識の啓発というのは、最初になかなかできないのではないかと思っていまして、今回、自転車の事故が増えてきているのも、自転車に乗る人が増えてきているので、いくら注意をしても僕自身も明日は我が身だと思って、いつ事故が起きるかというのも思っているのですけれど、事故が起きたとき。","respondent":"川口交通安全担当課長","answer":"こちらにつきまして、自転車の安全利用の月間等を含めまして、区としても、ヘルメットに関する利用の普及啓発、情報発信に努めているところではあります。","id":"exchange-035"}]},{"id":"topic-07","title":"大井坂下公園改修工事","agenda":"大井坂下公園改修工事","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"以前、この公園の中に喫煙所があったという話で、それが結構問題になっていたということで、今回の改修でその喫煙所はどうなるのか、なくすのか、伺いたいと思います。すみません、不勉強で申し訳ないのですが、コミュニケーションサインというのはどういうものなのか、ご説明いただけますか。","respondent":"高梨公園課長","answer":"２点目のコミュニケーションサインですが、これは自分の気持ちをうまく言葉で伝えることができないお子さんもいるというようなことから、例えば痛い、寒いというような自分の気持ちであったり、どこで遊びたいという遊具の種類などを記載したボードを。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"これは子どもたちのアイデアを活用したということなのですけれど、どういう議論からこういう形にしたのか、お聞きしたいと思います。夏場は涼しいという面もあるのですが、防犯上どうなのだというところもあったり、そこはどうなのでしょう。切れとは言いませんが、少し枝を切るとか、明るいイメージが欲しいと思う公園の一つかなと思っているのですが、いかがでしょうか。","respondent":"高梨公園課長","answer":"そちらの対応といたしまして、大きなイチョウの木等もあって、切ってしまうというのはなかなか忍びないところがあるのですが、樹木の整理ということで必要なものについては一部伐採もありますが、基本的には剪定等により見通しよく、明るく。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問・要望","question":"それと、宣伝、ＰＲというのも一つあるのかなと思っていて、せっかくつくられるわけですから、誰でも遊べるよという形で、本来、ユニバーサルデザインという意味合いは何かというと、健常者と配慮の必要な方々が一緒に遊べるというのが大きな目標だと思うのです。それから、ここはビルの中にあるというか、結構死角がないようであるのですよね。","respondent":"高梨公園課長","answer":"ただ、どうしても子どもたちのアイデアをそのままというわけにはいきませんので、しっかりと遊具の基準等に照らし合わせて、車いすで通れるというけれども、本当にその幅があるのか、大丈夫なのかといったところは、まちづくり条例等で該当する基準等としっかり照らし合わせて。","id":"exchange-038"}]},{"id":"topic-08","title":"マイガーデン西五反田の利用者募集および利用開始","agenda":"マイガーデン西五反田の利用者募集および利用開始","exchanges":[{"speaker":"西本委員","kind":"質問","question":"この区内のマイガーデン、非常に人気があるのですよね。南大井とか。それで抽選に漏れると、皆さんがっかりされるのです。なので、増えることはとてもありがたいと思っているのですが、今後、何かこういう形で整備していくという計画はあるのでしょうか。","respondent":"高梨公園課長","answer":"希望される方々それぞれに行き渡る量の農園が準備できると一番いいと考えているところですが、なかなか、土地の少ない品川区においては、確保が難しい状況です。現在のところ、西五反田に続くマイガーデンの予定地は計画されてございません。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"結局、地べたのところは限られてしまうと思うのですね。ですが、屋上の活用とかいうところがあると、また少し、適用できるところは少ないかもしれないのですけれど、そういうことで意外と、近場で菜園ができると、つくっていくと、とても皆さん喜ばれるのではないかと思うので、それもちょっと研究していただきたいと思っているのですが、そういう考え方はいかがでしょうか。","respondent":"高梨公園課長、藤田防災まちづくり部長","answer":"思いのある方が多くいらっしゃいますので、できるだけ菜園ができるところが増えていく方向で検討できればいいなと思ってありますが、屋上の菜園や緑地というものは、まず。施設管理者が設置した屋上の緑化であったり畑であったりすれば、その中で利用ができるのですが、朝早くからお水をやりに行きたいというような方も、マイガーデンの中にはいらっしゃるということもありまして。","id":"exchange-040"},{"speaker":"西本委員","kind":"提案","question":"そうなのです。管理が大変なのです。そこで、学校の屋上というのを提案して、土などは改良されていて、本当に薄くても作物が育成できるというものもあるのですね。ただ、部長がおっしゃるように管理という意味でいうと、学校に出入りしていいのかとかいろいろあるので、可能なところを見て、やはりマイガーデンはいい制度だと思っているので、それを広げていただくように研究をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"芹澤委員","kind":"質問・要望","question":"１点、所管が若干違ったらおっしゃっていただきたいのですけれども、マイガーデンについてということで、以前、本多委員から、用地買収とかをしたところをマイガーデンみたいに使えないかということが以前あって、マイガーデンでなくてもプランターを置くなりして、東京都がいいですよと言ってくださっているみたいなお話があって、地域と区で検討していくというようなお話が、二。","respondent":"高梨公園課長、稲田土木管理課長","answer":"ですが、具体的なご要望、ここでどのようなことをやりたいというものを、やはり東京都としても知りたい、持ってきてもらいたいところがございまして、そういった具体的なご要望を区民の方々からいただいて。私どもの聞いた話で、正確性には欠けるかもしれませんけれども、コロナ禍が始まって、テラス営業、店先にテーブルを出してやることもできるというような制度ができたのですが、それを利用しながら、戸越公園駅の南側なのですけれども。","id":"exchange-042"}]},{"id":"topic-09","title":"下水道管老朽化対策事業（再構築事業）","agenda":"下水道管老朽化対策事業（再構築事業）","exchanges":[{"speaker":"西本委員","kind":"質問","question":"今回はこの東五反田なのですけれども、品川区全体でどのぐらいの老朽化の進み具合というか、計画というか、そういうものはどういうふうに考えられているのでしょうか。","respondent":"栗原河川下水道課長","answer":"品川区内の第１期再構築エリアにつきましては、目黒川の北側が該当いたしまして、こちらの事業を東京都下水道局と連携して実施しております。進捗につきましては、おおむねそちらのエリアの３割程度が完了したという状況です。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"この事業については東京都下水道局ということなのですが、すみません、ずれるかもしれませんが、品川区全体に対する老朽化対策というのは、何か計画とかはあるのか。これは東京都の受託になると思うのですけれど、品川区はどういうふうに考えられているのでしょうか。","respondent":"栗原河川下水道課長","answer":"品川区内の下水道管の老朽化対策ですけれども、先ほど述べましたように第１期再構築エリア、目黒川の北側は、令和１１年度までに東京都下水道局と連携して実施していく予定です。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"それは分かりました。以前聞いたとき、品川区はかなり進んでいますと聞いたのです。品川区全体を見るとかなり進んでいて、今回の、これは樹脂材を入れるわけですよね。樹脂材を入れる方法もご説明を聞いたことがあって、そのときに品川区内の下水道については大分進んでいますというふうに聞いたのですけれど、どういう状況なのでしょうか。","respondent":"栗原河川下水道課長","answer":"品川区は東京都から下水道事業を受託して進めているということもございまして、かなりスピードアップを図って対策を実施してきているというのが現状でございまして、進んでいるというご認識は正しいご認識かと考えています。","id":"exchange-045"},{"speaker":"塚本委員","kind":"質問・要望","question":"管きょ更生工法というのを確認させていただきたいのですけれど、老朽化に伴う陥没防止というのはよく分かるのですが、排水能力の増強ということが、これはこの管きょ更生工法をすると、かつてより排水能力が上がるという捉え方でいいのでしょうか。","respondent":"栗原河川下水道課長","answer":"設計に当たりましては、下水道局が定める降雨基準であります、１時間５０ｍｍの降雨に耐えられるような管の大きさかどうかのチェックを行いまして、更生工法でも耐えられる場合は更生工法で実施いたしまして、それでも難しい場合は管を取替えて、管きょを増強してやっていきます。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297355?Template=document&Id=4326#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":51092,"voices":139}},{"id":"r03-20210707-9","meetingId":"r03-cm07","date":"2021年7月7日","dateIso":"2021-07-07","committee":"文教委員会","time":"午前１０時００分～午後 ０時２３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","topics":[{"id":"topic-01","title":"はじめに、(1)学校改築の進捗","agenda":"はじめに、(1)学校改築の進捗","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"あわせて、随時、小学校の学級編成も全学年３５人になっていくわけですけれども、これを踏まえて改築計画を立てている学校というのは、今日、１枚目の資料で提示された学校で言うとどこになるのか、伺いたいと思います。","respondent":"有馬庶務課長","answer":"３５人学級への対応ですけれども、鮫浜小学校、浜川小学校、第四日野小学校、浜川中学校につきましては、いわゆる３５人学級にという話を受けて計画をしたものではありません。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。今後の改築計画を立てるに当たって、これらの少人数学級の流れ、少なくとも中学校は、恐らくこうなるだろうという、こういう流れを踏まえるべきだと思うのですけれども、いかがでしょうか。","respondent":"有馬庶務課長","answer":"今、品川区の学校では、文科省の基準から言えば、１人当たりの校庭の面積が非常に狭くなっているという現実もありますので、運動スペースを確保しつつ、有効な校舎も建てていきたいというふうに考えておりますので、そこは慎重にいろいろ検討して進めていきたいと考えております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり、校庭の話もありますけれども、教室に４０人詰め込んだら、それは１人当たりの日常的に過ごすスペースがものすごく狭くなるので、やはり、児童・生徒の環境というのを考えると、もう見越して、区独自で少人数学級を進めていくという気構えで、私は、新築・整備のときには、そういった少人数学級も、今からきちんと視野に入れて計画をしていくことが必要だと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"今は改築の計画概要ということなので、この段階でどの辺まで決まっているのかの認識がなくて申し訳ない、今質問するべきかどうか分からないのですけれども、学校のトイレに関して、結構今までいろいろな委員の方から、洋式とか和式とか、洋式がいいという方もあるし、やはり一定和式は残すべきというご意見もあって、トイレはすごく大事かなというふうに思うのですけれども。","respondent":"小林学校施設担当課長","answer":"当然、雨水につきましては、雨水槽を設けて、便所の排水に利用したり、植栽の散水に使用したり、検討して設置するように努力してまいります。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"できるところではぜひ取り入れていただいて、やはり子どもたちが、その意義が分かるような形の設備にしていただきたいなというふうに思います。それから、先ほど１つ忘れました。どうなのでしょう。あったのでしたら、ぜひ継続をお願いしたいのですが、いかがでしょうか。","respondent":"小林学校施設担当課長","answer":"学校については、屋上に降った雨をそのまま集めますので、大きな水槽が必要になってきます。２０トンから３０トン、それは地下のピットに入れて、雨水槽ということで設けるのが一般的です。","id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"大きくというか、学校改築の考え方についてお聞きしたいのですけれども、１年に１回ずつ学校改築が計画として繰り広げられていくのですけれども、それの根拠といいますか、老朽化なのか、人口推移なのか、地域バランスなのか、何かそういったものの考え方があると思うのですけれども、それを教えていただけますか。","respondent":"有馬庶務課長","answer":"改築の進め方、考え方ですけれども、今、松澤委員が言われたとおり、老朽度、これをまず優先はしますけれども、最近では就学人口がかなり急激に増加しており、受け入れていかなければならないということもありますので、就学人口の動向、それから、当然、地域バランスということ。","id":"exchange-006"},{"speaker":"松澤委員","kind":"質問","question":"それで３５人学級になれば、なおさらいろいろ教室も増やさなければいけないという部分について、今、戸越公園の駅前が開発だという話になってくると、そういうところには今度また人が集まってきますよね。そうするとやはり、人口の推移、そういったものと、要は教育委員会との連携というのですか、そういったものというのはしっかりとれているのでしょうか。","respondent":"有馬庶務課長","answer":"まさに学校の規模、改修するに当たってどの程度の教室が今後必要になってくるかですので、今もマンション開発等がどういう状況なのかということは、都市計画課なり、都市開発課なりと情報をやり取りして、いつ頃こういうマンションの計画があります。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問","question":"いろいろな課題も各地域では言われている中で、この辺のプールが見える状況なのかどうかという、まずそこで、目隠しとかそういうものというのはある程度、配慮されたつくりになっているのか、その辺を改めて教えてください。","respondent":"小林学校施設担当課長","answer":"第四日野小学校のご質問にお答えします。いろいろな検討の中で、配置計画などをいろいろやりまして、その中で、この敷地についてはこのような配置が一番ベストといった考え方で計画はしたものです。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問・要望","question":"当然、設計の規制とか制約とかいろいろとある中で、例えば、後に設備として、それは公の学校としてはなかなか制度上難しい部分もあるのかもしれないのですけれども、できる範囲の中で、ご答弁の中にもあったお互いの配慮が、後にいろいろなお声として上がってきたときに、できないと言うよりも、事前にそういう用意もできるということが大事かなと思ったので確認をさせていただきました。","respondent":"有馬庶務課長","answer":"まだ残り半分あるかなというところですが、地元の人にとっては、うちの学校はいつになるのかということにだんだんなってくることは、我々も認識しているところではありますけれども、今のように。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"ですけれども、今の就学前の子どもたちがどこへ行こうかなという声が、今、伺う中で、校舎がきれいであるとか、新しいとかということではない部分の魅力というところで、後地小学校についても、そこのところをしっかりてこ入れをしていただいた中で、校舎もきれいになったというのはあるのですけれども、ぜひ周辺の学校も、人口の関係もあるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"吉田委員","kind":"確認","question":"私が、図面の見方が決して得意ではないので誤解かもしれないのですけれども、縦横で見ると、特別支援学級などが、すごくほかの教室からは行きにくいというか、そういうところに、断面図を見ても、ここだけが体育館の下のところに入り込んでいてというふうに見えるのですけれども、やはり、特別支援学級については考え方がいろいろあって、私たちとしては普通のクラスで障害児もというふうに思うのですが。","respondent":"小林学校施設担当課長、矢部教育総合支援センター長","answer":"いろいろな考え方がありますが、当然、特別支援学級もそれぞれの子どもさんの程度とか、いろいろな考えの設計条件をいただいて、このように少し離すとか、近くにするだとか、委員がおっしゃった交流の場は。教員の考え方もありますので、今、コロナ禍なので、通常でもなかなか難しいのですけれども、交流をこちらとしても推進しておりますので、教室は、あまり高い階ではなく、これは２階になっていますかね。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。保育園までは一緒ですので。いろいろなお考えがあるということは分かりました。ぜひ、今後もいろいろな方のご意見を聞きながら、ただ一方で、やはり社会に出たら一緒に暮らすのですから、その辺のことは教育委員会としても、ぜひ重く見て、学校の設計もしていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-02","title":"令和４年度新入学者の受入枠","agenda":"令和４年度新入学者の受入枠","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"学校施設やハード上の制約もあるのか伺います。私としては、初めから加配の選択というのを前提に想定するというのではなくて、３５人ということの学級量の選択を想定して受入枠というのを作ったほうがいいのではないかと思うのですけれども、いかがでしょうか。","respondent":"勝亦学務課長","answer":"例えば、３０人ですとか３５人と小さく設定しますと、学校のほうで受け入れられますよという人数のほうが減ってしまいますので、まずは学区として入学想定される人数については最大限受け入れるということで、法律どおり設定しているものです。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"何となく分かったような、分からないような。学校の施設的条件を加味した学区のさらなる見直しも必要なのかなとか、区内どこの学校に通っても、この少人数学級というのを享受できる環境を作るべきなのではないかと思うのですけれども、こういう受入枠というのを示すというよりも、そういったところをしっかりと注力すべきなのではないかと思うのですけれども、あわせて伺います。","respondent":"勝亦学務課長","answer":"少人数学級との関係もありますけれども、課題は、いただいたように、あります。ここについては検討できるものは研究していきたいと考えております。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"意見で終わりますけれども、こういう受入枠を提示して選択してもらおうというようなところで、毎年腐心をしているわけですが、そういうところで苦労をするのではなく、やはり、最大の使命である、全ての子どもにとって良質な教育環境、少人数学級をしっかりと環境を整えていくというところに、やはりぜひ、労力と時間と工夫、それを費やしていただきたいなというふうに私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"松本委員","kind":"質問","question":"この受入可能人数ということで、５人余裕を持たせているということだと思うので、それは区内転居者とか、区外転入者ということで、余裕を持たせているということだと思うのですけれども、小学校も中学校も５人ずつということで、一方で小学校は６年で中学校は３年ということで、どの程度の増減が発生するのかというのは、やや、小学校と中学校で違うのかなというふうにも思うのですけれども。","respondent":"勝亦学務課長","answer":"小学校６年間、中学校３年、後期課程３年間ということで、その課程の１年生、７年生でないときの転入ということで、先ほどもありましたけれども、新しいマンションが建つですとか、そういったことを含めて、転入の中には様々な学年の方が入ってまいりますので。","id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"余りそこを詳しくは把握されていないということなのでしょうか。例えばタワーマンションが建つ場合というのは、大幅に増えるというのは分かると思うのですけれども、それ以外の一般的な、状況の中で大体傾向としては、推移で言うと１年間に入ってくるのが大体このぐらいなどというデータはどうなのでしょうか。お願いします。","respondent":"有馬庶務課長","answer":"年間でのデータというと特色がありまして、今、手元にある中で、例えば、昨年の１年生から６年生の人数は１学年こういう人数でした、それが今年の１年生はこういうふうになりましたということで、例えば、令和元年度の４年生が２,５７７人だったけれども。","id":"exchange-017"},{"speaker":"松本委員","kind":"質問・要望","question":"５人という枠、なぜ確認しているかと言ったら、受入れのゆとりの枠が広ければ広いほど選択肢が逆に狭まるというか、入りたくても入れないという子どもたちも生じ得るのかなというところで、そこは５人という、ある意味きりがいい数字にされているので、そこの部分は精査していただきながら、すぐに、では５人ではなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-03","title":"その他のうち、(1)所管質問","agenda":"その他のうち、(1)所管質問","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"区長からのご答弁でしたが、区としてのお考えを求めた質問だったと思うのですけれども、区としてのお考えが結局はっきり聞き取ることができませんでしたので、改めて、学校としてどのようにお考えか、品川区の教育委員会としてどのようにお考えか伺いたいと思います。","respondent":"工藤指導課長","answer":"昨日、７月６日に都教育委員会から最終の意向調査の通知が示されたところです。それに合わせながら、私どもで今示された内容と、またその詳細について、さらに都教育委員会に照会・確認を行っているところでございまして、現在検討をしています。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"都教育委員会がそのような意向調査をするというようなお話は都のほうから伺っていて、前に品川区にお問合せをしたら、まだそのような調査はないということだったのですが、今検討中ということで、例えばそのときに、学校のＰＴＡの意見を聞くとか、学校の先生の負荷を現場ではどの程度考えているかとか、そういうことを考えた上で結論をお出しになるというふうに考えてよろしいのでしょうか。","respondent":"工藤指導課長","answer":"現状では、昨日示された都教育委員会からの情報を基にしながら、教育委員会として、安全・安心に行うというのが前提ですので、それらを含めまして、現在検討を行っているです。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問・要望","question":"一緒に聞いてしまいます。仕様の中身はこの情報だと分からなくて、仕様については教育委員会、所管が決められていると思うのですけれども、入札が進んでいってしまったとして、例えば中止となったときには、それを中止することができるような仕様にされているのかどうか、その辺についても確認させてください。","respondent":"工藤指導課長","answer":"仕様の中身について今お話しできる内容というのがどこまでかというところはありながらなのですけれども、そういったもので、契約のスケジュールが、契約の部署の方で進んでいるというのは、当然、私どもも把握していますので、そういったものがどこで。","id":"exchange-021"},{"speaker":"吉田委員","kind":"質問・要望","question":"１つ、先生方のことについては、ぜひ、よくよく、校長会を通してということですけれども、なるべく現場の直の先生方のお声も聞いていただきたいと思います。気になっているのは、どんどん進んでしまうと、予定価格１,４００万円になっていますよね。ただ、その仕様の中身については所管がきちんと決めていくということですので、そのことについて伺いました。","respondent":"工藤指導課長","answer":"それを進めている中では、その契約の時期、実際にスケジュールがありますけれども、それに伴いながら、様々な検討を今進めている中で、調整が可能な部分、また、どういったところで、場合によってはキャンセル料等がかかる、かからないということもありますので。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問・要望","question":"最後にします。前回、６月の委員会のときも申しましたけれども、都の意向とか、そういうことを勘案しながらということでしたが、ほかの区ではもう既に区として中止を決めたというところもあります。区として決められるのだと思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"子どもの観戦を中止してほしいという区民の声は、現在何件ぐらい届いているのか伺いたいと思います。それと、子どもの安全に関わる重要な問題なので、教育委員会、ＰＴＡ連合会、校長会などには、先ほど校長会という話もありましたけれども、観戦の是非について意見を聞いたのか、聞いたとしたらどのような意見が挙がったのか、それぞれ伺いたいと思います。","respondent":"工藤指導課長","answer":"この実施に関してのところですが、私ども、今回の連携観戦プログラムですが、これまでも行ってきたオリンピック・パラリンピック教育の中で、様々な学習体験を、特にこの品川区の中でも積み重ねてまいりました。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"そこで３点大きく伺いたいのですけれども、今回の連携観戦で観戦を予定している子どもというのは、結局全部で何人なのでしょうか。そういった声も聞いたので伺いますが、会場でスポンサーがペットボトルを配るので水筒の持込みは禁止されているのだというような、そういう話もしている人がいたのですけれども、事実はどうなのでしょうか。その辺のルールがどうなっているのか伺いたいと思います。","respondent":"工藤指導課長","answer":"授業日ということで計画上位置づけられておりますので、そこでは様々なご意見もいただいて議論をしているという訂正をします。あわせまして、予定している人数ですが、区立学校、幼稚園の５歳児も含めまして、約２万２,０００人を予定しているところです。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"細かいところを聞かせていただきたいのですが、ラッシュ時に移動してしまうというか、通勤ラッシュの時間帯に移動してしまうような午前中の観戦というのがあるのかどうか、その辺を後で確認させてください。","respondent":"工藤指導課長","answer":"最長でも１時間程度の観戦しかできないというところを勘案しながら、ラッシュ時を避けることも連絡していくところです。こちらも含めて、今検討の事項に入っているところです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"確認","question":"区が定めたガイドラインでは、今、課長がおっしゃったようなことになっているのですよね。これが、確認なのですけれども、五輪期間まで延長継続された場合は、学校連携観戦は中止するという考えでよろしいのか伺いたいと思います。出席停止と欠席というのは何が違うのかなというのが分からなかったので、それも併せて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、今の時点で、やはり私は、早い時期に決断をすべきだと思います。やはり、事実上できないということもあります。改めて、子どもたちの何を一番重要視するか。もちろん、苦渋の決断になると思うのですけれども、改めて品川区教育委員会として、中止に向けて必要な手続きをするよう求めますけれども、最後にいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-04","title":"区立児童相談所開設に向けた進捗状況","agenda":"区立児童相談所開設に向けた進捗状況","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"細かいところからなのですが、子ども家庭支援センターは、児童相談所の開設後は同じ建物に入る計画なのでしょうか。その辺を確認したいと思います。それと、別紙資料なのですけれども、これは６月２日の検討委員会の議論を経て作成されたものなのか、それとも、当日検討委員会に出された資料なのかというのが分からなかったので、お伺いします。","respondent":"加島児童相談所移管担当課長、山下子ども家庭支援センター長","answer":"こちら、会議の中ではこれ以上のご意見というのはございませんでしたが、区として受け止めておりますところでは、児童相談所と子ども家庭支援センターの役割分担をしてケース対応を行ってまいりますので、そういった進行管理の面。代表者会議である品川区虐待防止ネットワーク推進協議会、実務者会議としまして２層目で地域分科会、こちらは１３地域センターそれぞれで実施をしております。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"子ども家庭支援センターなのですが、これは現在の建物がありますので、そこで別建物として継続していくというお考えなのか伺います。いろいろ視察などしますと、職員がやはり心身ともに疲弊してしまうというケースが多いと伺いました。３つ目は、この運営計画検討委員会が非公開という、委員会にはこういった形で報告があるのですが、その理由は何かというのを伺いたいと思います。","respondent":"山下子ども家庭支援センター長、加島児童相談所移管担当課長","answer":"今、二葉のほうに所在しておりまして、子ども家庭支援センター、設置・運営をしているのですけれども、今後につきましては、状況としましては、新庁舎も含め移転をするような形での考え方をしております。２点目以降の質問にお答えいたします。職員の心身の疲弊につきましては、私どもも視察等で、視察先の職員からそのような状況が起こり得るということを聞いております。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。それは、児童相談所の担当児童福祉司ということになると考えてよろしいのか、伺いたいと思います。もう１つ、最後ですけれども、ある意味、虐待発生を未然に防ぐ家庭支援というのが最も大事なのかなと思うのですね。その点において、児童相談所と子ども家庭支援センターはどのような役割を果たしていくのか、改めてそちらについてのお考えを伺いたいと思います。","respondent":"加島児童相談所移管担当課長、山下子ども家庭支援センター長","answer":"子育て中の保護者の方、子どもご本人、それぞれが悩み事があったときに気軽に相談できるような体制をというところで、現在、子ども家庭支援センターは区が、児童相談所は都が担っておりますけれども、先ほどご説明申し上げましたとおり。今後、（仮称）品川児童相談所ができた場合でも、そちらの調整をしっかり担いまして、運営委員会の委員からもご意見いただきましたけれども、両機関の狭間に落ちるケース等々が発生しないように。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"相談しなかったのが悪いのではというふうにはもちろん言わないでしょうけれども、そういうふうになってはいけないわけで、そういう意味で、児童相談所を置く、独自で作るということで、悩まなくていい、本当に相談してくださいと、行政は味方ですよと言うような体制を作る上でも、ぜひさらに頑張っていただきたいと思いますし、あと、子どもの権利条約という観点が子育て支援に非常に重要というか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"松本委員","kind":"質問","question":"先ほど安藤委員からもお話があった、この運営計画検討委員会が非公開のところなのですけれども、やはりこれは公開はしていくべきだと私は考えています。","respondent":"加島児童相談所移管担当課長","answer":"個別のケースですけれども、確かにそういったケース検討を行っているわけではないのですが、議題を示す中で、委員のほうから過去に関わったケースですとか、あとは理事者のほうからそういった発言が出ることもありますので、今の段階では非公開としています。","id":"exchange-033"},{"speaker":"松本委員","kind":"意見","question":"今、調べたところだと、恐らくこの検討委員会が開かれていること自体は特にウェブサイトに記載がないようにも思われるのですが、そのあたりも、現状どういうふうに区民に対する公開がされているのかというところも踏まえてご答弁をお願いいたします。","respondent":"加島児童相談所移管担当課長","answer":"２点目からのお答えになるかもしれませんが、現在、有識者会議につきましては、確かに委員ご指摘のとおり、ホームページ等には掲載しておりません。","id":"exchange-034"},{"speaker":"松本委員","kind":"質問","question":"委員長という単語が重複するので、なかなか。私の頭の中のことですが。例えば、弁護士１名となっていますけれども、私も弁護士ですが、弁護士と言っても専門性はいろいろなのですね。そういう意味では、やはりきちんと委員の構成、委員の専門性とか、どういう方たちを選任しているのかというところはきちんと公開されたほうがいいのではないかと思いますが、その点はいかがでしょうか。","respondent":"加島児童相談所移管担当課長","answer":"現在、この委員についても構成、お名前等、公開はされておりませんけれども、この委員会を通じて区立児童相談所設置・運営計画を完成していくに当たり、有識者のお名前等も公開していけるよう、会議の中で調整を図ってまいりたいという。","id":"exchange-035"},{"speaker":"松本委員","kind":"質問・要望","question":"ありがとうございました。ちなみになのですが、この６月２日に行われた会議ですけれども、会議の開催時間、どのくらい時間が使われたのかというところもお願いいたします。","respondent":"加島児童相談所移管担当課長","answer":"会議の開催時間について、６月２日は１５時から始めまして、１時間半強ほどご意見をいただいたところです。","id":"exchange-036"},{"speaker":"松本委員","kind":"質問・要望","question":"最後は本当に要望で。できるだけ、このあたりの情報というのは公開していただきたいと考えていますので、引き続き、ここは検討委員会の委員長と相談していただきながら、在り方を考えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのご意見が、区としての考え方に反映されたかをフィードバックする機会は、もう最後の案のところでしかないのでしょうか。次のことになって、これからということだと思いますけれども、これからということであるならば、ぜひそういうことをここで深く議論していただきたいと思うのですけれども、その辺についていかがでしょうか。","respondent":"加島児童相談所移管担当課長","answer":"権利擁護の部分につきまして、これから議題としてどのような提案の仕方をしていくか委員長と話しますので、まだまとまったものがあるわけではないのですけれども、一般質問等でいただいたアドボケイト制度、意見表明支援の件につきましても、今現在。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひそのように進めていただきたいと思います。最後に、先ほどの松本委員からのご意見がありましたので、一応、意見だけ言わせていただきたいのですけれども、やはり会議の公開というのは進められるべきかなというふうに思います。ですので、ぜひそこは、ご懸念がおありでしたら一歩ずつでもいいので進めていっていただきたいと思います。最後は意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"松澤委員","kind":"質問","question":"２層性というか、併存型というのは、これはやはり連携をとるのがとても難しいという課題が多く、私も勉強会などに行かせてもらうと、お聞きしています。そういった中で、やらないということはないでしょうけれども、どういった部分でそういう連携評価をいうのを図っていくのかというのを教えてください。","respondent":"加島児童相談所移管担当課長","answer":"世田谷区のほうでは、両機関の共通の認識といたしまして、リスクアセスメントの基準を明確にしていたり、両機関で定期的に情報共有する会議を合同開催するなどの機会を設けていると聞いておりますので、私どももそういったものを参考にしながら。","id":"exchange-040"},{"speaker":"松澤委員","kind":"質問","question":"先行事例の世田谷区さんなど、そういうのを見るのはとてもいいことだと思いますので、お願いいたします。特別区での設置になると、今までは東京都が管理していますので、東京都がやっている中で、そういう情報が全くつながらなくなったり、要は都と区の連携というのですか。","respondent":"加島児童相談所移管担当課長、山下子ども家庭支援センター長","answer":"先行区の例になってしまうのですけれども、都と区で同行で訪問していたりというような取組を行っていると聞いております。我が区においても、その取組につきましては実施に向けて検討が必要と考えているものです。私ども子ども家庭支援センターとしましては、実際に一時保護に至った後、また地域に戻られてくるときに、その児童であったり、またその保護者の方々を支援するという役割がありますので、今現在、私どもとしましては。","id":"exchange-041"},{"speaker":"松澤委員","kind":"質問","question":"最後に、職員の異動と言いますか、児童相談所の職員というのは、行政の中にあると、ある程度、数年たてば異動してしまう、そういう流れだと思うのですよね。ただ、ここがすごく課題だと。そうすると、職員の異動の周期、これは今話すことではないのかもしれないのですけれども、そういった部分も少し長く見るということも検討の１つなのかなと思っているのですけれども、その辺はどうでしょうか。","respondent":"加島児童相談所移管担当課長","answer":"そういったスーパーバイザーをこの区職員の中から輩出していくためにも、長期的な育成とともに、先ほど申し上げました、様々な職場で業務経験を蓄積していくということ、少し対立に見えるかもしれませんが、そういった道を両立させていくようなことも、今後。","id":"exchange-042"},{"speaker":"つる委員","kind":"提案","question":"進捗状況ということで、ありがとうございました。会派としても、福岡などいろいろな先行自治体の事例も視察させていただきながら提案もさせていただいて、いろいろな人材の面であるとか、そういったところも伺いながら、また提案をさせていただいて、今、こういう進捗を教えていただきました。","respondent":"加島児童相談所移管担当課長","answer":"３つ目といたしましては、最後になりますが、地域、関係機関、庁内関係部署、区として顔の見える関係がありますので、そういったつながりを生かしながら、緊急対応の前段階から、子どもと家庭に支援が届くよう、児童虐待の防止・早期発見をより強化していけると考えております。","id":"exchange-043"},{"speaker":"つる委員","kind":"質問","question":"ありがとうございました。そういう意味では、この別紙２の図もありますけれども、これをさらにもう一重、二重、重ねていくのがその重層だと思うのですが、このイメージで言うと、重層と児童相談所、子ども家庭支援センターの役割分担と言いましょうか、連携の在り方というのですか。このあたりというのはどういうイメージを今後持って進めていくのか教えてください。","respondent":"加島児童相談所移管担当課長","answer":"そういったものとして、重層的支援体制整備事業のネットワークの中にかかってくるご家庭、子どもに対してきちんと児童相談所が掲げている業務の役割を果たしていけるよう、今後、庁内で意見、認識を共有してまいりたいというふうに考えております。","id":"exchange-044"},{"speaker":"つる委員","kind":"提案","question":"個人的には、この重層的支援体制整備事業については、特別委員会を設けて本当に多角的な議論をしていかなければいけないなというふうに、今年度、会派の中で提案させていただいた部分もあるのですけれども、今ご答弁いただいて、本当に複雑に絡み合ったものを、適切に、まさに１人１人に合った形で、制度に人を合わせていくのではなくて、困っている人に制度を当てはめていくと言いましょうか、形作っていく。","respondent":"加島児童相談所移管担当課長、山下子ども家庭支援センター長","answer":"児童精神科医、非常に母数が少ないので、確保が難しいところですけれども、職員のメンタルケアにも関わっていただけるような方をこちらできちんと確保してまいりたいと考えているところです。今現在の時点で、虐待の通告の件数等々、相談の件数等々というのは伸びを示している状況ですけれども、やはりそちらの体制を整備することで、児童相談所の円滑な運営につながる部分もありますので、子ども家庭支援センターの役割として。","id":"exchange-045"},{"speaker":"つる委員","kind":"質問・要望","question":"ありがとうございました。人材のところについては、本当に大事な部分かなと思います。ＯＪＴではないですけれども、やれるような、それだけの課題が濃いと思うのですね。愛称がいいか、悪いかという、両方側面があると思うのですけれども、例えば品川区でやっていくときに、この子ども家庭支援センターも含めてなのでしょうけれども、そういう愛称みたいなものをつけていく考えというのはどうでしょうか。","respondent":"加島児童相談所移管担当課長","answer":"江戸川区の児童相談所のほうでも、区民公募を図りまして、はあとポートという愛称をつけておりますので、そういった試みについても、今後区のほうで研究してまいりたいというふうに考えております。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/186280?Template=document&Id=5038#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":45033,"voices":128}}]);
